class TestOrdersAgenticTaskRuntime(IsolatedDbTestCase):
    def test_pending_answer_preserves_requested_account_environment_scope(
        self,
    ) -> None:
        state = AgentSessionState(
            goal=(
                "Siparisleri guncelle; hangi hesap ve ortami kullandigini "
                "acikca soyle."
            ),
            active_domain="orders",
            status="pending_approval",
        )
        state.active_entities["turn_interpretation"] = {
            "requested_fields": ["scope"],
        }
        state.completed_steps = [
            AgentTaskStep(
                index=1,
                prompt="Hesap ve ortam bilgisini al.",
                status="completed",
                tool_names=["orders.query"],
                verification_status="verified",
                result_data={
                    "tool_result": {
                        "account_scopes": [
                            {
                                "api_account_id": 1,
                                "account_id": "784195",
                                "store_name": "MDB",
                                "platform": "TRENDYOL",
                                "environment": "production",
                            }
                        ]
                    }
                },
            ),
            AgentTaskStep(
                index=2,
                prompt="Senkronizasyonu hazirla.",
                status="completed",
                tool_names=["orders.fetch.prepare"],
                verification_status="verified",
                result_message=(
                    "Onay gerekiyor: exact hesap kapsaminda siparis "
                    "senkronizasyonu hazirlandi."
                ),
                result_data={
                    "answer": (
                        "Onay gerekiyor: exact hesap kapsaminda siparis "
                        "senkronizasyonu hazirlandi."
                    )
                },
            ),
        ]
        action = PendingActionSnapshot.from_action(
            {
                "action_type": "orders.get_orders_from_companies",
                "status": "pending_approval",
                "record_refs": [
                    RecordRef(
                        domain="account",
                        record_type="marketplace_account",
                        record_id="1",
                        source="prepared_action",
                        account="unknown",
                        environment="unknown",
                    ).to_dict()
                ],
                "selected_record_count": 1,
                "preview_item_count": 1,
                "execute_input_count": 1,
            }
        ).to_action(
            {
                "action_type": "orders.get_orders_from_companies",
                "status": "pending_approval",
            }
        )
        state.pending_actions = [action]
        state.active_pending_action_id = str(action["action_id"])

        answer = task_runtime._pending_task_answer(state)

        self.assertIn("Kapsam: MDB (TRENDYOL / production).", answer)
        self.assertIn("Onay gerekiyor", answer)
        self.assertIn("API istegi", answer)
        self.assertNotIn("Hedef kayitlar:\n1. 1", answer)

    @staticmethod
    def _quota_limited_planner():
        calls = {"count": 0}

        def planner(_prompt: str) -> str:
            calls["count"] += 1
            planner.resource_plan.update(
                {
                    "requested_model": "gemini-3.5-flash",
                    "actual_model": "",
                    "model_invocation_attempted": True,
                    "invocation_error_reason": "http_429",
                    "quota_scope": "project",
                    "fallback_blocked_reason": "provider_quota",
                    "normalized_error_history": [
                        {
                            "provider_code": "gemini",
                            "category": "quota",
                            "retryable": True,
                            "quota_scope": "project",
                            "status_code": 429,
                            "safe_message": (
                                "Provider kota veya rate-limit yanıtı verdi."
                            ),
                            "model_fallback_allowed": False,
                        }
                    ],
                }
            )
            raise RuntimeError("provider response intentionally redacted")

        planner.runtime_name = "gemini_chat"
        planner.model_name = "gemini-3.5-flash"
        planner.resource_plan = {
            "provider_code": "gemini",
            "requested_model": "gemini-3.5-flash",
            "allow_model_fallback": False,
        }
        return planner, calls

