    def test_explicit_multi_signal_fields_survive_typed_model_omission(self) -> None:
        def planner(_prompt: str) -> str:
            return json.dumps(
                {
                    "mode": "inspect",
                    "domain": "orders",
                    "objective": "Mağaza sipariş operasyonlarını özetle",
                    "intent_kind": "data_read",
                    "requested_fields": ["scope"],
                    "entity": "return_claim",
                    "metric": "summary",
                    "status_scope": "all",
                    "period": "all",
                    "freshness": "local_snapshot",
                    "reason": "genel özet",
                    "requires_clarification": False,
                    "clarification": "",
                }
            )

        result = task_runtime.interpret_agent_turn(
            "Tamam, şimdi mağazamın durum dağılımını, kargoya hazır adedi, ciroyu ve "
            "operasyon risklerini birlikte değerlendir",
            planner_client=planner,
        )

        self.assertTrue(result.success, result.message)
        fields = set((result.data or {}).get("requested_fields") or [])
        self.assertEqual(
            fields,
            {"scope", "status", "count", "amount", "currency", "risk"},
        )
        corrections = set((result.data or {}).get("semantic_corrections") or [])
        self.assertIn("explicit_count_requested_field_retained", corrections)
        self.assertIn("explicit_status_requested_field_retained", corrections)
        self.assertIn("explicit_amount_requested_field_retained", corrections)
        self.assertIn("explicit_risk_requested_field_retained", corrections)
        self.assertIn(
            "monetary_amount_currency_dimension_added",
            corrections,
        )

    def test_local_business_projection_canonicalizes_conversation_drift_to_data_read(
        self,
    ) -> None:
        def planner(_prompt: str) -> str:
            return json.dumps(
                {
                    "mode": "explain",
                    "domain": "orders",
                    "objective": (
                        "Onceki ciro sonucunun para birimi ve hesap kapsamını acikla"
                    ),
                    "intent_kind": "conversation",
                    "request_shape": "scalar",
                    "requested_fields": ["amount", "store", "scope"],
                    "entity": "order",
                    "metric": "detail",
                    "status_scope": "all",
                    "record_scope": "all_matching",
                    "period": "all",
                    "freshness": "local_snapshot",
                    "information_source": "local_business_data",
                    "operation_policy": "allow_new_operations",
                    "reason": "Yerel siparis ozetinin meta verileri soruluyor.",
                    "requires_clarification": False,
                    "clarification": "",
                },
                ensure_ascii=False,
            )

        result = task_runtime.interpret_agent_turn(
            "bu cironun birimini ve hesap kapsamini soyler misin?",
            planner_client=planner,
            history=[
                {
                    "role": "assistant",
                    "content": "Toplam ciro 502.518,01 birimdir.",
                }
            ],
        )

        self.assertTrue(result.success, result.message)
        interpretation = dict(result.data or {})
        self.assertEqual(interpretation.get("mode"), "inspect")
        self.assertEqual(interpretation.get("intent_kind"), "data_read")
        self.assertEqual(
            set(interpretation.get("requested_fields") or []),
            {"amount", "currency", "store", "scope"},
        )
        contract = dict(interpretation.get("semantic_contract") or {})
        self.assertEqual(contract.get("entity"), "order")
        self.assertEqual(contract.get("metric"), "amount")
        self.assertEqual(
            contract.get("metric_requirements"),
            [ORDER_REVENUE_TOTAL_METRIC],
        )
        corrections = set(
            interpretation.get("semantic_corrections") or []
        )
        self.assertIn(
            "business_evidence_source_requires_inspect",
            corrections,
        )
        self.assertIn(
            "monetary_amount_currency_dimension_added",
            corrections,
        )
        self.assertIn(
            "population_amount_detail_metric_to_amount",
            corrections,
        )

    def test_numeric_metric_roles_are_not_misclassified_as_order_identifiers(
        self,
    ) -> None:
        non_identifiers = (
            "Bu 502518.01 rakami hangi para biriminde?",
            "Toplam ciro 502.518,01 TRY.",
            "Yuzde 502518 oranini acikla.",
            "startDate 1597759208000 zaman damgasini kullan.",
        )
        for message in non_identifiers:
            with self.subTest(message=message):
                self.assertFalse(task_runtime._goal_has_order_identifier(message))
                self.assertEqual(
                    task_runtime._order_identifiers_from_goal(message),
                    [],
                )

        exact_messages = {
            "99000000001": ["99000000001"],
            "99000000001 numarali siparisin tutari nedir?": ["99000000001"],
            "ORD-ABC_123 siparisini getir": ["ORD-ABC-123"],
        }
        for message, expected in exact_messages.items():
            with self.subTest(message=message):
                self.assertTrue(task_runtime._goal_has_order_identifier(message))
                self.assertEqual(
                    task_runtime._order_identifiers_from_goal(message),
                    expected,
                )

