    def test_r351_list_wrapped_array_dependency_is_canonicalized_and_accepted(
        self,
    ) -> None:
        goal = (
            "Bu ürünü baz alıp son 3 haftada kaç farklı siparişte kaç adet "
            "satıldığını ve brüt satış tutarını hesapla; dosya üretme."
        )
        interpretation = {
            "mode": "inspect",
            "domain": "orders",
            "intent_kind": "data_read",
            "request_shape": "focused_analysis",
            "requested_fields": [
                "item_sales_order_count",
                "item_sales_quantity",
                "item_sales_amount",
                "currency",
            ],
            "semantic_contract": {
                "entity": "order",
                "metric": "summary",
                "status_scope": "all",
                "record_scope": "all_matching",
                "period": "last_21_days",
                "projection": [
                    "item_sales_order_count",
                    "item_sales_quantity",
                    "item_sales_amount",
                    "currency",
                ],
                "metric_requirements": [ORDER_ITEM_SALES_SUMMARY_METRIC],
                "contextual_item_identity_required": True,
            },
        }
        model_plan = {
            "steps": [
                {
                    "id": "context_product_identity",
                    "operation_id": "orders.product_public_identities",
                    "arguments": {"order_numbers": ["ORD-CONTEXT-3"]},
                    "depends_on": [],
                    "objective": "Resolve the selected order's public product identity.",
                    "expected_evidence": ["product_identities"],
                },
                {
                    "id": "context_product_sales",
                    "operation_id": "orders.item_sales_summary",
                    "arguments": {
                        "period": "last_21_days",
                        # R351 exact provider dialect: the operation schema
                        # says array, so the graph binding was wrapped once.
                        "product_identities": [
                            {
                                "$from_step": "context_product_identity",
                                "path": "tool_result.product_identities",
                            }
                        ],
                    },
                    "depends_on": ["context_product_identity"],
                    "objective": "Aggregate the selected product's 21-day sales.",
                    "expected_evidence": [
                        "order_count",
                        "total_quantity",
                        "total_gross_amount",
                    ],
                },
            ]
        }
        tools = available_tools()
        candidates = {
            operation_id: tools[operation_id]
            for operation_id in (
                "orders.product_public_identities",
                "orders.item_sales_summary",
            )
        }

        with patch(
            "AI.processors.task_runtime._planner_operation_candidates",
            return_value=candidates,
        ):
            step_ids, metadata = task_runtime._orders_task_plan(
                goal,
                planner_client=lambda _prompt: json.dumps(
                    model_plan,
                    ensure_ascii=False,
                ),
                max_steps=8,
                typed_context=[
                    {
                        "kind": "order_selection",
                        "order_numbers": ["ORD-CONTEXT-3"],
                    }
                ],
                turn_interpretation=interpretation,
            )

        self.assertEqual(metadata.get("source"), "llm_direct", metadata)
        self.assertEqual(
            step_ids,
            ["context_product_identity", "context_product_sales"],
        )
        specs = list(metadata.get("step_specs") or [])
        self.assertEqual(
            (specs[1].get("arguments") or {}).get("product_identities"),
            {
                "$from_step": "context_product_identity",
                "path": "tool_result.product_identities",
            },
        )
        self.assertIs(metadata.get("contextual_item_sales_bound"), True)

