    def test_status_ratio_verifier_accepts_only_target_status_and_inputs(self) -> None:
        state = self._completed_response_state(
            goal=(
                "Teslim edilen siparislerin toplam icindeki payi yuzde kac? "
                "Kullandigin iki sayiyi da goster."
            ),
            operation="orders.summary",
            tool_result={
                "total_orders": 3112,
                "status_counts": {
                    "Cancelled": 110,
                    "Delivered": 2957,
                    "UnDeliveredAndReturned": 44,
                    "UnDelivered": 1,
                },
                "status_rates": {
                    "Cancelled": 3.53,
                    "Delivered": 95.02,
                    "UnDeliveredAndReturned": 1.41,
                    "UnDelivered": 0.03,
                },
            },
            authoritative_answer=(
                "Delivered 2957 / toplam 3112 siparis = %95.02."
            ),
            requested_fields=["count", "status", "ratio"],
        )
        state.active_entities["turn_interpretation"]["request_shape"] = (
            "focused_analysis"
        )
        state.active_entities["turn_interpretation"]["semantic_contract"] = {
            "entity": "order",
            "metric": "ratio",
            "status_scope": "delivered",
            "record_scope": "all_matching",
            "period": "all",
            "projection": ["count", "status", "ratio"],
            "metric_requirements": [
                ORDER_TOTAL_COUNT_METRIC,
                ORDER_STATUS_DISTRIBUTION_METRIC,
            ],
        }

        answer = (
            "Delivered: 2957 / toplam 3112 siparis = %95.02. "
            "Siparislerin %95.02'si teslim edilmis."
        )
        verified = response_verifier.verify_response_projection(
            answer,
            state,
            source="model_candidate",
        )

        self.assertTrue(verified.success, f"{answer}\n{verified.data}")
        fallback = response_verifier.project_fallback_response(state, "")
        self.assertIn("2957", fallback)
        self.assertIn("3112", fallback)
        self.assertIn("95.02", fallback)
        self.assertNotIn("Cancelled", fallback)
        self.assertNotIn("502518", fallback)

        missing_input = response_verifier.verify_response_projection(
            "Teslim edilenlerin orani %95.02.",
            state,
            source="model_candidate",
        )
        self.assertFalse(missing_input.success)
        reason_codes = (
            ((missing_input.data or {}).get("response_verification") or {}).get(
                "reason_codes"
            )
            or []
        )
        self.assertIn("status_ratio_numerator_projection_missing", reason_codes)
        self.assertIn("status_ratio_denominator_projection_missing", reason_codes)

    def test_combined_status_ratio_has_typed_members_and_verified_calculation(
        self,
    ) -> None:
        message = (
            "Teslim edilemeyenlerle iade donenleri birlikte dusunursek "
            "toplam kac siparis ve yuzde kac ediyor? Hesabi da goster."
        )
        interpreted = task_runtime.interpret_agent_turn(
            message,
            planner_client=lambda _prompt: json.dumps(
                {
                    "mode": "inspect",
                    "domain": "orders",
                    "objective": "Iki siparis durumunun birlesik oranini hesapla",
                    "intent_kind": "data_read",
                    "request_shape": "focused_analysis",
                    "requested_fields": ["count", "status", "ratio"],
                    "entity": "return_claim",
                    "metric": "summary",
                    "status_scope": "all",
                    "record_scope": "all_matching",
                    "period": "all",
                    "freshness": "local_snapshot",
                    "information_source": "unspecified",
                    "operation_policy": "allow_new_operations",
                    "reason": "Birlesik durum orani",
                    "requires_clarification": False,
                    "clarification": "",
                }
            ),
        )

        self.assertTrue(interpreted.success, interpreted.message)
        interpretation = dict(interpreted.data or {})
        contract = dict(interpretation.get("semantic_contract") or {})
        self.assertEqual(contract.get("entity"), "order")
        self.assertEqual(contract.get("metric"), "ratio")
        self.assertEqual(contract.get("status_scope"), "all")
        self.assertEqual(
            contract.get("status_members"),
            ["undelivered_and_returned", "undelivered"],
        )
        self.assertEqual(
            interpretation.get("information_source"),
            "local_business_data",
        )

        state = self._completed_response_state(
            goal=message,
            operation="orders.summary",
            tool_result={
                "total_orders": 3112,
                "status_counts": {
                    "Cancelled": 110,
                    "Delivered": 2957,
                    "UnDeliveredAndReturned": 44,
                    "UnDelivered": 1,
                },
            },
            authoritative_answer=(
                "UnDelivered 1 + UnDeliveredAndReturned 44 = 45; "
                "45 / toplam 3112 = %1.45."
            ),
            requested_fields=["count", "status", "ratio"],
        )
        state.active_entities["turn_interpretation"] = interpretation

        answer = (
            "UnDelivered 1 + UnDeliveredAndReturned 44 = 45; "
            "45 / toplam 3112 siparis = %1.45."
        )
        verified = response_verifier.verify_response_projection(
            answer,
            state,
            source="model_candidate",
        )
        self.assertTrue(verified.success, verified.data)

        natural_turkish = (
            "Teslim edilemeyen 1 siparis ile iade donen 44 siparisin "
            "toplami 45 siparis. 45 / toplam 3112 siparis = %1.45."
        )
        natural_verified = response_verifier.verify_response_projection(
            natural_turkish,
            state,
            source="model_candidate",
        )
        self.assertTrue(natural_verified.success, natural_verified.data)

        fallback = response_verifier.project_fallback_response(state, "")
        self.assertIn("UnDelivered 1", fallback)
        self.assertIn("UnDeliveredAndReturned 44", fallback)
        self.assertIn("45", fallback)
        self.assertIn("3112", fallback)
        self.assertIn("1.45", fallback)

        missing_component = response_verifier.verify_response_projection(
            "Bu iki durum toplam 45 / 3112 = %1.45.",
            state,
            source="model_candidate",
        )
        self.assertFalse(missing_component.success)
        codes = (
            ((missing_component.data or {}).get("response_verification") or {}).get(
                "reason_codes"
            )
            or []
        )
        self.assertIn("status_projection_missing:UnDelivered", codes)
        self.assertIn("status_projection_missing:UnDeliveredAndReturned", codes)

