    def test_three_member_status_ratio_preempts_malformed_generic_formula(
        self,
    ) -> None:
        message = (
            "Yeni sorgu yok; iptal ve iki teslim edilememe grubunu birleştir, "
            "adediyle toplam içindeki yüzdesini işlemiyle ver."
        )
        interpreted = task_runtime.interpret_agent_turn(
            message,
            planner_client=lambda _prompt: json.dumps(
                {
                    "mode": "inspect",
                    "domain": "orders",
                    "objective": "Üç sipariş durumunu topla ve oranını hesapla",
                    "intent_kind": "data_read",
                    "request_shape": "focused_analysis",
                    "requested_fields": [
                        "count",
                        "ratio",
                        "calculation",
                        "returns",
                    ],
                    "entity": "order",
                    "metric": "derived",
                    "status_scope": "all",
                    "record_scope": "all_matching",
                    "period": "all",
                    "freshness": "local_snapshot",
                    "information_source": "local_business_data",
                    "operation_policy": "allow_new_operations",
                    "derived_calculation": {
                        "operator": "percentage",
                        "operands": [{"ref": "orders.status_count"}],
                        "result_kind": "percentage",
                        "precision": 2,
                        "show_work": True,
                    },
                    "reason": "Birleşik durum oranı",
                    "requires_clarification": False,
                    "clarification": "",
                },
                ensure_ascii=False,
            ),
        )

        self.assertTrue(interpreted.success, interpreted.message)
        interpretation = dict(interpreted.data or {})
        self.assertEqual(
            set(interpretation.get("requested_fields") or []),
            {"count", "status", "ratio"},
        )
        self.assertIn(
            "status_set_ratio_not_generic_derived_calculation",
            interpretation.get("semantic_corrections") or [],
        )
        self.assertNotEqual(
            interpretation.get("decision_path"),
            "typed_canonical_read_recovery",
        )
        self.assertEqual(interpretation.get("mode"), "inspect")
        self.assertEqual(interpretation.get("intent_kind"), "data_read")
        self.assertEqual(
            interpretation.get("operation_policy"),
            "existing_observations_only",
        )
        contract = dict(interpretation.get("semantic_contract") or {})
        self.assertEqual(contract.get("metric"), "ratio")
        self.assertEqual(
            set(contract.get("status_members") or []),
            {"cancelled", "undelivered", "undelivered_and_returned"},
        )
        self.assertEqual(
            contract.get("metric_requirements"),
            [
                ORDER_TOTAL_COUNT_METRIC,
                ORDER_STATUS_DISTRIBUTION_METRIC,
            ],
        )

        state = self._completed_response_state(
            goal=message,
            operation="orders.summary",
            tool_result={
                "total_orders": 3112,
                "status_counts": {
                    "Cancelled": 110,
                    "Delivered": 2957,
                    "UnDeliveredAndReturned": 44,
                    "UnDelivered": 1,
                },
            },
            authoritative_answer="Sipariş durum özeti hazır.",
            requested_fields=["count", "status", "ratio"],
        )
        state.active_entities["turn_interpretation"] = interpretation

        answer = (
            "Cancelled 110 + UnDelivered 1 + "
            "UnDeliveredAndReturned 44 = 155; "
            "155 / toplam 3112 siparis = %4.98."
        )
        verified = response_verifier.verify_response_projection(
            answer,
            state,
            source="model_candidate",
        )
        fallback = response_verifier.project_fallback_response(state, "")
        fallback_verified = response_verifier.verify_response_projection(
            fallback,
            state,
            source="verified_fallback",
        )

        self.assertTrue(verified.success, verified.data)
        self.assertIn("155", fallback)
        self.assertIn("3112", fallback)
        self.assertIn("4.98", fallback)
        self.assertTrue(fallback_verified.success, fallback_verified.data)

