    def test_nonfinal_status_summary_executes_only_scoped_domain_operation(self) -> None:
        now_ms = int(datetime.now(TZ_GMT3).timestamp() * 1000)
        self._insert_order(
            "ORD-NONFINAL-READY",
            now_ms,
            package_id=91_001,
            status="ReadyToShip",
        )
        self._insert_order(
            "ORD-NONFINAL-SHIPPED",
            now_ms + 1_000,
            package_id=91_002,
            status="Shipped",
        )
        self._insert_order(
            "ORD-NONFINAL-DELIVERED",
            now_ms + 2_000,
            package_id=91_003,
            status="Delivered",
        )

        planner_prompts: list[str] = []

        def planner(prompt: str) -> str:
            planner_prompts.append(prompt)
            if prompt.startswith("Orders domain agent task plan"):
                return json.dumps(
                    {
                        "steps": [
                            {
                                "id": "unfinished_fulfillment_summary",
                                "operation_id": "orders.nonfinal_summary",
                                "arguments_json": "{}",
                                "depends_on": [],
                                "objective": (
                                    "Terminal olmayan siparisleri durumlarina "
                                    "gore ozetle"
                                ),
                                "expected_evidence": [
                                    "total_count",
                                    "status_counts",
                                    "final_statuses",
                                ],
                            }
                        ]
                    }
                )
            if prompt.startswith("Orders agent task final cevabi yaz"):
                return (
                    "Sevkiyat sureci tamamlanmamis 2 siparis var. "
                    "Siparis durumlari: ReadyToShip 1, Shipped 1."
                )
            return json.dumps(
                {
                    "decision": "complete",
                    "reason": "Scoped nonfinal count and status evidence observed.",
                    "clarification": "",
                    "steps": [],
                }
            )

        result = run_agent_task(
            (
                "Hazir yoksa sevkiyat sureci henuz tamamlanmamis "
                "siparisleri durumlarina gore ozetle"
            ),
            db_name=self.db_path,
            planner_client=planner,
            turn_interpretation={
                "mode": "inspect",
                "domain": "orders",
                "objective": (
                    "Terminal olmayan siparisleri durumlarina gore ozetle"
                ),
                "intent_kind": "data_read",
                "request_shape": "broad_analysis",
                "requested_fields": ["status", "count"],
                "requires_clarification": False,
                "valid": True,
                "decision_path": "typed_model_turn_interpretation",
                "semantic_contract": {
                    "entity": "order",
                    "metric": "summary",
                    "status_scope": "nonfinal",
                    "record_scope": "all_matching",
                    "period": "all",
                    "freshness": "local_snapshot",
                    "projection": ["status", "count"],
                    "metric_requirements": [
                        ORDER_NONFINAL_COUNT_METRIC,
                        ORDER_NONFINAL_STATUS_DISTRIBUTION_METRIC,
                    ],
                },
            },
        )

        self.assertTrue(result.success, f"{result.message} | {result.data}")
        state = dict((result.data or {}).get("state") or {})
        self.assertEqual(state.get("status"), "complete")
        self.assertEqual(
            [
                tool_name
                for step in state.get("completed_steps") or []
                for tool_name in step.get("tool_names") or []
            ],
            ["orders.nonfinal_summary"],
        )
        answer = str((result.data or {}).get("answer") or result.message)
        self.assertIn("2", answer)
        self.assertIn("ReadyToShip", answer)
        self.assertIn("Shipped", answer)
        self.assertNotIn("Delivered", answer)
        self.assertNotIn("ciro", answer.casefold())
        self.assertTrue(
            any(
                prompt.startswith("Orders domain agent task plan")
                for prompt in planner_prompts
            )
        )

    def test_nonfinal_contract_rejects_global_summary_and_repairs_before_execution(self) -> None:
        responses = iter(
            [
                {
                    "steps": [
                        {
                            "id": "wrong_global_summary",
                            "operation_id": "orders.summary",
                            "arguments": {"period": "all"},
                            "depends_on": [],
                            "objective": "Butun siparis gecmisini ozetle",
                            "expected_evidence": [
                                "total_orders",
                                "status_counts",
                                "estimated_revenue",
                            ],
                        }
                    ]
                },
                {
                    "steps": [
                        {
                            "id": "scoped_nonfinal_summary",
                            "operation_id": "orders.nonfinal_summary",
                            "arguments": {},
                            "depends_on": [],
                            "objective": (
                                "Yalniz terminal olmayan siparisleri ozetle"
                            ),
                            "expected_evidence": [
                                "total_count",
                                "status_counts",
                                "final_statuses",
                            ],
                        }
                    ]
                },
            ]
        )
        tools = available_tools()
        candidates = {
            operation_id: tools[operation_id]
            for operation_id in (
                "orders.summary",
                "orders.nonfinal_summary",
            )
        }
        interpretation = {
            "mode": "inspect",
            "domain": "orders",
            "intent_kind": "data_read",
            "request_shape": "broad_analysis",
            "requested_fields": ["status", "count"],
            "semantic_contract": {
                "entity": "order",
                "metric": "summary",
                "status_scope": "nonfinal",
                "record_scope": "all_matching",
                "period": "all",
                "projection": ["status", "count"],
                "metric_requirements": [
                    ORDER_NONFINAL_COUNT_METRIC,
                    ORDER_NONFINAL_STATUS_DISTRIBUTION_METRIC,
                ],
            },
        }

        with patch(
            "AI.processors.task_runtime._planner_operation_candidates",
            return_value=candidates,
        ):
            step_ids, meta = task_runtime._orders_task_plan(
                (
                    "Hazir yoksa sevkiyat sureci tamamlanmamis siparisleri "
                    "durumlarina gore ozetle"
                ),
                planner_client=lambda _prompt: json.dumps(next(responses)),
                max_steps=8,
                turn_interpretation=interpretation,
            )

        self.assertEqual(meta.get("source"), "llm_direct_repaired")
        self.assertTrue(meta.get("planner_repair_accepted"))
        self.assertIn(
            "typed_read_metric_requirement_missing:"
            + ORDER_NONFINAL_COUNT_METRIC,
            meta.get("initial_plan_reason_codes") or [],
        )
        self.assertIn(
            "typed_read_metric_requirement_missing:"
            + ORDER_NONFINAL_STATUS_DISTRIBUTION_METRIC,
            meta.get("initial_plan_reason_codes") or [],
        )
        self.assertEqual(step_ids, ["scoped_nonfinal_summary"])
        self.assertEqual(
            [
                row.get("operation_id")
                for row in list(meta.get("step_specs") or [])
            ],
            ["orders.nonfinal_summary"],
        )

