    def test_model_authored_verified_fallback_projection_is_accepted(self) -> None:
        state = {
            "active_entities": {
                "task_plan": {
                    "source": "llm_direct",
                    "planner_invoked": True,
                    "llm_step_ids": ["step_1"],
                    "deterministic_business_steps_inserted": False,
                    "semantic_inserted_step_ids": [],
                    "step_specs": [
                        {
                            "id": "step_1",
                            "operation_id": "orders.full_context",
                        }
                    ],
                },
                "response_synthesis": {
                    "final_source": "deterministic_verified_projection",
                    "final_projection_verified": False,
                    "fallback_projection_verified": True,
                },
            },
            "completed_steps": [
                {"tool_names": ["orders.full_context"]}
            ],
        }

        accepted = task_runtime.model_authored_projection_acceptance(
            state,
            final_model_response_received=True,
        )
        no_final_model_response = (
            task_runtime.model_authored_projection_acceptance(
                state,
                final_model_response_received=False,
            )
        )

        self.assertTrue(accepted["model_authored_plan_accepted"])
        self.assertTrue(accepted["projection_verified"])
        self.assertTrue(accepted["verified_business_projection"])
        self.assertFalse(
            no_final_model_response["verified_business_projection"]
        )

        state["active_entities"]["task_plan"][
            "deterministic_business_steps_inserted"
        ] = True
        deterministic_plan = (
            task_runtime.model_authored_projection_acceptance(
                state,
                final_model_response_received=True,
            )
        )
        self.assertFalse(
            deterministic_plan["model_authored_plan_accepted"]
        )
        self.assertFalse(
            deterministic_plan["verified_business_projection"]
        )

    def test_direct_bulk_cargo_plan_is_not_rewritten_by_legacy_singular_tokens(self) -> None:
        order_numbers = [f"ORD-BULK-{index:02d}" for index in range(1, 13)]
