    def test_r381_cancellation_count_and_reason_distribution_keep_canonical_metric(
        self,
    ) -> None:
        message = (
            "yerel sipariş kayıtlarına göre iptal edilmiş kaç sipariş var ve "
            "iptal nedenleri nasıl dağılıyor? sayı ile neden dağılımını "
            "birlikte ver, dışarıdan güncelleme yapma"
        )
        interpreted = task_runtime.interpret_agent_turn(
            message,
            planner_client=lambda _prompt: json.dumps(
                {
                    "mode": "inspect",
                    "domain": "orders",
                    "objective": "İptal sayısı ve neden dağılımını getir",
                    "intent_kind": "data_read",
                    "request_shape": "focused_analysis",
                    "requested_fields": ["count", "reason", "status"],
                    "direct_output_fields": ["count", "reason"],
                    "entity": "order",
                    "metric": "summary",
                    "status_scope": "cancelled",
                    "record_scope": "all_matching",
                    "period": "all",
                    "freshness": "local_snapshot",
                    "information_source": "local_business_data",
                    "operation_policy": "allow_new_operations",
                    "reason": "Cancellation count and reasons.",
                    "requires_clarification": False,
                    "clarification": "",
                },
                ensure_ascii=False,
            ),
        )

        self.assertTrue(interpreted.success, interpreted.message)
        interpretation = dict(interpreted.data or {})
        self.assertEqual(interpretation.get("requested_fields"), ["count", "reason"])
        contract = dict(interpretation.get("semantic_contract") or {})
        self.assertEqual(contract.get("status_scope"), "cancelled")
        self.assertEqual(
            contract.get("metric_requirements"),
            [
                ORDER_CANCELLED_COUNT_METRIC,
                ORDER_CANCELLATION_REASON_DISTRIBUTION_METRIC,
            ],
        )

        step_ids, metadata = task_runtime._orders_task_plan(
            message,
            planner_client=lambda _prompt: json.dumps(
                {
                    "steps": [
                        {
                            "id": "cancellations",
                            "operation_id": "orders.cancellations",
                            "arguments_json": '{"period":"all"}',
                            "depends_on": [],
                            "objective": "Cancellation count and reasons",
                            "expected_evidence": [
                                "cancelled_orders",
                                "cancel_reasons",
                            ],
                        }
                    ]
                }
            ),
            max_steps=8,
            turn_interpretation=interpretation,
        )
        self.assertEqual(step_ids, ["cancellations"])
        self.assertEqual(metadata.get("source"), "llm_direct")
        self.assertEqual(
            [row.get("operation_id") for row in metadata.get("step_specs") or []],
            ["orders.cancellations"],
        )

        state = self._completed_response_state(
            goal=message,
            operation="orders.cancellations",
            tool_result={
                "cancelled_orders": 3,
                "cancel_reasons": {"Stok yok": 2, "Müşteri vazgeçti": 1},
                "orders": [],
                "listed_count": 0,
                "truncated": True,
            },
            authoritative_answer="3 iptal sipariş var.",
            requested_fields=["count", "reason"],
        )
        state.active_entities["turn_interpretation"]["semantic_contract"] = {
            **contract,
            "projection": ["count", "reason"],
        }
        incomplete = response_verifier.verify_response_projection(
            "İptal edilmiş 3 sipariş var.",
            state,
            source="model",
        )
        self.assertFalse(incomplete.success)
        self.assertIn(
            "cancellation_reason_projection_missing:stok yok",
            (
                (incomplete.data or {}).get("response_verification") or {}
            ).get("reason_codes")
            or [],
        )
        complete = response_verifier.verify_response_projection(
            "İptal edilmiş 3 sipariş var. İptal nedeni sipariş kalemi sayıları: Stok yok (2), Müşteri vazgeçti (1).",
            state,
            source="model",
        )
        self.assertTrue(complete.success, complete.data)
        fallback = response_verifier.project_fallback_response(state, "")
        self.assertIn("Iptal edilmis 3 siparis", fallback)
        self.assertIn("Stok yok (2)", fallback)
        self.assertIn("Müşteri vazgeçti (1)", fallback)

