    def test_r406_new_query_acmadan_forces_existing_observation_projection(
        self,
    ) -> None:
        message = (
            "Bu dağılımda baskın durum hangisi? Yine yeni sorgu açmadan, "
            "baskın durumdaki sipariş sayısının diğer iki durumun toplamına "
            "oranını hesapla."
        )
        interpreted = task_runtime.interpret_agent_turn(
            message,
            planner_client=lambda _prompt: json.dumps(
                {
                    "mode": "inspect",
                    "domain": "orders",
                    "objective": "Baskın durumun diğer iki duruma oranını hesapla",
                    "intent_kind": "data_read",
                    "request_shape": "focused_analysis",
                    "requested_fields": ["count", "status", "calculation"],
                    "direct_output_fields": ["count", "status"],
                    "entity": "order",
                    "metric": "derived",
                    "status_scope": "all",
                    "record_scope": "all_matching",
                    "period": "all",
                    "freshness": "local_snapshot",
                    "information_source": "local_business_data",
                    # R406 provider drift: the explicit no-new-query boundary
                    # was lost and a redundant status_counts read was opened.
                    "operation_policy": "allow_new_operations",
                    "derived_calculation": {
                        "operator": "divide",
                        "operands": [
                            {
                                "ref": "orders.status_count",
                                "member": "Delivered",
                            },
                            {
                                "ref": "orders.status_count_sum",
                                "members": [
                                    "Cancelled",
                                    "UnDeliveredAndReturned",
                                ],
                            },
                        ],
                        "result_kind": "scalar",
                        "precision": 2,
                        "show_work": True,
                    },
                    "reason": "Prior status observation is sufficient",
                    "requires_clarification": False,
                    "clarification": "",
                },
                ensure_ascii=False,
            ),
        )

        self.assertTrue(interpreted.success, interpreted.message)
        interpretation = dict(interpreted.data or {})
        self.assertEqual(
            interpretation.get("operation_policy"),
            "existing_observations_only",
        )
        self.assertIn(
            "explicit_no_new_operation_to_existing_observations_only",
            interpretation.get("semantic_corrections") or [],
        )

        state = AgentSessionState(
            goal="Sipariş durumu özeti",
            active_domain="orders",
            status="complete",
        )
        state.completed_steps = [
            AgentTaskStep(
                index=1,
                step_id="summary",
                prompt="Sipariş özeti",
                operation_domain="orders",
                status="completed",
                tool_names=["orders.summary"],
                result_data={
                    "tool_result": {
                        "tool": "orders.summary",
                        "total_orders": 3120,
                        "status_counts": {
                            "Cancelled": 110,
                            "Delivered": 2958,
                            "UnDeliveredAndReturned": 52,
                        },
                    }
                },
            )
        ]
        projected = task_runtime.run_existing_observation_read_turn(
            message,
            interpretation=interpretation,
            session_state=state,
        )

        self.assertTrue(projected.success, projected.data)
        projected_data = dict(projected.data or {})
        self.assertEqual(projected_data.get("tool_calls"), [])
        self.assertEqual(projected_data.get("tool_names"), [])
        self.assertIn("2958", str(projected_data.get("answer") or ""))
        self.assertIn("110", str(projected_data.get("answer") or ""))
        self.assertIn("52", str(projected_data.get("answer") or ""))
        self.assertIn("18.26", str(projected_data.get("answer") or ""))

    def test_r408_same_turn_derived_dependency_does_not_bind_prior_turn_result(
        self,
    ) -> None:
        message = (
            "Yine yeni sorgu açmadan Delivered sayısını diğer iki durumun "
            "toplamına böl; önce 110 + 52 ara hesabını, sonra nihai oranı "
            "iki ondalıkla göster."
        )
        state = AgentSessionState(
            goal="Sipariş durum özeti",
            active_domain="orders",
            status="complete",
        )
        state.completed_steps = [
            AgentTaskStep(
                index=1,
                step_id="summary",
                prompt="Sipariş özeti",
                operation_domain="orders",
                status="completed",
                tool_names=["orders.summary"],
                result_data={
                    "tool_result": {
                        "tool": "orders.summary",
                        "total_orders": 3120,
                        "status_counts": {
                            "Cancelled": 110,
                            "Delivered": 2958,
                            "UnDeliveredAndReturned": 52,
                        },
                    }
                },
            )
        ]
        # R408 had a valid prior-turn percentage. The second formula must
        # still bind the first formula in this turn, never this stale latest.
        state.observations = [
            Observation.create(
                domain="orders",
                operation_name="core.verified_calculation",
                success=True,
                aggregates={
                    "verified_calculation": {
                        "result": "1.67",
                        "result_kind": "percentage",
                        "result_label": "Hesaplanan oran",
                        "unit": "%",
                        "evidence_hash": "r408-prior-percentage",
                        "verified": True,
                    }
                },
                source="typed_authoritative_observation_calculation",
            )
        ]
        prompts: list[str] = []
        responses = iter(
            [
                json.dumps(
                    {
                        "mode": "inspect",
                        "domain": "orders",
                        "objective": message,
                        "intent_kind": "data_read",
                        "request_shape": "focused_analysis",
                        "requested_fields": ["calculation", "count", "ratio"],
                        "direct_output_fields": [],
                        "entity": "order",
                        "metric": "derived",
                        "status_scope": "delivered",
                        "record_scope": "all_matching",
                        "period": "all",
                        "freshness": "local_snapshot",
                        "information_source": "local_business_data",
                        "operation_policy": "existing_observations_only",
                        "calculation_count": 2,
                        "calculation_grouping": "single_result",
                        "derived_calculations": [
                            {
                                "operator": "add",
                                "operands": [
                                    {
                                        "ref": "orders.status_count",
                                        "member": "Cancelled",
                                    },
                                    {
                                        "ref": "orders.status_count",
                                        "member": "UnDeliveredAndReturned",
                                    },
                                ],
                                "result_kind": "count",
                                "precision": 0,
                                "show_work": True,
                            },
                            {
                                "operator": "divide",
                                "operands": [
                                    {
                                        "ref": "orders.status_count",
                                        "member": "Delivered",
                                    },
                                    {"ref": "formula_0.result"},
                                ],
                                "result_kind": "scalar",
                                "precision": 2,
                                "show_work": True,
                            },
                        ],
                        "reason": "Ara toplamı sonraki oranda kullan",
                        "requires_clarification": False,
                        "clarification": "",
                    },
                    ensure_ascii=False,
                ),
                json.dumps(
                    {
                        "derived_calculations": [
                            {
                                "operator": "add",
                                "operands": [
                                    {
                                        "ref": "orders.status_count",
                                        "member": "Cancelled",
                                    },
                                    {
                                        "ref": "orders.status_count",
                                        "member": "UnDeliveredAndReturned",
                                    },
                                ],
                                "result_kind": "count",
                                "precision": 0,
                                "show_work": True,
                            },
                            {
                                "operator": "divide",
                                "operands": [
                                    {
                                        "ref": "orders.status_count",
                                        "member": "Delivered",
                                    },
                                    {"ref": "derived.current", "index": 0},
                                ],
                                "result_kind": "scalar",
                                "precision": 2,
                                "show_work": True,
                            },
                        ]
                    },
                    ensure_ascii=False,
                ),
            ]
        )

        def planner(prompt: str, **_kwargs: object) -> str:
            prompts.append(prompt)
            return next(responses)

        interpreted = task_runtime.interpret_agent_turn(
            message,
            planner_client=planner,
            session_state=state,
        )

        self.assertTrue(interpreted.success, interpreted.message)
        self.assertEqual(len(prompts), 2)
        self.assertIn("derived.current", prompts[1])
        contract = dict((interpreted.data or {}).get("semantic_contract") or {})
        self.assertEqual(
            interpreted.data.get("calculation_grouping"),
            "sequential_results",
        )
        self.assertEqual(
            contract.get("calculation_grouping"),
            "sequential_results",
        )
        formulas = list(contract.get("derived_calculations") or [])
        self.assertEqual(
            formulas[1]["operands"][1],
            {"ref": "derived.current", "index": 0},
        )
        projected = task_runtime.run_existing_observation_read_turn(
            message,
            interpretation=dict(interpreted.data or {}),
            session_state=state,
        )

        self.assertTrue(projected.success, projected.data)
        answer = str((projected.data or {}).get("answer") or "")
        self.assertIn("110 siparis + 52 siparis = 162 adet", answer)
        self.assertIn("2958 siparis / 162 adet = 18.26", answer)
        self.assertNotIn("2958 siparis / 1.67 %", answer)
        self.assertEqual((projected.data or {}).get("tool_calls"), [])

        forward_errors: list[str] = []
        forward = task_runtime._normalize_derived_calculations(
            [
                {
                    "operator": "add",
                    "operands": [
                        {"ref": "derived.current", "index": 0},
                        {"ref": "literal", "value": 1},
                    ],
                    "result_kind": "scalar",
                    "precision": 0,
                    "show_work": True,
                }
            ],
            domain="orders",
            message="Ara sonuca 1 ekle.",
            validation_errors=forward_errors,
            minimum_count=1,
        )
        self.assertEqual(forward, [])
        self.assertTrue(
            any(
                "derived_current_must_reference_prior_formula" in reason
                for reason in forward_errors
            ),
            forward_errors,
        )

    def test_r415_same_data_and_no_percentage_are_binding_typed_boundaries(
        self,
    ) -> None:
        message = (
            "Aynı veriden önce Cancelled ile UnDeliveredAndReturned "
            "toplamını bul, ardından Delivered sayısını bu ara sonuca böl; "
            "iki ondalık olsun, yüzdeye çevirme."
        )
        state = AgentSessionState(
            goal="Sipariş durum özeti",
            active_domain="orders",
            status="complete",
        )
        state.completed_steps = [
            AgentTaskStep(
                index=1,
                step_id="summary",
                prompt="Sipariş özeti",
                operation_domain="orders",
                status="completed",
                tool_names=["orders.summary"],
                result_data={
                    "tool_result": {
                        "tool": "orders.summary",
                        "total_orders": 3120,
                        "status_counts": {
                            "Cancelled": 110,
                            "Delivered": 2958,
                            "UnDeliveredAndReturned": 52,
                        },
                    }
                },
            )
        ]
        model_payload = {
            "mode": "inspect",
            "domain": "orders",
            "objective": message,
            "intent_kind": "data_read",
            "request_shape": "focused_analysis",
            # R415 provider drift: operands and a negated percentage were
            # incorrectly echoed as independently visible base fields.
            "requested_fields": [
                "status",
                "ratio",
                "calculation",
                "count",
            ],
            "direct_output_fields": ["status", "ratio"],
            "identifier_display": "auto",
            "entity": "order",
            "metric": "derived",
            "status_scope": "all",
            "record_scope": "all_matching",
            "period": "all",
            "freshness": "local_snapshot",
            "information_source": "local_business_data",
            "operation_policy": "allow_new_operations",
            "calculation_grouping": "sequential_results",
            "calculation_count": 2,
            "derived_calculations": [
                {
                    "operator": "add",
                    "operands": [
                        {
                            "ref": "orders.status_count",
                            "member": "Cancelled",
                        },
                        {
                            "ref": "orders.status_count",
                            "member": "UnDeliveredAndReturned",
                        },
                    ],
                    "result_kind": "count",
                    "precision": 0,
                    "show_work": True,
                },
                {
                    "operator": "divide",
                    "operands": [
                        {
                            "ref": "orders.status_count",
                            "member": "Delivered",
                        },
                        {"ref": "derived.current", "index": 0},
                    ],
                    "result_kind": "scalar",
                    "precision": 2,
                    "show_work": True,
                },
            ],
            "reason": "Aynı verified veriden iki sıralı hesap",
            "requires_clarification": False,
            "clarification": "",
        }

        self.assertTrue(
            task_runtime._existing_observations_only_requested(message)
        )
        self.assertTrue(
            task_runtime._explicit_percentage_relation_prohibited(message)
        )
        self.assertFalse(
            task_runtime._explicit_percentage_relation_requested(message)
        )
        interpreted = task_runtime.interpret_agent_turn(
            message,
            planner_client=lambda _prompt, **_kwargs: json.dumps(
                model_payload,
                ensure_ascii=False,
            ),
            session_state=state,
        )

        self.assertTrue(interpreted.success, interpreted.message)
        interpretation = dict(interpreted.data or {})
        self.assertEqual(
            interpretation.get("operation_policy"),
            "existing_observations_only",
        )
        self.assertEqual(
            interpretation.get("direct_output_fields"),
            [],
        )
        self.assertEqual(
            set(interpretation.get("requested_fields") or []),
            {"calculation", "count"},
        )
        contract = dict(interpretation.get("semantic_contract") or {})
        self.assertEqual(contract.get("direct_projection") or [], [])
        self.assertNotIn("ratio", contract.get("projection") or [])
        projected = task_runtime.run_existing_observation_read_turn(
            message,
            interpretation=interpretation,
            session_state=state,
        )

        self.assertTrue(projected.success, projected.data)
        answer = str((projected.data or {}).get("answer") or "")
        self.assertIn("110 siparis + 52 siparis = 162 adet", answer)
        self.assertIn("2958 siparis / 162 adet = 18.26", answer)
        self.assertNotIn("bulunamadi", answer.casefold())
        self.assertEqual((projected.data or {}).get("tool_calls"), [])

