    def test_r410_broad_average_cannot_persist_unrelated_duplicate_formulas(
        self,
    ) -> None:
        message = (
            "Pazaryerinden yeni veri çekmeden mevcut yerel production "
            "sipariş kaydımıza genel bak: toplam sipariş, durum dağılımı, "
            "toplam ciro ve sipariş başına ortalama ciroyu açık formülle "
            "özetle."
        )
        wrong_formula = {
            "operator": "add",
            "operands": [
                {"ref": "orders.status_count", "member": "pending"},
                {"ref": "orders.status_count", "member": "shipped"},
                {"ref": "orders.status_count", "member": "delivered"},
                {"ref": "orders.status_count", "member": "cancelled"},
            ],
            "result_kind": "count",
            "precision": 0,
            "show_work": False,
        }
        responses = iter(
            [
                json.dumps(
                    {
                        "mode": "inspect",
                        "domain": "orders",
                        "objective": message,
                        "intent_kind": "data_read",
                        "request_shape": "broad_analysis",
                        "requested_fields": [
                            "count",
                            "status",
                            "amount",
                            "scope",
                            "calculation",
                        ],
                        "direct_output_fields": [
                            "count",
                            "status",
                            "amount",
                            "scope",
                        ],
                        "entity": "order",
                        "metric": "derived",
                        "status_scope": "all",
                        "record_scope": "all_matching",
                        "period": "all",
                        "freshness": "local_snapshot",
                        "information_source": "local_business_data",
                        "operation_policy": "allow_new_operations",
                        "calculation_grouping": "sequential_results",
                        "calculation_count": 3,
                        "derived_calculations": [
                            wrong_formula,
                            wrong_formula,
                            wrong_formula,
                        ],
                        "reason": "Yanlış tekrarlı formüller",
                        "requires_clarification": False,
                        "clarification": "",
                    },
                    ensure_ascii=False,
                ),
                json.dumps(
                    {
                        "result_contract_revision": {
                            "calculation_count": 1,
                            "calculation_grouping": "single_result",
                            "reason": "Toplam, durum dağılımı ve ciro ham metrik; yalnız sipariş başına ortalama hesaplanıyor.",
                        },
                        "derived_calculations": [
                            {
                                "operator": "divide",
                                "operands": [
                                    {"ref": "orders.revenue_total"},
                                    {"ref": "orders.total_count"},
                                ],
                                "result_kind": "amount_per_order",
                                "precision": 2,
                                "show_work": True,
                            }
                        ]
                    },
                    ensure_ascii=False,
                ),
            ]
        )
        prompts: list[str] = []

        def planner(prompt: str, **_kwargs: object) -> str:
            prompts.append(prompt)
            return next(responses)

        interpreted = task_runtime.interpret_agent_turn(
            message,
            planner_client=planner,
        )

        # Detailed arithmetic follows real reads; the goal and direct evidence survive.
        self.assertTrue(interpreted.success, interpreted.message)
        data = dict(interpreted.data or {})
        contract = dict(data.get("semantic_contract") or {})
        deferred = dict(contract.get("deferred_calculation") or {})
        self.assertEqual(deferred.get("status"), "pending")
        self.assertTrue(deferred.get("requires_source_bound_calculation"))
        self.assertFalse(contract.get("derived_calculation"))
        self.assertFalse(contract.get("derived_calculations"))
        self.assertIn("calculation", data.get("requested_fields") or [])
        self.assertTrue(set(['count', 'status', 'amount', 'currency', 'scope']).issubset(set(data.get("requested_fields") or [])), data)
        self.assertFalse((data.get("derived_calculation_repair") or {}).get("applied"))
        state = AgentSessionState(goal=message, active_domain="orders", active_entities={"turn_interpretation": data})
        self.assertEqual(task_runtime._unmet_goal_obligations(state), ["deferred_source_bound_calculation_missing"])

    def test_multi_calculation_normalization_accepts_typed_provider_dialect(
        self,
    ) -> None:
        normalized = task_runtime._normalize_derived_calculations(
            [
                {
                    "operator": "subtraction",
                    "operands": [
                        {
                            "ref": "orders.status_count",
                            "members": ["Delivered"],
                        },
                        {
                            "ref": "orders.status_count",
                            "members": ["Cancelled"],
                        },
                    ],
                    "result_kind": "difference",
                    "precision": 0,
                    "show_work": (
                        "Delivered sipariş sayısı - Cancelled sipariş sayısı"
                    ),
                },
                {
                    "operator": "division",
                    "ordered_operand_refs": [
                        "orders.status_count(status=Cancelled)",
                        "orders.total_count",
                    ],
                    "result_kind": "ratio",
                    "precision": 2,
                    "show_work": (
                        "Cancelled sipariş sayısı / toplam sipariş sayısı × 100"
                    ),
                },
            ],
            domain="orders",
            message="Delivered Cancelled farkı ve oranı",
        )

        self.assertEqual(
            [row.get("operator") for row in normalized],
            ["subtract", "divide"],
        )
        self.assertEqual(
            [row.get("result_kind") for row in normalized],
            ["count", "percentage"],
        )
        self.assertTrue(all(row.get("show_work") is True for row in normalized))
        self.assertEqual(
            normalized[0]["operands"][0],
            {"ref": "orders.status_count", "member": "Delivered"},
        )

