    def test_r292_goal_plan_covers_base_metrics_before_verified_average(
        self,
    ) -> None:
        goal = (
            "Toplam sipariş, durum dağılımı, ciro ve sipariş başına "
            "ortalama tutarı aynı kapsamda ver."
        )
        interpretation = {
            "mode": "inspect",
            "domain": "orders",
            "intent_kind": "data_read",
            "requested_fields": [
                "count",
                "status",
                "amount",
                "currency",
                "scope",
                "calculation",
            ],
            "direct_output_fields": [
                "count",
                "status",
                "amount",
                "currency",
                "scope",
            ],
            "semantic_contract": {
                "entity": "order",
                "metric": "derived",
                "request_shape": "broad_analysis",
                "status_scope": "all",
                "record_scope": "all_matching",
                "period": "all",
                "projection": [
                    "count",
                    "status",
                    "amount",
                    "currency",
                    "scope",
                    "calculation",
                ],
                "direct_projection": [
                    "count",
                    "status",
                    "amount",
                    "currency",
                    "scope",
                ],
                "metric_requirements": [
                    ORDER_TOTAL_COUNT_METRIC,
                    ORDER_STATUS_DISTRIBUTION_METRIC,
                    ORDER_REVENUE_TOTAL_METRIC,
                ],
                "derived_calculation": {
                    "operator": "divide",
                    "operands": [
                        {"ref": "orders.revenue_total"},
                        {"ref": "orders.total_count"},
                    ],
                    "result_kind": "amount_per_order",
                    "precision": 2,
                    "show_work": False,
                },
            },
        }
        plan_payload = {
            "steps": [
                {
                    "id": "summary",
                    "operation_id": "orders.summary",
                    "arguments": {"period": "all"},
                    "depends_on": [],
                    "objective": "Toplam sipariş ve durum dağılımını getir",
                    "expected_evidence": [
                        "total_orders",
                        "status_counts",
                        "account_scopes",
                    ],
                },
                {
                    "id": "revenue",
                    "operation_id": "orders.revenue_total",
                    "arguments": {"period": "all"},
                    "depends_on": [],
                    "objective": "Aynı kapsamdaki toplam ciroyu getir",
                    "expected_evidence": [
                        "estimated_revenue",
                        "currency",
                        "account_scopes",
                    ],
                },
            ]
        }
        tools = available_tools()
        candidates = {
            operation_id: tools[operation_id]
            for operation_id in ("orders.summary", "orders.revenue_total")
        }

        with patch(
            "AI.processors.task_runtime._planner_operation_candidates",
            return_value=candidates,
        ):
            step_ids, metadata = task_runtime._orders_task_plan(
                goal,
                planner_client=lambda _prompt: json.dumps(
                    plan_payload,
                    ensure_ascii=False,
                ),
                max_steps=8,
                turn_interpretation=interpretation,
            )

        self.assertEqual(metadata.get("source"), "llm_direct", metadata)
        self.assertEqual(step_ids, ["summary", "revenue"])
        self.assertEqual(metadata.get("missing_metric_requirements"), [])
        self.assertEqual(
            [
                row.get("operation_id")
                for row in list(metadata.get("step_specs") or [])
            ],
            ["orders.summary", "orders.revenue_total"],
        )
        self.assertFalse(metadata.get("deterministic_business_steps_inserted"))

