    def test_bounded_recent_list_number_cannot_authorize_model_formula(
        self,
    ) -> None:
        message = (
            "En yeni 8 siparişimi yalnız sipariş numaralarıyla sırala; "
            "kişisel bilgi verme."
        )
        calls = 0

        def planner(_prompt: str) -> str:
            nonlocal calls
            calls += 1
            return json.dumps(
                {
                    "mode": "inspect",
                    "domain": "orders",
                    "objective": "En yeni 8 sipariş numarasını listele",
                    "intent_kind": "data_read",
                    "request_shape": "focused_analysis",
                    "requested_fields": ["calculation"],
                    "entity": "order",
                    "metric": "derived",
                    "status_scope": "all",
                    "record_scope": "all_matching",
                    "period": "all",
                    "freshness": "current_local",
                    "information_source": "local_business_data",
                    "operation_policy": "allow_new_operations",
                    "calculation_count": 1,
                    "derived_calculation": {
                        "operator": "add",
                        "operands": [
                            {
                                "ref": "orders.status_count",
                                "member": "total",
                            },
                            {
                                "ref": "orders.status_count",
                                "member": "cancelled",
                            },
                        ],
                        "result_kind": "scalar",
                        "precision": 0,
                        "show_work": False,
                    },
                    "reason": "Newest eight orders",
                    "requires_clarification": False,
                    "clarification": "",
                },
                ensure_ascii=False,
            )

        interpreted = task_runtime.interpret_agent_turn(
            message,
            planner_client=planner,
        )

        self.assertTrue(interpreted.success, interpreted.message)
        self.assertEqual(calls, 1)
        data = dict(interpreted.data or {})
        self.assertEqual(data.get("request_shape"), "record_list")
        self.assertEqual(data.get("requested_fields"), ["order_number"])
        self.assertEqual(data.get("calculation_count"), 0)
        contract = dict(data.get("semantic_contract") or {})
        self.assertEqual(contract.get("metric"), "list")
        self.assertEqual(contract.get("request_shape"), "record_list")
        self.assertEqual(contract.get("projection"), ["order_number"])
        self.assertNotIn("derived_calculation", contract)
        self.assertNotIn("derived_calculations", contract)
        self.assertIn(
            "unrequested_derived_calculation_removed",
            data.get("semantic_corrections") or [],
        )

