    def test_existing_observation_average_uses_verified_core_calculation_without_tool(
        self,
    ) -> None:
        state = AgentSessionState(
            goal="Sipariş özeti",
            active_domain="orders",
            status="complete",
        )
        state.completed_steps = [
            AgentTaskStep(
                index=1,
                step_id="count",
                prompt="Toplam sipariş",
                operation_domain="orders",
                status="completed",
                tool_names=["orders.count"],
                result_data={
                    "tool_result": {
                        "tool": "orders.count",
                        "count": 3112,
                    }
                },
            ),
            AgentTaskStep(
                index=2,
                step_id="revenue",
                prompt="Toplam ciro",
                operation_domain="orders",
                status="completed",
                tool_names=["orders.revenue_total"],
                result_data={
                    "tool_result": {
                        "tool": "orders.revenue_total",
                        "estimated_revenue": 502518.01,
                        "currency": "TRY",
                    }
                },
            ),
        ]
        interpretation = {
            "mode": "inspect",
            "domain": "orders",
            "objective": "Önceki ciroyu sipariş sayısına böl",
            "intent_kind": "data_read",
            "request_shape": "focused_analysis",
            "operation_policy": "existing_observations_only",
            "requested_fields": ["calculation", "amount", "currency"],
            "semantic_contract": {
                "entity": "order",
                "metric": "derived",
                "status_scope": "all",
                "record_scope": "all_matching",
                "period": "all",
                "freshness": "local_snapshot",
                "projection": ["calculation", "amount", "currency"],
                "metric_requirements": [
                    ORDER_REVENUE_TOTAL_METRIC,
                    ORDER_TOTAL_COUNT_METRIC,
                ],
                "derived_calculation": {
                    "operator": "divide",
                    "operands": [
                        {"ref": "orders.revenue_total"},
                        {"ref": "orders.total_count"},
                    ],
                    "result_kind": "amount_per_order",
                    "precision": 2,
                    "show_work": True,
                },
            },
        }

        result = task_runtime.run_existing_observation_read_turn(
            "Yeni sorgu çalıştırmadan ortalamayı işlemiyle göster.",
            interpretation=interpretation,
            session_state=state,
        )

        self.assertTrue(result.success, result.message)
        answer = str((result.data or {}).get("answer") or "")
        self.assertIn("502518.01 TRY / 3112 siparis", answer)
        self.assertIn("161.48 TRY/siparis", answer)
        self.assertEqual((result.data or {}).get("tool_calls"), [])
        calculation = dict((result.data or {}).get("verified_calculation") or {})
        self.assertEqual(calculation.get("result"), "161.48")
        self.assertTrue(calculation.get("verified"))
        final_state = AgentSessionState.from_dict(
            dict((result.data or {}).get("session_state") or {})
        )
        calculation_observations = [
            row
            for row in final_state.observations
            if row.operation_name == "core.verified_calculation"
        ]
        self.assertEqual(len(calculation_observations), 1)
        synthesis = dict(
            (final_state.active_entities or {}).get("response_synthesis") or {}
        )
        self.assertEqual(
            synthesis.get("final_source"),
            "deterministic_existing_observation_projection",
        )

