    def test_r302_status_sum_consistency_is_typed_compared_without_revenue_drift(
        self,
    ) -> None:
        state = AgentSessionState(
            goal="Sipariş özeti",
            active_domain="orders",
            status="complete",
        )
        state.completed_steps = [
            AgentTaskStep(
                index=1,
                step_id="summary",
                prompt="Sipariş özeti",
                operation_domain="orders",
                status="completed",
                tool_names=["orders.summary"],
                result_data={
                    "tool_result": {
                        "tool": "orders.summary",
                        "total_orders": 3119,
                        "status_counts": {
                            "Cancelled": 110,
                            "Delivered": 2957,
                            "UnDeliveredAndReturned": 52,
                        },
                        "estimated_revenue": 503446.47,
                        "currency": "TRY",
                    }
                },
            )
        ]
        message = (
            "Bu yerel snapshotta sipariş durumlarını adetleriyle dağıt ve durum "
            "adetlerinin toplamının az önce verdiğin 3119 siparişle tutarlı olup "
            "olmadığını doğrula. API senkronu yapma."
        )
        self.assertTrue(
            task_runtime._explicit_comparison_relation_requested(message)
        )
        self.assertTrue(
            task_runtime._explicit_arithmetic_relation_requested(message)
        )
        self.assertNotIn(
            "amount",
            task_runtime._explicit_repeat_projection_fields(message),
        )
        self.assertTrue(
            task_runtime._goal_has_order_status_distribution_requirement(
                message
            )
        )

        responses = [
            {
                "mode": "inspect",
                "domain": "orders",
                "objective": "Durum adetlerini ve tutarlılığı doğrula",
                "intent_kind": "data_read",
                "request_shape": "focused_analysis",
                "requested_fields": [
                    "status",
                    "count",
                    "amount",
                    "currency",
                ],
                "direct_output_fields": ["status", "count"],
                "entity": "order",
                "metric": "summary",
                "status_scope": "all",
                "record_scope": "all_matching",
                "period": "all",
                "freshness": "local_snapshot",
                "information_source": "local_business_data",
                "operation_policy": "existing_observations_only",
                "calculation_count": 0,
                "reason": "Önceki özeti doğrula",
                "requires_clarification": False,
                "clarification": "",
            },
            {
                "operator": "add",
                "operands": [
                    {
                        "ref": "orders.status_count",
                        "member": "Cancelled",
                    },
                    {
                        "ref": "orders.status_count",
                        "member": "Delivered",
                    },
                    {
                        "ref": "orders.status_count",
                        "member": "UnDeliveredAndReturned",
                    },
                ],
                "result_kind": "count",
                "precision": 0,
                "show_work": True,
                "comparison": {
                    "operator": "equal",
                    "operand": {"ref": "orders.total_count"},
                },
            },
        ]
        prompts: list[str] = []

        def planner(prompt: str) -> str:
            prompts.append(prompt)
            return json.dumps(responses.pop(0), ensure_ascii=False)

        interpreted = task_runtime.interpret_agent_turn(
            message,
            planner_client=planner,
            session_state=state,
        )

        self.assertTrue(interpreted.success, interpreted.message)
        self.assertEqual(len(prompts), 2)
        self.assertIn('"comparison_required": true', prompts[1])
        data = dict(interpreted.data or {})
        self.assertIn(
            "explicit_arithmetic_relation_requires_model_formula",
            data.get("semantic_corrections") or [],
        )
        self.assertNotIn("amount", data.get("requested_fields") or [])
        self.assertNotIn("currency", data.get("requested_fields") or [])
        contract = dict(data.get("semantic_contract") or {})
        self.assertEqual(contract.get("metric"), "derived")
        self.assertEqual(
            contract.get("metric_requirements"),
            [ORDER_TOTAL_COUNT_METRIC, ORDER_STATUS_DISTRIBUTION_METRIC],
        )
        formula = dict(contract.get("derived_calculation") or {})
        self.assertEqual(
            formula.get("comparison"),
            {
                "operator": "equal",
                "operand": {"ref": "orders.total_count"},
            },
        )

        projected = task_runtime.run_existing_observation_read_turn(
            message,
            interpretation=data,
            session_state=state,
        )

        self.assertTrue(projected.success, projected.message)
        answer = str((projected.data or {}).get("answer") or "")
        self.assertIn(
            "110 siparis + 2957 siparis + 52 siparis = 3119 adet",
            answer,
        )
        self.assertIn("Tutarlılık: tutarlı (3119 = 3119)", answer)
        self.assertNotIn("ciro", answer.casefold())
        self.assertNotIn("TRY", answer)
        self.assertEqual((projected.data or {}).get("tool_calls"), [])

        projected_state = AgentSessionState.from_dict(
            dict((projected.data or {}).get("session_state") or {})
        )
        missing_relation = response_verifier.verify_response_projection(
            (
                "Sipariş durumları: Cancelled 110, Delivered 2957, "
                "UnDeliveredAndReturned 52. Hesaplanan adet: "
                "110 + 2957 + 52 = 3119 adet."
            ),
            projected_state,
        )
        self.assertFalse(missing_relation.success)
        self.assertIn(
            "derived_calculation_comparison_projection_missing",
            (missing_relation.data.get("response_verification") or {}).get(
                "reason_codes"
            )
            or [],
        )

    def test_r311_api_sync_prohibition_allows_dynamic_local_status_sum(
        self,
    ) -> None:
        message = (
            "Peki bu 3119 siparişin durum dağılımını adetleriyle ver; durum "
            "adetlerini toplayıp 3119 ile tutarlı olup olmadığını da açıkça "
            "göster. API senkronu yapma."
        )
        self.assertFalse(task_runtime._goal_has_fetch_intent(message))
        self.assertFalse(
            task_runtime._existing_observations_only_requested(message)
        )

        prior_state = AgentSessionState(
            goal="Yerel sipariş sayısı",
            active_domain="orders",
            status="complete",
        )
        prior_state.completed_steps = [
            AgentTaskStep(
                index=1,
                step_id="count",
                prompt="Toplam sipariş sayısını oku",
                operation_domain="orders",
                status="completed",
                tool_names=["orders.count"],
                result_data={
                    "tool_result": {
                        "tool": "orders.count",
                        "count": 3119,
                    }
                },
            )
        ]
        interpreted = task_runtime.interpret_agent_turn(
            message,
            planner_client=lambda _prompt: json.dumps(
                {
                    "mode": "inspect",
                    "domain": "orders",
                    "objective": "Durum dağılımını topla ve toplamla karşılaştır",
                    "intent_kind": "data_read",
                    "request_shape": "focused_analysis",
                    "requested_fields": ["status", "count", "calculation"],
                    "direct_output_fields": ["status"],
                    "entity": "order",
                    "metric": "derived",
                    "status_scope": "all",
                    "record_scope": "all_matching",
                    "period": "all",
                    "freshness": "local_snapshot",
                    "information_source": "local_business_data",
                    # The model authorizes the requested local read while
                    # the user's separate API synchronization prohibition stays.
                    "operation_policy": "allow_new_operations",
                    "calculation_count": 1,
                    "derived_calculation": {
                        "operator": "add",
                        "operands": [{"ref": "orders.status_counts"}],
                        "result_kind": "count",
                        "precision": 0,
                        "show_work": True,
                        "comparison": {
                            "operator": "equal",
                            "operand": {"ref": "literal", "value": 3119},
                        },
                    },
                    "reason": "Yerel durum bucket'larını doğrula",
                    "requires_clarification": False,
                    "clarification": "",
                },
                ensure_ascii=False,
            ),
            session_state=prior_state,
        )

        self.assertTrue(interpreted.success, interpreted.message)
        interpretation = dict(interpreted.data or {})
        self.assertEqual(
            interpretation.get("operation_policy"),
            "allow_new_operations",
        )
        contract = dict(interpretation.get("semantic_contract") or {})
        self.assertEqual(
            contract.get("metric_requirements"),
            [ORDER_TOTAL_COUNT_METRIC, ORDER_STATUS_DISTRIBUTION_METRIC],
        )
        self.assertEqual(
            dict(contract.get("derived_calculation") or {}).get("operands"),
            [{"ref": "orders.status_counts"}],
        )

        verification_state = AgentSessionState(
            goal=message,
            active_domain="orders",
            status="complete",
        )
        verification_state.active_entities["turn_interpretation"] = interpretation
        verification_state.completed_steps = [
            AgentTaskStep(
                index=1,
                step_id="summary",
                prompt="Durum dağılımını oku",
                operation_domain="orders",
                status="completed",
                tool_names=["orders.summary"],
                result_data={
                    "tool_result": {
                        "tool": "orders.summary",
                        "total_orders": 3119,
                        "status_counts": {
                            "Cancelled": 110,
                            "Delivered": 2957,
                            "UnDeliveredAndReturned": 52,
                        },
                    }
                },
            )
        ]
        calculated = response_verifier.verified_derived_calculation(
            verification_state
        )

        self.assertEqual(calculated.get("result"), "3119")
        self.assertTrue(calculated.get("comparison_holds"))
        self.assertEqual(
            [row.get("value") for row in calculated.get("operands") or []],
            ["110", "2957", "52"],
        )

    def test_r313_comparison_pseudo_row_repairs_to_one_dynamic_formula(
        self,
    ) -> None:
        message = (
            "Pazaryerinden güncelleme yapmadan yerel kayıttaki toplam sipariş "
            "sayısını ve bütün durum dağılımını ver; dağılımdaki adetlerin "
            "toplamının genel toplamla tutarlı olup olmadığını işlemiyle göster."
        )
        responses = iter(
            [
                {
                    "mode": "inspect",
                    "domain": "orders",
                    "objective": "Yerel durum toplamını genel toplamla doğrula",
                    "intent_kind": "data_read",
                    "request_shape": "focused_analysis",
                    "requested_fields": ["status", "count", "calculation"],
                    "direct_output_fields": ["status", "count"],
                    "entity": "order",
                    "metric": "derived",
                    "status_scope": "all",
                    "record_scope": "all_matching",
                    "period": "all",
                    "freshness": "local_snapshot",
                    "information_source": "local_business_data",
                    "operation_policy": "allow_new_operations",
                    # R313 provider dialect: equality was incorrectly emitted
                    # as a second numeric calculation row.
                    "calculation_count": 2,
                    "derived_calculations": [
                        {
                            "operator": "sum",
                            "operand_refs": ["orders.status_counts"],
                            "result_kind": "count",
                            "precision": 0,
                            "show_work": True,
                        },
                        {
                            "operator": "eq_check",
                            "operand_refs": [
                                "orders.status_counts_sum",
                                "orders.count",
                            ],
                            "result_kind": "boolean",
                            "precision": 0,
                            "show_work": True,
                        },
                    ],
                    "reason": "Dağılım toplamını karşılaştır",
                    "requires_clarification": False,
                    "clarification": "",
                },
                {
                    "operator": "add",
                    "operands": [{"ref": "orders.status_counts"}],
                    "result_kind": "count",
                    "precision": 0,
                    "show_work": True,
                    "comparison": {
                        "operator": "equal",
                        "operand": {"ref": "orders.total_count"},
                    },
                },
            ]
        )
        prompts: list[str] = []

        def planner(prompt: str) -> str:
            prompts.append(prompt)
            return json.dumps(next(responses), ensure_ascii=False)

        interpreted = task_runtime.interpret_agent_turn(
            message,
            planner_client=planner,
        )

        # Detailed arithmetic follows real reads; the goal and direct evidence survive.
        self.assertTrue(interpreted.success, interpreted.message)
        data = dict(interpreted.data or {})
        contract = dict(data.get("semantic_contract") or {})
        deferred = dict(contract.get("deferred_calculation") or {})
        self.assertEqual(deferred.get("status"), "pending")
        self.assertTrue(deferred.get("requires_source_bound_calculation"))
        self.assertFalse(contract.get("derived_calculation"))
        self.assertFalse(contract.get("derived_calculations"))
        self.assertIn("calculation", data.get("requested_fields") or [])
        self.assertTrue(set(['count', 'status']).issubset(set(data.get("requested_fields") or [])), data)
        self.assertFalse((data.get("derived_calculation_repair") or {}).get("applied"))
        state = AgentSessionState(goal=message, active_domain="orders", active_entities={"turn_interpretation": data})
        self.assertEqual(task_runtime._unmet_goal_obligations(state), ["deferred_source_bound_calculation_missing"])
        self.assertTrue(deferred.get("comparison_required"))
        self.assertNotIn("amount", data.get("requested_fields") or [])

