    def test_derived_calculation_verifier_rejects_wrong_result_or_missing_work(
        self,
    ) -> None:
        state = AgentSessionState(
            goal="Sipariş başına ortalama ciro",
            active_domain="orders",
            status="complete",
        )
        state.active_entities["turn_interpretation"] = {
            "requested_fields": ["calculation", "amount", "currency"],
            "semantic_contract": {
                "entity": "order",
                "metric": "derived",
                "projection": ["calculation", "amount", "currency"],
                "metric_requirements": [
                    ORDER_REVENUE_TOTAL_METRIC,
                    ORDER_TOTAL_COUNT_METRIC,
                ],
                "derived_calculation": {
                    "operator": "divide",
                    "operands": [
                        {"ref": "orders.revenue_total"},
                        {"ref": "orders.total_count"},
                    ],
                    "result_kind": "amount_per_order",
                    "precision": 2,
                    "show_work": True,
                },
            },
        }
        state.completed_steps = [
            AgentTaskStep(
                index=1,
                step_id="count",
                prompt="count",
                status="completed",
                tool_names=["orders.count"],
                result_data={"tool_result": {"count": 3112}},
            ),
            AgentTaskStep(
                index=2,
                step_id="revenue",
                prompt="revenue",
                status="completed",
                tool_names=["orders.revenue_total"],
                result_data={
                    "tool_result": {
                        "estimated_revenue": 502518.01,
                        "currency": "TRY",
                    }
                },
            ),
        ]

        wrong = response_verifier.verify_response_projection(
            "Sipariş başına ortalama ciro 160.00 TRY.",
            state,
        )
        missing_work = response_verifier.verify_response_projection(
            "Sipariş başına ortalama ciro 161.48 TRY.",
            state,
        )

        self.assertFalse(wrong.success)
        self.assertIn(
            "derived_calculation_result_projection_missing",
            (wrong.data.get("response_verification") or {}).get("reason_codes") or [],
        )
        self.assertFalse(missing_work.success)
        self.assertIn(
            "derived_calculation_operand_projection_missing:1",
            (missing_work.data.get("response_verification") or {}).get("reason_codes") or [],
        )

