    def test_r356_period_correction_keeps_all_contextual_product_metrics(
        self,
    ) -> None:
        state = AgentSessionState(
            goal="Seçili ürünün satış özetini göster",
            active_domain="orders",
        )
        previous_fields = [
            "item_sales_quantity",
            "item_sales_order_count",
            "item_sales_amount",
            "currency",
        ]
        state.record_turn(
            role="user",
            content=(
                "Bu ürün son 30 günde kaç siparişte kaç adet satıldı ve "
                "brüt tutarı ne oldu?"
            ),
            mode="inspect",
            objective="Seçili ürünün son 30 günlük satış özetini göster",
            intent_kind="data_read",
            requested_fields=previous_fields,
            semantic_contract={
                "entity": "order",
                "metric": "summary",
                "record_scope": "all_matching",
                "period": "last_30_days",
                "freshness": "local_snapshot",
                "projection": previous_fields,
                "metric_requirements": [ORDER_ITEM_SALES_SUMMARY_METRIC],
                "contextual_item_identity_required": True,
            },
        )
        state.record_turn(
            role="assistant",
            content="Ürün satış özeti gösterildi.",
            mode="complete",
            objective="Seçili ürünün son 30 günlük satış özetini göster",
            tool_names=["orders.item_sales_summary"],
        )
        message = (
            "Pardon, ürün analizinde son 30 gün değil son 21 günü "
            "kastettim; aynı ürün için farklı sipariş sayısı, adet ve brüt "
            "tutarı düzeltilmiş dönemde tekrar göster, dosya yok."
        )

        interpreted = task_runtime.interpret_agent_turn(
            message,
            planner_client=lambda _prompt: json.dumps(
                {
                    "mode": "inspect",
                    "domain": "orders",
                    "objective": "Aynı ürün özetini düzeltilmiş dönemde göster",
                    "intent_kind": "data_read",
                    "request_shape": "focused_analysis",
                    # R356 model drift retained only one of three explicit
                    # contextual product metrics and the superseded period.
                    "requested_fields": ["item_sales_order_count"],
                    "direct_output_fields": [],
                    "entity": "order",
                    "metric": "item_order_count",
                    "status_scope": "all",
                    "record_scope": "all_matching",
                    "period": "last_30_days",
                    "freshness": "local_snapshot",
                    "information_source": "local_business_data",
                    "operation_policy": "allow_new_operations",
                    "calculation_count": 0,
                    "calculation_grouping": "none",
                    "reason": "Dönem düzeltmesi",
                    "requires_clarification": False,
                    "clarification": "",
                },
                ensure_ascii=False,
            ),
            session_state=state,
        )

        self.assertTrue(interpreted.success, interpreted.message)
        data = dict(interpreted.data or {})
        self.assertEqual(
            (data.get("mode"), data.get("intent_kind")),
            ("correct", "correction"),
        )
        contract = dict(data.get("semantic_contract") or {})
        self.assertEqual(contract.get("period"), "last_21_days")
        self.assertEqual(contract.get("metric"), "summary")
        self.assertTrue(contract.get("contextual_item_identity_required"))
        self.assertEqual(
            set(contract.get("projection") or []),
            set(previous_fields),
        )
        self.assertIsNone(
            task_runtime._explicit_bounded_recent_order_read_limit(message)
        )
        self.assertTrue(
            dict(data.get("correction_target") or {}).get("turn_id")
        )

    def test_r358_ready_and_terminal_nonfinal_counts_keep_distinct_metrics(
        self,
    ) -> None:
        message = (
            "lokal kayıtta şu an kargoya hazır kaç sipariş var, ayrıca "
            "bütün terminal olmayan siparişlerin toplamı kaç? ikisini ayrı "
            "söyle"
        )

        interpreted = task_runtime.interpret_agent_turn(
            message,
            planner_client=lambda _prompt: json.dumps(
                {
                    "mode": "inspect",
                    "domain": "orders",
                    "objective": (
                        "kargoya hazır ve terminal olmayan sipariş "
                        "sayılarını ayrı ayrı öğren"
                    ),
                    "intent_kind": "data_read",
                    "request_shape": "scalar",
                    # R358 drift treated the lifecycle word ``kargoya`` as a
                    # carrier projection and the scoped total as global.
                    "requested_fields": ["count", "cargo"],
                    "direct_output_fields": [],
                    "entity": "order",
                    "metric": "count",
                    "status_scope": "ready_to_ship",
                    "record_scope": "all_matching",
                    "period": "all",
                    "freshness": "local_snapshot",
                    "information_source": "local_business_data",
                    "operation_policy": "allow_new_operations",
                    "calculation_count": 0,
                    "calculation_grouping": "independent_results",
                    "reason": "İki bağımsız sayı istendi.",
                    "requires_clarification": False,
                    "clarification": "",
                },
                ensure_ascii=False,
            ),
        )

        self.assertTrue(interpreted.success, interpreted.message)
        data = dict(interpreted.data or {})
        contract = dict(data.get("semantic_contract") or {})
        self.assertEqual(data.get("requested_fields"), ["count"])
        self.assertNotIn("cargo", contract.get("projection") or [])
        self.assertEqual(
            set(contract.get("metric_requirements") or []),
            {
                ORDER_READY_TO_SHIP_COUNT_METRIC,
                ORDER_NONFINAL_COUNT_METRIC,
            },
        )
        self.assertNotIn(
            ORDER_TOTAL_COUNT_METRIC,
            contract.get("metric_requirements") or [],
        )
        self.assertTrue(task_runtime.nonfinal_orders_requested(message))
        self.assertFalse(
            task_runtime._goal_has_total_order_count_requirement(message)
        )
        self.assertTrue(
            task_runtime._goal_has_total_order_count_requirement(
                "Terminal olmayan siparişlerin toplamını ve ayrıca tüm "
                "siparişlerin toplamını söyle."
            )
        )

