    def test_derived_repair_receives_value_free_invalid_operand_reason(self) -> None:
        message = (
            "Yeni bir sipariş sorgusu çalıştırmadan önceki dağılımdaki "
            "Delivered siparişlerin 3112 toplam içindeki yüzdesini hesapla."
        )
        prompts: list[str] = []

        def planner(prompt: str) -> str:
            prompts.append(prompt)
            common = {
                "mode": "inspect",
                "domain": "orders",
                "objective": "Delivered sipariş yüzdesini hesapla",
                "intent_kind": "data_read",
                "request_shape": "focused_analysis",
                "requested_fields": ["calculation", "ratio"],
                "entity": "order",
                "metric": "derived",
                "status_scope": "delivered",
                "record_scope": "all_matching",
                "period": "all",
                "freshness": "local_snapshot",
                "information_source": "local_business_data",
                "operation_policy": "existing_observations_only",
                "reason": "Önceki durum dağılımından oran",
                "requires_clarification": False,
                "clarification": "",
            }
            if len(prompts) == 1:
                common["derived_calculation"] = {
                    "operator": "percentage",
                    "operands": [
                        {"ref": "literal", "value": 2957},
                        {"ref": "literal", "value": 3112},
                    ],
                    "result_kind": "percentage",
                    "precision": 2,
                    "show_work": True,
                }
            else:
                common["derived_calculation"] = {
                    "operator": "percentage",
                    "operands": [
                        {"ref": "orders.status_count", "member": "delivered"},
                        {"ref": "literal", "value": 3112},
                    ],
                    "result_kind": "percentage",
                    "precision": 2,
                    "show_work": True,
                }
            return json.dumps(common, ensure_ascii=False)

        interpreted = task_runtime.interpret_agent_turn(
            message,
            planner_client=planner,
        )

        self.assertTrue(interpreted.success, interpreted.message)
        self.assertEqual(len(prompts), 2)
        self.assertIn(
            "literal_not_in_current_message",
            prompts[1],
        )
        self.assertNotIn("2957", prompts[1])
        self.assertEqual(
            (interpreted.data or {}).get("decision_path"),
            "typed_model_turn_interpretation_derived_repaired",
        )
        self.assertTrue(
            ((interpreted.data or {}).get("derived_calculation_repair") or {}).get(
                "applied"
            )
        )

