    def test_exact_order_list_auto_binds_cardinality_and_rejects_partial_materialization(
        self,
    ) -> None:
        order_numbers = [f"ORD-EXACT-{index:02d}" for index in range(1, 12)]
        state = AgentSessionState(
            goal="güzel bu bekleyen 11 siparişi sipariş numaralarıyla listele",
            active_domain="orders",
        )
        step = AgentTaskStep(
            index=1,
            step_id="list_exact_orders",
            prompt=state.goal,
            objective=state.goal,
            operation_candidates=["orders.query"],
            operation_domain="orders",
            arguments={
                "mode": "list",
                "order_numbers": order_numbers,
            },
        )
        tool = available_tools()["orders.query"]

        kwargs, problems, bindings = task_runtime._resolve_step_arguments(
            state,
            step,
            tool,
            db_name=self.db_path,
        )

        self.assertEqual(problems, [])
        self.assertEqual(kwargs.get("limit"), 11)
        self.assertEqual(kwargs.get("offset"), 0)
        self.assertEqual(kwargs.get("page"), 1)
        self.assertEqual(
            bindings.get("limit"),
            "exact_order_numbers_cardinality",
        )

        partial_rows = [
            {"order_number": value}
            for value in order_numbers[:10]
        ]
        partial_data = {
            "mode": "tool",
            "answer": "10 siparis listelendi.",
            "tool_call": {
                "tool": "orders.query",
                "arguments": kwargs,
            },
            "tool_result": {
                "tool": "orders.query",
                "mode": "list",
                "count": 11,
                "orders": partial_rows,
                "pagination": {
                    "offset": 0,
                    "limit": 11,
                    "returned": 10,
                },
                "truncated": True,
            },
        }
        checked, checked_data = (
            task_runtime._reject_incomplete_exact_record_read(
                state,
                step,
                Result.ok(
                    "Query completed.",
                    close_dialog=False,
                    data=partial_data,
                ),
                partial_data,
            )
        )

        self.assertFalse(checked.success)
        checked_tool_result = dict(
            checked_data.get("tool_result") or {}
        )
        self.assertFalse(
            checked_tool_result.get("exact_materialization_valid")
        )
        self.assertEqual(
            checked_tool_result.get("missing_order_numbers"),
            [order_numbers[-1]],
        )
        self.assertEqual(
            checked_tool_result.get("materialized_record_count"),
            10,
        )

