    def test_turn_deadline_is_not_reinterpreted_as_user_clarification(
        self,
    ) -> None:
        calls = {"count": 0}

        def planner(_prompt: str) -> str:
            calls["count"] += 1
            planner.resource_plan.update(
                {
                    "actual_model": "",
                    "model_invocation_attempted": True,
                    "invocation_error_reason": "turn_deadline_exceeded",
                    "quota_scope": "runtime",
                    "fallback_blocked_reason": "turn_deadline_exceeded",
                    "normalized_error_history": [
                        {
                            "provider_code": "openrouter",
                            "category": "turn_deadline",
                            "retryable": False,
                            "quota_scope": "runtime",
                            "status_code": None,
                            "safe_message": (
                                "Cloud sohbet turunun süre bütçesi doldu."
                            ),
                            "model_fallback_allowed": False,
                        }
                    ],
                }
            )
            raise RuntimeError(
                "Cloud turn deadline exceeded before provider request."
            )

        planner.runtime_name = "openrouter_chat"
        planner.model_name = "deepseek/deepseek-v4-flash"
        planner.resource_plan = {
            "provider_code": "openrouter",
            "requested_model": planner.model_name,
            "allow_model_fallback": False,
        }

        result = task_runtime.interpret_agent_turn(
            "API'ye dokunmadan yerel siparişlerin genel özetini ver",
            planner_client=planner,
        )

        self.assertTrue(result.success, result.message)
        data = dict(result.data or {})
        self.assertEqual(calls["count"], 1)
        self.assertTrue(data.get("provider_unavailable"))
        self.assertEqual(data.get("mode"), "provider_unavailable")
        self.assertEqual(
            data.get("decision_path"),
            "typed_model_turn_provider_unavailable",
        )
        self.assertEqual(
            (data.get("provider_failure") or {}).get("category"),
            "turn_deadline",
        )
        answer = str(data.get("answer") or "")
        self.assertIn("süre bütçesini", answer)
        self.assertIn("kota veya bakiyenin bittiğini göstermez", answer)
        self.assertNotIn("bağlamında mı devam edeyim", answer)

