    def test_contextual_product_identity_bridge_requires_exact_selection_and_dependency(
        self,
    ) -> None:
        goal = (
            "Bu üründen tüm sipariş geçmişi boyunca toplam kaç adet satılmış? "
            "Siparişteki 1 adedi sormuyorum."
        )
        state = AgentSessionState(
            goal=goal,
            active_domain="orders",
            active_entities={
                "turn_interpretation": {
                    "mode": "inspect",
                    "domain": "orders",
                    "intent_kind": "data_read",
                    "requested_fields": ["item_sales_quantity"],
                    "semantic_contract": {
                        "entity": "order",
                        "metric": "item_quantity_total",
                        "status_scope": "all",
                        "record_scope": "all_matching",
                        "period": "all",
                        "projection": ["item_sales_quantity"],
                        "metric_requirements": [ORDER_ITEM_SALES_SUMMARY_METRIC],
                        "contextual_item_identity_required": True,
                    },
                }
            },
        )
        state.add_selection_snapshot(
            SelectionSnapshot.from_order_numbers(
                ["ORD-CONTEXT-PRODUCT"],
                source_tool="orders.full_context",
                listed_count=1,
                total_count=1,
                truncated=False,
            )
        )
        plan = GoalPlan.create(
            goal=goal,
            domain="orders",
            step_ids=["identity", "sales"],
            prompts=["Public ürün kimliğini çıkar", "Geçmiş satış adedini topla"],
            step_specs=[
                {
                    "operation_id": "orders.product_public_identities",
                    "arguments": {
                        "order_numbers": ["ORD-CONTEXT-PRODUCT"]
                    },
                    "depends_on": [],
                },
                {
                    "operation_id": "orders.item_sales_summary",
                    "arguments": {
                        "period": "all",
                        "product_identities": {
                            "$from_step": "identity",
                            "path": "tool_result.product_identities",
                        },
                    },
                    "depends_on": ["identity"],
                },
            ],
            source="llm_direct",
        )
        state.add_goal_plan(plan)

        allowed = semantic_verifier.verify_plan_step_semantics(
            state,
            plan.steps[0],
            available_tools()["orders.product_public_identities"],
            verifier_client=None,
        )
        self.assertTrue(allowed.success, allowed.data)
        evidence = dict(
            ((allowed.data or {}).get("semantic_verification") or {}).get(
                "evidence"
            )
            or {}
        )
        bridge = dict(evidence.get("contextual_identity_bridge") or {})
        self.assertTrue(bridge.get("active_selection_complete"), bridge)
        self.assertTrue(
            bridge.get("identity_target_matches_active_selection"),
            bridge,
        )
        self.assertTrue(bridge.get("downstream_item_sales_bound"), bridge)

        state.active_entities["turn_interpretation"]["requested_fields"] = [
            "item_sales_quantity",
            "item_sales_order_count",
            "item_sales_amount",
            "currency",
        ]
        state.active_entities["turn_interpretation"]["semantic_contract"] = {
            "entity": "order",
            "metric": "summary",
            "status_scope": "all",
            "record_scope": "all_matching",
            "period": "all",
            "projection": [
                "item_sales_quantity",
                "item_sales_order_count",
                "item_sales_amount",
                "currency",
            ],
            "metric_requirements": [ORDER_ITEM_SALES_SUMMARY_METRIC],
            "contextual_item_identity_required": True,
        }
        composite_allowed = semantic_verifier.verify_plan_step_semantics(
            state,
            plan.steps[0],
            available_tools()["orders.product_public_identities"],
            verifier_client=None,
        )
        self.assertTrue(composite_allowed.success, composite_allowed.data)
        composite_evidence = dict(
            (
                (composite_allowed.data or {}).get("semantic_verification")
                or {}
            ).get("evidence")
            or {}
        )
        self.assertEqual(
            set(
                (composite_evidence.get("contextual_identity_bridge") or {}).get(
                    "projection_fields"
                )
                or []
            ),
            {
                "item_sales_quantity",
                "item_sales_order_count",
                "item_sales_amount",
            },
        )

        plan.steps[0].arguments = {
            "order_numbers": ["ORD-MODEL-HALLUCINATION"]
        }
        rejected = semantic_verifier.verify_plan_step_semantics(
            state,
            plan.steps[0],
            available_tools()["orders.product_public_identities"],
            verifier_client=None,
        )
        self.assertFalse(rejected.success)
        self.assertIn(
            "typed_all_matching_scope_narrowed_by_exact_ids",
            list(
                ((rejected.data or {}).get("semantic_verification") or {}).get(
                    "reason_codes"
                )
                or []
            ),
        )

    def test_response_verifier_rejects_internal_contract_field_names(
        self,
    ) -> None:
        state = AgentSessionState(
            goal=(
                "Modo di Bellezza production mağazasında kaç sipariş "
                "var bekleyen?"
            ),
            active_domain="orders",
            active_entities={
                "turn_interpretation": {
                    "requested_fields": ["count", "scope"],
                }
            },
        )
        state.completed_steps.append(
            AgentTaskStep(
                index=1,
                step_id="ready_count",
                prompt="Bekleyen siparişleri say",
                status="completed",
                tool_names=["orders.ready_to_ship_count"],
                result_data={
                    "tool_result": {
                        "tool": "orders.ready_to_ship_count",
                        "count": 11,
                        "listed_count": 11,
                        "period_label": "all",
                        "account_scopes": [
                            {
                                "api_account_id": 1,
                                "store_name": "MDB",
                                "platform": "TRENDYOL",
                                "environment": "production",
                            }
                        ],
                    }
                },
            )
        )

        rejected = response_verifier.verify_response_projection(
            (
                "MDB production mağazasında 11 sipariş bekliyor. "
                "Kapsam: period_label: all."
            ),
            state,
        )
        rejected_enum = response_verifier.verify_response_projection(
            "all doneminde kargoya hazir 11 siparis var.",
            state,
        )
        accepted = response_verifier.verify_response_projection(
            (
                "MDB (TRENDYOL / production) mağazasında tüm dönemlerden "
                "kargoya hazır 11 sipariş bekliyor."
            ),
            state,
        )

        self.assertFalse(rejected.success)
        reason_codes = (
            (
                (rejected.data or {}).get("response_verification")
                or {}
            ).get("reason_codes")
            or []
        )
        self.assertIn(
            "internal_contract_field_exposed:period_label",
            reason_codes,
        )
        self.assertFalse(rejected_enum.success)
        enum_reason_codes = (
            (
                (rejected_enum.data or {}).get("response_verification")
                or {}
            ).get("reason_codes")
            or []
        )
        self.assertIn(
            "internal_period_enum_exposed:all",
            enum_reason_codes,
        )
        self.assertTrue(accepted.success, accepted.message)

    def test_valid_typed_read_uses_model_authored_atomic_plan_when_planner_exists(
        self,
    ) -> None:
        planner_prompts: list[str] = []

        def planner(prompt: str) -> str:
            planner_prompts.append(prompt)
            if prompt.startswith("Orders domain agent task plan"):
                self.assertIn("turn_semantic_contract", prompt)
                self.assertIn('"status_scope": "ready_to_ship"', prompt)
                return json.dumps(
                    {
                        "steps": [
                            {
                                "id": "count_ready",
                                "operation_id": "orders.ready_to_ship_count",
                                "arguments_json": '{"period":"all"}',
                                "depends_on": [],
                                "objective": "Bekleyen siparişleri say",
                                "expected_evidence": [
                                    "count",
                                    "order_numbers",
                                ],
                            }
                        ]
                    }
                )
            if prompt.startswith("GoalPlan observation"):
                return json.dumps(
                    {
                        "decision": "complete",
                        "reason": "Authoritative ready count observed.",
                        "clarification": "",
                        "steps": [],
                    }
                )
            raise AssertionError(prompt[:120])

        result = run_agent_task(
            "Modo di Bellezza mağazasında kaç sipariş var bekleyen?",
            db_name=self.db_path,
            planner_client=planner,
            turn_interpretation={
                "mode": "inspect",
                "domain": "orders",
                "objective": "Bekleyen sipariş sayısını getir",
                "intent_kind": "data_read",
                "requested_fields": ["count", "scope"],
                "requires_clarification": False,
                "valid": True,
                "decision_path": "typed_model_turn_interpretation",
                "semantic_contract": {
                    "entity": "order",
                    "metric": "count",
                    "status_scope": "ready_to_ship",
                    "period": "all",
                    "freshness": "local_snapshot",
                    "projection": ["count", "scope"],
                },
            },
        )

        self.assertTrue(result.success, f"{result.message} | {result.data}")
        state = dict((result.data or {}).get("state") or {})
        plan = dict(
            (state.get("active_entities") or {}).get("task_plan") or {}
        )
        self.assertEqual(plan.get("source"), "llm_direct")
        self.assertFalse(plan.get("model_plan_bypassed", False))
        self.assertEqual(
            plan.get("step_ids"),
            ["count_ready"],
        )
        self.assertEqual(
            [
                tool
                for step in state.get("completed_steps") or []
                for tool in step.get("tool_names") or []
            ],
            ["orders.ready_to_ship_count"],
        )
        self.assertEqual(
            sum(
                prompt.startswith("Orders domain agent task plan")
                for prompt in planner_prompts
            ),
            1,
        )

    def test_explicit_pending_control_is_typed_without_model_call(self) -> None:
        def unexpected_provider_call(_prompt: str) -> str:
            raise AssertionError("Pending action protocol must not call the model")

        cancel = task_runtime.interpret_agent_turn(
            "Vazgeç, bu işlemi iptal et.",
            planner_client=unexpected_provider_call,
        )
        approve = task_runtime.interpret_agent_turn(
            "Onayla ve çalıştır.",
            planner_client=unexpected_provider_call,
        )

        self.assertTrue(cancel.success, cancel.message)
        self.assertEqual((cancel.data or {}).get("mode"), "cancel")
        self.assertEqual((cancel.data or {}).get("intent_kind"), "approval_control")
        self.assertFalse((cancel.data or {}).get("planner_invoked"))
        self.assertTrue((cancel.data or {}).get("valid"))
        self.assertEqual(
            (cancel.data or {}).get("decision_path"),
            "typed_protocol_cancel",
        )
        self.assertTrue(approve.success, approve.message)
        self.assertEqual((approve.data or {}).get("mode"), "approve")
        self.assertEqual((approve.data or {}).get("intent_kind"), "approval_control")
        self.assertFalse((approve.data or {}).get("planner_invoked"))
        self.assertTrue((approve.data or {}).get("valid"))
        self.assertEqual(
            (approve.data or {}).get("decision_path"),
            "typed_protocol_approve",
        )

