    def test_malformed_typed_turn_repair_uses_guarded_json_directly(self) -> None:
        calls: list[str] = []

        def planner(_prompt: str) -> str:
            raise AssertionError("Typed planner must use a wired JSON contract")

        def invoke_structured(_prompt: str, *, schema: dict) -> str:
            calls.append(f"structured:{schema.get('type')}")
            return '{"mode":"inspect","domain":"orders"'

        def invoke_json_text(prompt: str, *, schema: dict) -> str:
            calls.append(f"guarded:{schema.get('type')}")
            self.assertTrue(
                prompt.startswith("OrderScout typed turn contract repair")
            )
            return json.dumps(
                {
                    "mode": "inspect",
                    "domain": "orders",
                    "objective": "Kargoya hazir siparis sayisini getir",
                    "intent_kind": "data_read",
                    "request_shape": "scalar",
                    "requested_fields": ["count"],
                    "entity": "order",
                    "metric": "count",
                    "status_scope": "ready_to_ship",
                    "record_scope": "all_matching",
                    "period": "all",
                    "freshness": "local_snapshot",
                    "information_source": "local_business_data",
                    "operation_policy": "allow_new_operations",
                    "calculation_count": 0,
                    "reason": "Kuyruk sayisi",
                    "requires_clarification": False,
                    "clarification": "",
                }
            )

        planner.invoke_structured = invoke_structured
        planner.invoke_json_text = invoke_json_text
        planner.resource_plan = {
            "capability_profile": {
                "native_tool_runtime_enabled": True,
                "structured_output_runtime_enabled": True,
            }
        }

        result = task_runtime.interpret_agent_turn(
            "Kargoya hazir kac siparis var?",
            planner_client=planner,
        )

        self.assertTrue(result.success, result.message)
        interpretation = dict(result.data or {})
        self.assertEqual(
            interpretation.get("decision_path"),
            "typed_model_turn_interpretation_repaired",
        )
        self.assertEqual(calls, ["structured:object", "guarded:object"])
        self.assertTrue(
            (interpretation.get("turn_interpretation_repair") or {}).get(
                "applied"
            )
        )

    def test_provider_error_without_model_response_does_not_trigger_turn_repair_request(self) -> None:
        calls = 0

        def unavailable_provider(_prompt: str) -> str:
            nonlocal calls
            calls += 1
            raise RuntimeError("provider account quota")

        result = task_runtime.interpret_agent_turn(
            "MDB production hesabinda bekleyen kac siparis var?",
            planner_client=unavailable_provider,
        )

        self.assertFalse(result.success)
        interpretation = dict(result.data or {})
        self.assertEqual(calls, 1)
        self.assertEqual(
            interpretation.get("decision_path"),
            "typed_model_turn_interpretation_failed",
        )
        repair = dict(interpretation.get("turn_interpretation_repair") or {})
        self.assertFalse(repair.get("invoked"))
        self.assertFalse(repair.get("applied"))
        self.assertEqual(repair.get("attempt_count"), 0)
        self.assertEqual(repair.get("initial_response_length"), 0)

