        self.assertEqual(meta.get("source"), "llm_direct_repaired")
        self.assertIn(
            "typed_read_metric_requirement_missing:"
            + ORDER_ITEM_SALES_REPORT_METRIC,
            meta.get("initial_plan_reason_codes") or [],
        )
        self.assertEqual(step_ids, ["report"])
        self.assertEqual(
            [row.get("operation_id") for row in meta.get("step_specs") or []],
            ["orders.item_sales_report"],
        )

