    def test_item_sales_report_and_no_file_boundary_survive_utf8_mojibake(self) -> None:
        message = (
            "Son 3 haftanın en çok satan ürünlerini adet ve ciro sırasıyla "
            "ilk 10 olarak çıkar; önce burada listele, dosya oluşturma."
        )
        mojibake = message.encode("utf-8").decode("latin-1")

        self.assertEqual(
            task_runtime._normalized(mojibake),
            task_runtime._normalized(message),
        )
        self.assertTrue(task_runtime._goal_has_item_sales_report_intent(mojibake))
        self.assertTrue(task_runtime._goal_prohibits_report_export(mojibake))
        self.assertFalse(task_runtime._goal_has_report_export_intent(mojibake))

