    def test_item_sales_snapshot_projects_all_rows_and_persists_typed_analysis(self) -> None:
        snapshot = {
            "report_type": "orders.item_sales",
            "metadata": {"period_label": "2026-07-01..2026-07-21"},
            "sheets": [
                {
                    "name": "En Cok Satanlar",
                    "columns": [
                        {"key": "rank"},
                        {"key": "product_name"},
                        {"key": "quantity"},
                        {"key": "order_count"},
                        {"key": "gross_amount"},
                        {"key": "currency"},
                    ],
                    "rows": [
                        [1, "Urun A", 20, 18, 1234.5, "TRY"],
                        [2, "Urun B", 11, 10, 987.65, "TRY"],
                    ],
                }
            ],
        }
        tool_result = {
            "tool": "orders.item_sales_report",
            "report_snapshot": snapshot,
            "snapshot_id": "rpt-test",
            "content_hash": "hash-test",
            "period": "last_21_days",
            "period_label": "2026-07-01..2026-07-21",
            "row_count": 2,
            "order_count": 28,
            "product_count": 2,
            "total_quantity": 31,
            "account_scopes": [
                {
                    "api_account_id": 1,
                    "account_id": "784195",
                    "store_name": "MDB",
                    "platform": "TRENDYOL",
                    "environment": "production",
                }
            ],
        }
        state = AgentSessionState(
            goal="Son 21 günün en çok satanlarını listele",
            active_domain="orders",
            status="complete",
            active_entities={
                "turn_interpretation": {
                    "mode": "inspect",
                    "requested_fields": ["item_sales_rows", "scope"],
                }
            },
        )
        step = AgentTaskStep(
            index=1,
            step_id="orders.item_sales.report",
            prompt=state.goal,
            operation_domain="orders",
            status="completed",
            tool_names=["orders.item_sales_report"],
            result_data={"tool_result": tool_result},
        )
        state.completed_steps = [step]

        observation = task_runtime._record_typed_step_observation(
            state,
            step=step,
            data={
                "tool_call": {"tool": "orders.item_sales_report"},
                "tool_result": tool_result,
            },
            result=Result.ok("Rapor hazır", close_dialog=False),
        )
        self.assertIsNotNone(observation)
        self.assertEqual(len(state.analysis_contexts), 1)
        self.assertEqual(
            state.analysis_contexts[0].facts.get("report_snapshot"),
            snapshot,
        )
        self.assertEqual(state.active_scopes["orders"].environments, ("production",))

        partial = response_verifier.verify_response_projection(
            "1. Urun A | adet: 20 | siparis: 18 | brut: 1234.5 TRY",
            state,
            source="partial_test",
        )
        fallback = response_verifier.project_fallback_response(state, "")
        verified = response_verifier.verify_response_projection(
            fallback,
            state,
            source="fallback_test",
        )
        self.assertFalse(partial.success)
        self.assertIn("requested_item_sales_rows_missing:1", str(partial.data))
        self.assertIn("Urun A | adet: 20 | siparis: 18 | brut: 1234.5 TRY", fallback)
        self.assertIn("Urun B | adet: 11 | siparis: 10 | brut: 987.65 TRY", fallback)
        self.assertIn("Kapsam: MDB (TRENDYOL / production).", fallback)
        self.assertTrue(verified.success, verified.data)

        contextual_state = AgentSessionState(
            goal="Bu doğrulanmış listeyi Excel'e hazırla",
            active_domain="orders",
            active_entities={
                "prior_authoritative_context": [
                    row["context"]
                    for row in state.authoritative_context_rows()
                ]
            },
        )
        found, bound_snapshot, source = task_runtime._state_context_binding_value(
            contextual_state,
            "report_snapshot",
        )
        self.assertTrue(found)
        self.assertEqual(bound_snapshot, snapshot)
        self.assertEqual(source, "analysis_context")

