    def test_contextual_order_ordinals_resolve_against_display_order(self) -> None:
        ordered = ["ORD-1", "ORD-2", "ORD-3", "ORD-4"]
        cases = (
            ("listedeki ikinci sipariş", ["ORD-2"], "ordered_index_2"),
            ("3. sıradaki sipariş", ["ORD-3"], "ordered_index_3"),
            ("son sıradaki sipariş", ["ORD-4"], "ordered_index_4"),
            ("ilk 2 sipariş", ["ORD-1", "ORD-2"], "ordered_first_2"),
        )
        for prompt, expected, qualifier in cases:
            with self.subTest(prompt=prompt):
                selected, binding = task_runtime._contextual_order_subset(
                    prompt,
                    ordered,
                )
                self.assertEqual(selected, expected)
                self.assertEqual(binding, qualifier)

