    def test_full_context_rejects_rows_outside_resolved_exact_order_set(self) -> None:
        state = AgentSessionState(
            goal="Listedeki ilk sıradaki siparişi göster",
            active_domain="orders",
        )
        step = AgentTaskStep(
            index=1,
            step_id="detail",
            prompt=state.goal,
            objective=state.goal,
            operation_candidates=["orders.full_context"],
            operation_domain="orders",
            arguments={"order_numbers": ["ORD-1"]},
        )
        data = {
            "tool_call": {
                "tool": "orders.full_context",
                "arguments": {"order_numbers": ["ORD-1"]},
            },
            "tool_result": {
                "count": 2,
                "contexts": [
                    {"order": {"order_number": "ORD-1"}},
                    {"order": {"order_number": "ORD-2"}},
                ],
            },
        }
        result = Result.ok("adapter returned two rows", data=data)

        guarded_result, guarded_data = (
            task_runtime._reject_incomplete_exact_record_read(
                state,
                step,
                result,
                data,
            )
        )

        self.assertFalse(guarded_result.success)
        guarded_tool_result = guarded_data.get("tool_result") or {}
        self.assertEqual(
            guarded_tool_result.get("unexpected_order_numbers"),
            ["ORD-2"],
        )
        self.assertFalse(guarded_tool_result.get("exact_materialization_valid"))

