    def test_model_cannot_invent_or_override_population_calendar_scope(
        self,
    ) -> None:
        def interpretation_payload(period: str) -> str:
            return json.dumps(
                {
                    "mode": "inspect",
                    "domain": "orders",
                    "objective": "Sipariş nüfusunu analiz et",
                    "intent_kind": "data_read",
                    "requested_fields": [
                        "count",
                        "status",
                        "amount",
                        "item_sales_rows",
                    ],
                    "entity": "order",
                    "metric": "count",
                    "status_scope": "all",
                    "record_scope": "all_matching",
                    "period": period,
                    "freshness": "local_snapshot",
                    "reason": "Population analysis",
                    "requires_clarification": False,
                    "clarification": "",
                }
            )

        unqualified = task_runtime.interpret_agent_turn(
            "Toplam kaç siparişim var? Durum dağılımını, toplam cirosunu ve "
            "en çok satan ürünlerini birlikte analiz et.",
            planner_client=lambda _prompt: interpretation_payload("today"),
        )
        explicit_today = task_runtime.interpret_agent_turn(
            "Bugünkü toplam sipariş sayımı, durum dağılımını, cirosunu ve en çok "
            "satan ürünlerini birlikte analiz et.",
            planner_client=lambda _prompt: interpretation_payload("all"),
        )

        self.assertTrue(unqualified.success, unqualified.message)
        self.assertTrue(explicit_today.success, explicit_today.message)
        self.assertEqual(
            (unqualified.data or {}).get("semantic_contract", {}).get("period"),
            "all",
        )
        self.assertEqual(
            (explicit_today.data or {}).get("semantic_contract", {}).get("period"),
            "today",
        )

