    def test_verified_model_authored_read_plan_advances_without_goal_model_call(
        self,
    ) -> None:
        state = AgentSessionState(
            goal="Toplam siparisleri genel olarak analiz et",
            active_domain="orders",
        )
        plan = GoalPlan.create(
            goal=state.goal,
            domain="orders",
            step_ids=["count", "summary"],
            prompts=["Toplam siparis sayisini getir", "Genel ozeti getir"],
            step_specs=[
                {
                    "id": "count",
                    "operation_id": "orders.count",
                    "operation_domain": "orders",
                    "depends_on": [],
                    "expected_evidence": ["count"],
                },
                {
                    "id": "summary",
                    "operation_id": "orders.summary",
                    "operation_domain": "orders",
                    "depends_on": [],
                    "expected_evidence": [
                        "total_orders",
                        "status_counts",
                        "estimated_revenue",
                    ],
                },
            ],
            source="llm_direct",
        )
        state.add_goal_plan(plan)
        step = plan.steps[0]
        step.status = "completed"
        step.verification_status = "observed"
        step.result_data = {"tool_result": {"count": 3112}}
        state.completed_steps = [step]
        state.remaining_steps = [plan.steps[1]]
        observation = Observation.create(
            domain="orders",
            operation_name="orders.count",
            success=True,
            aggregates={"count": 3112},
            source="local_db",
        )
        calls = {"count": 0}

        def planner(_prompt: str) -> str:
            calls["count"] += 1
            raise AssertionError("verified happy-path plan must not call goal evaluator")

        evaluation = task_runtime._reevaluate_goal_after_observation(
            state,
            step,
            observation,
            planner_client=planner,
            max_steps=4,
            max_replans=1,
        )

        self.assertEqual(calls["count"], 0)
        self.assertEqual(evaluation.get("decision"), "continue")
        self.assertFalse(evaluation.get("applied"))
        self.assertFalse(evaluation.get("model_invoked"))
        self.assertTrue(evaluation.get("deterministic_progress"))
        self.assertEqual(
            evaluation.get("reason"),
            "verified_expected_evidence_independent_plan_continues",
        )

