    def test_business_advice_does_not_turn_finance_movement_into_bank_balance(self) -> None:
        state = AgentSessionState(goal="Finansı incele", active_domain="finance")
        state.completed_steps = [AgentTaskStep(
            index=1, prompt=state.goal, status="completed",
            tool_names=["finance.cashflow_summary"],
            result_data={"tool_result": {"period": "all"}},
        )]
        answer = "Banka bakiyeni bu hareketlerden çıkaramayız; gerçekleşmiş tahsilatı ayrıca kontrol et."
