        self.assertEqual(result.data["answer"], answer)
        self.assertTrue(result.data["response_synthesis"]["candidate_accepted"])
        replies = iter(("Banka bakiyen 50 USD.", answer))
        repaired = task_runtime.run_model_conversation_turn(
            "Paramı artırmak için ne önerirsin?", mode="chat",
            objective="Finans verisiyle sınırlı öneri ver",
            chat_client=lambda _prompt: next(replies), session_state=state,
        )
        self.assertTrue(repaired.success, repaired.message)
        self.assertEqual(repaired.data["answer"], answer)
        self.assertIn(
            "financial_movement_implies_bank_balance",
            repaired.data["response_synthesis"]["candidate_projection_reason_codes"],
        )

