    def test_non_business_responder_rejects_ungrounded_operational_state_claim(
        self,
    ) -> None:
        result = task_runtime.run_model_conversation_turn(
            "Başkan selam, bugün sipariş tarafında beraber çalışacağız; naber?",
            mode="chat",
            objective="Selamlaş ve sipariş çalışmasına hazırlan",
            chat_client=lambda _prompt: (
                "Başkan selam! Siparişler hazır, ne yapacağımızı söyle yeter."
            ),
        )

        self.assertTrue(result.success, result.message)
        data = dict(result.data or {})
        self.assertEqual(
            data.get("answer"),
            "İyiyim başkan, hazırım. Sipariş tarafında nereden başlayalım?",
        )
        self.assertIn(
            "ungrounded_non_business_state_to_safe_conversation",
            data.get("response_semantic_corrections") or [],
        )
        synthesis = dict(data.get("response_synthesis") or {})
        self.assertFalse(synthesis.get("candidate_accepted"))
        self.assertEqual(
            synthesis.get("candidate_projection_reason_codes"),
            ["unsupported_non_business_operational_state_claim"],
        )
        self.assertTrue(synthesis.get("final_projection_verified"))
        self.assertEqual(
            synthesis.get("final_source"),
            "deterministic_verified_non_business_fallback",
        )

