    def test_empty_broad_analysis_is_authoritative_and_projects_its_scope(
        self,
    ) -> None:
        state = self._completed_response_state(
            goal="Bugün siparişlerde ne var ne yok bakalım.",
            operation="orders.summary",
            tool_result={
                "period": "today",
                "period_label": "2026-08-04",
                "total_orders": 0,
                "status_counts": {},
                "estimated_revenue": 0.0,
                "currency": "TRY",
                "cancellation_rate": 0.0,
                "average_revenue_per_order": 0.0,
            },
            authoritative_answer="Bugünkü sipariş özeti hazır.",
            requested_fields=[
                "count",
                "status",
                "amount",
                "currency",
                "item_sales_rows",
            ],
        )
        state.active_entities["turn_interpretation"]["semantic_contract"] = {
            "entity": "order",
            "metric": "summary",
            "record_scope": "all_matching",
            "period": "today",
            "projection": [
                "count",
                "status",
                "amount",
                "currency",
                "item_sales_rows",
            ],
            "metric_requirements": [
                ORDER_TOTAL_COUNT_METRIC,
                ORDER_STATUS_DISTRIBUTION_METRIC,
                ORDER_REVENUE_TOTAL_METRIC,
                ORDER_ITEM_SALES_SUMMARY_METRIC,
            ],
        }
        state.completed_steps.append(
            AgentTaskStep(
                index=2,
                step_id="item_sales",
                prompt=state.goal,
                status="completed",
                tool_names=["orders.item_sales_summary"],
                result_data={
                    "tool_result": {
                        "rows": [],
                        "period": "today",
                        "period_label": "2026-08-04",
                        "order_count": 0,
                        "matched_order_count": 0,
                        "total_quantity": 0,
                        "leading_five_quantity": 0,
                        "leading_five_quantity_share": 0.0,
                        "total_gross_amount": 0.0,
                    }
                },
            )
        )

        fallback = response_verifier.project_fallback_response(state, "")
        verified = response_verifier.verify_response_projection(
            fallback,
            state,
            source="verified_fallback",
        )
        incomplete = response_verifier.verify_response_projection(
            "Toplam 0 siparis var. Tahmini ciro: 0 TRY.",
            state,
            source="model_candidate",
        )

        self.assertIn("Toplam 0 siparis var", fallback)
        self.assertIn("2026-08-04 siparis durum dagilimi bos", fallback)
        self.assertIn("2026-08-04 siparis kalemi satisi yok", fallback)
        self.assertIn("Tahmini ciro: 0", fallback)
        self.assertNotIn("Analitik yorum", fallback)
        self.assertTrue(verified.success, verified.data)
        self.assertFalse(incomplete.success)
        reasons = list(
            (
                (incomplete.data or {}).get("response_verification") or {}
            ).get("reason_codes")
            or []
        )
        self.assertIn(
            "empty_status_distribution_projection_missing",
            reasons,
        )
        self.assertIn("empty_item_sales_projection_missing", reasons)

