    def test_two_hundred_visible_chat_messages_keep_complete_typed_trace(self) -> None:
        state = AgentSessionState(goal="Long conversation", active_domain="orders")
        payload: dict[str, Any] = state.to_dict()
        history: list[dict[str, str]] = []
        for index in range(1, 101):
            user = f"Kullanici mesaji {index}"
            assistant = f"Asistan cevabi {index}"
            history.append({"role": "user", "content": user})
            result = task_runtime.run_model_conversation_turn(
                user,
                mode="chat",
                objective=f"Sohbet turu {index}",
                chat_client=lambda _prompt, value=assistant: value,
                history=history,
                session_state=payload,
            )
            self.assertTrue(result.success, result.message)
            payload = dict((result.data or {}).get("session_state") or {})
            history.append({"role": "assistant", "content": assistant})

        returned = AgentSessionState.from_dict(payload)
        self.assertEqual(len(returned.conversation_turns), 200)
        self.assertEqual(returned.conversation_turns[0].content, "Kullanici mesaji 1")
        self.assertEqual(returned.conversation_turns[-1].content, "Asistan cevabi 100")
        self.assertEqual(
            len(
                [
                    event
                    for event in returned.state_events
                    if event.event_type == "conversation_turn"
                ]
            ),
            200,
        )

