    def _completed_response_state(
        self,
        *,
        goal: str,
        operation: str,
        tool_result: dict,
        authoritative_answer: str,
        requested_fields: list[str],
    ) -> AgentSessionState:
        state = AgentSessionState(
            goal=goal,
            active_domain="orders",
            status="complete",
            active_entities={
                "turn_interpretation": {
                    "mode": "inspect",
                    "domain": "orders",
                    "objective": goal,
                    "requested_fields": list(requested_fields),
                    "requires_clarification": False,
                    "valid": True,
                }
            },
        )
        state.completed_steps = [
            AgentTaskStep(
                index=1,
                step_id="response_test",
                prompt=goal,
                status="completed",
                result_message=authoritative_answer,
                tool_names=[operation],
                result_data={
                    "answer": authoritative_answer,
                    "tool_result": dict(tool_result),
                },
            )
        ]
        return state

    def test_r66_response_projection_never_confuses_total_ready_and_query_metrics(
        self,
    ) -> None:
        state = self._completed_response_state(
            goal=(
                "güzel, güncel siparişler genel olarak ne durumda? mağaza ve ortamı "
                "da söyle, toplam sipariş ile kargoya hazır sayıyı atlama"
            ),
            operation="orders.count",
            tool_result={
                "count": 3112,
                "account_scopes": [
                    {
                        "api_account_id": 1,
                        "store_name": "MDB",
                        "platform": "TRENDYOL",
                        "environment": "production",
                    }
                ],
            },
            authoritative_answer="Toplam 3112 sipariş var.",
            requested_fields=["count", "store", "status", "scope"],
        )
        state.active_entities["turn_interpretation"]["semantic_contract"] = {
            "entity": "order",
            "metric": "count",
            "status_scope": "ready_to_ship",
            "period": "all",
            "projection": ["count", "store", "status", "scope"],
            "metric_requirements": [
                ORDER_TOTAL_COUNT_METRIC,
                ORDER_READY_TO_SHIP_COUNT_METRIC,
                ORDER_STATUS_DISTRIBUTION_METRIC,
            ],
        }
        state.completed_steps.extend(
            [
                AgentTaskStep(
                    index=2,
                    step_id="ready",
                    prompt="Kargoya hazır sayısı",
                    status="completed",
                    result_message="Kargoya hazır 12 sipariş var.",
                    tool_names=["orders.ready_to_ship_count"],
                    result_data={"tool_result": {"count": 12}},
                ),
                AgentTaskStep(
                    index=3,
                    step_id="sample_query",
                    prompt="Örnek siparişler",
                    status="completed",
                    result_message="Filtreli örnek bulunamadı.",
                    tool_names=["orders.query"],
                    result_data={
                        "tool_result": {
                            "count": 0,
                            "total_count": 0,
                            "status_counts": {
                                "ReadyToShip": 0,
                                "Shipped": 0,
                            },
                        }
                    },
                ),
            ]
        )

        incomplete = response_verifier.verify_response_projection(
            (
                "Kargoya hazır 12 sipariş var. Mağaza: MDB. "
                "Kapsam: MDB (TRENDYOL / production)."
            ),
            state,
            source="model_candidate",
        )

        self.assertFalse(incomplete.success)
        reasons = list(
            (
                (incomplete.data or {}).get("response_verification") or {}
            ).get("reason_codes")
            or []
        )
        self.assertIn("total_order_projection_missing", reasons)
        self.assertIn("status_distribution_evidence_missing", reasons)
        fallback_without_distribution = response_verifier.project_fallback_response(
            state,
            "Özet hazırlanamadı.",
        )
        self.assertIn("Toplam 3112 siparis", fallback_without_distribution)
        self.assertIn("Kargoya hazir 12 siparis", fallback_without_distribution)
        self.assertIn(
            "durum dagilimi authoritative sonuc icinde bulunamadi",
            fallback_without_distribution,
        )
        self.assertNotIn("Shipped 0", fallback_without_distribution)

        state.completed_steps.append(
            AgentTaskStep(
                index=4,
                step_id="status_distribution",
                prompt="Genel durum dağılımı",
                status="completed",
                result_message="Durum dağılımı hazır.",
                tool_names=["orders.status_counts"],
                result_data={
                    "tool_result": {
                        "total_orders": 3112,
                        "status_counts": {
                            "Delivered": 3000,
                            "ReadyToShip": 12,
                            "Shipped": 100,
                        },
                    }
                },
            )
        )
        complete_fallback = response_verifier.project_fallback_response(
            state,
            "Özet hazır.",
        )

        self.assertIn("Toplam 3112 siparis", complete_fallback)
        self.assertIn("Kargoya hazir 12 siparis", complete_fallback)
        self.assertIn("Delivered 3000", complete_fallback)
        self.assertIn("ReadyToShip 12", complete_fallback)
        self.assertIn("Shipped 100", complete_fallback)
        verified = response_verifier.verify_response_projection(
            complete_fallback,
            state,
            source="verified_fallback",
        )
        self.assertTrue(verified.success, verified.data)

