    def test_task_finalization_prefers_provider_final_text_contract(self) -> None:
        state = self._completed_response_state(
            goal="Kargoya hazir siparis sayisini getir",
            operation="orders.ready_to_ship_count",
            tool_result={"count": 3},
            authoritative_answer="Kargoya hazir 3 siparis var.",
            requested_fields=["count"],
        )

        class FinalTextClient:
            def __init__(self) -> None:
                self.final_prompts: list[str] = []

            def __call__(self, _prompt: str) -> str:
                raise AssertionError("ordinary text contract must not render task final")

            def invoke_final_text(self, prompt: str) -> str:
                self.final_prompts.append(prompt)
                return "Kargoya hazir 3 siparis var."

        client = FinalTextClient()
        answer = task_runtime._finalize_task_answer(
            state,
            chat_client=client,
        )

        self.assertEqual(answer, "Kargoya hazir 3 siparis var.")
        self.assertEqual(len(client.final_prompts), 1)
        synthesis = dict(state.active_entities.get("response_synthesis") or {})
        self.assertEqual(synthesis.get("final_source"), "verified_model_candidate")

    def test_timed_out_model_final_uses_verified_authoritative_fallback(self) -> None:
        state = self._completed_response_state(
            goal="Kargoya hazir siparis sayisini getir",
            operation="orders.ready_to_ship_count",
            tool_result={"count": 3},
            authoritative_answer="Kargoya hazir 3 siparis var.",
            requested_fields=["count"],
        )

        def timed_out_client(_prompt: str) -> str:
            raise TimeoutError("provider request timed out")

        answer = task_runtime._finalize_task_answer(
            state,
            chat_client=timed_out_client,
        )

        self.assertEqual(answer, "Kargoya hazir 3 siparis var.")
        synthesis = dict(
            state.active_entities.get("response_synthesis") or {}
        )
        self.assertEqual(synthesis.get("reason"), "model_synthesis_error")
        self.assertEqual(synthesis.get("error_type"), "TimeoutError")
        self.assertEqual(
            synthesis.get("final_source"),
            "deterministic_verified_projection",
        )
        self.assertTrue(synthesis.get("fallback_projection_verified"))

