    def test_full_context_requires_explicit_zero_return_projection(self) -> None:
        state = self._completed_response_state(
            goal="Bu listedeki en son siparisin kalem, kargo ve iade baglamini goster",
            operation="orders.full_context",
            tool_result={
                "contexts": [
                    {
                        "order": {
                            "order_number": "ORD-CONTEXT-1",
                            "status": "ReadyToShip",
                            "cargo_provider": "Trendyol Express",
                            "cargo_tracking_number": "TRK-CONTEXT-1",
                        },
                        "items": [
                            {"product_name": "Test Urunu", "quantity": 1}
                        ],
                        "returns": [],
                    }
                ]
            },
            authoritative_answer="Siparis tam baglami hazir: 1 kalem, 0 iade.",
            requested_fields=[
                "order_number",
                "item",
                "cargo",
                "tracking_number",
                "returns",
            ],
        )

        missing = response_verifier.verify_response_projection(
            "ORD-CONTEXT-1: Test Urunu, Trendyol Express, TRK-CONTEXT-1.",
            state,
            source="model_candidate",
        )
        grounded = response_verifier.verify_response_projection(
            "ORD-CONTEXT-1: Test Urunu, Trendyol Express, TRK-CONTEXT-1. Iade kaydi yok.",
            state,
            source="model_candidate",
        )
        expanded_placeholders = response_verifier.verify_response_projection(
            (
                "Sipariş ORD-CONTEXT-1 detayları:\n"
                "**Müşteri Adı:** [Veri gizliliği gereği kayıtlı isim]\n"
                "**Sipariş Tarihi:** [Sistem kayıt tarihi]\n"
                "**Ürün:** Test Urunu\n"
                "**Tutar:** 299.99 TRY\n"
                "**Teslimat Adresi:** [Sistemde kayıtlı adres]\n"
                "**Durum:** Kargoya Hazır"
            ),
            state,
            source="model_candidate",
        )
        fallback = response_verifier.project_fallback_response(
            state,
            "Siparis tam baglami hazir.",
        )

        self.assertFalse(missing.success)
        self.assertIn(
            "return_context_projection_missing",
            list(
                ((missing.data or {}).get("response_verification") or {}).get(
                    "reason_codes"
                )
                or []
            ),
        )
        self.assertTrue(grounded.success, grounded.data)
        self.assertFalse(expanded_placeholders.success)
        expanded_reasons = list(
            (
                (expanded_placeholders.data or {}).get("response_verification")
                or {}
            ).get("reason_codes")
            or []
        )
        self.assertIn("unrequested_field_label:customer_name", expanded_reasons)
        self.assertIn("unrequested_field_label:address", expanded_reasons)
        self.assertIn("unrequested_field_label:date", expanded_reasons)
        self.assertIn("unrequested_field_label:amount", expanded_reasons)
        self.assertIn("unrequested_field_label:status", expanded_reasons)
        self.assertIn("Test Urunu", fallback)
        self.assertIn("Trendyol Express", fallback)
        self.assertIn("Iade kaydi yok", fallback)

    def test_full_context_quantity_cargo_and_tracking_are_all_verified(self) -> None:
        state = self._completed_response_state(
            goal=(
                "listedeki ilk siparisin urun icerigini, adetini, kargo "
                "firmasini ve takip numarasini goster"
            ),
            operation="orders.full_context",
            tool_result={
                "contexts": [
                    {
                        "order": {
                            "order_number": "ORD-DETAIL-1",
                            "cargo_provider": "Trendyol Express Marketplace",
                            "cargo_tracking_number": "TRK-DETAIL-987",
                        },
                        "items": [
                            {
                                "product_name": "20 Adet Musluk Contasi",
                                "quantity": 2,
                            }
                        ],
                        "returns": [],
                    }
                ]
            },
            authoritative_answer="Siparis tam baglami hazir.",
            requested_fields=[
                "item",
                "quantity",
                "cargo",
                "tracking_number",
            ],
        )

        incomplete = response_verifier.verify_response_projection(
            "20 Adet Musluk Contasi | adet: 2",
            state,
            source="model_candidate",
        )
        complete = response_verifier.verify_response_projection(
            "20 Adet Musluk Contasi | adet: 2 | Trendyol Express Marketplace "
            "| TRK-DETAIL-987",
            state,
            source="model_candidate",
        )
        natural_multiline = response_verifier.verify_response_projection(
            "Urun: 20 Adet Musluk Contasi\nAdet: 2\n"
            "Kargo: Trendyol Express Marketplace\nTakip: TRK-DETAIL-987",
            state,
            source="model_candidate",
        )
        fallback = response_verifier.project_fallback_response(
            state,
            "Siparis tam baglami hazir.",
        )
        fallback_verification = response_verifier.verify_response_projection(
            fallback,
            state,
            source="verified_fallback",
        )

        self.assertFalse(incomplete.success)
        reasons = list(
            ((incomplete.data or {}).get("response_verification") or {}).get(
                "reason_codes"
            )
            or []
        )
        self.assertIn("cargo_projection_missing:ORD-DETAIL-1", reasons)
        self.assertIn("tracking_projection_missing:ORD-DETAIL-1", reasons)
        self.assertTrue(complete.success, complete.data)
        self.assertTrue(natural_multiline.success, natural_multiline.data)
        self.assertIn("20 Adet Musluk Contasi", fallback)
        self.assertIn("adet: 2", fallback)
        self.assertIn("Trendyol Express Marketplace", fallback)
        self.assertIn("TRK-DETAIL-987", fallback)
        self.assertTrue(fallback_verification.success, fallback_verification.data)

