    def test_response_verifier_rejects_ungrounded_number_and_identifier(self) -> None:
        state = self._completed_response_state(
            goal="Kargoya hazir kac siparis var?",
            operation="orders.ready_to_ship_count",
            tool_result={"count": 3},
            authoritative_answer="Kargoya hazir 3 siparis var.",
            requested_fields=["count"],
        )

        answer = task_runtime._finalize_task_answer(
            state,
            chat_client=lambda _prompt: "Kargoya hazir 4 siparis var; biri ORD-FAKE-999.",
        )

        self.assertEqual(answer, "Kargoya hazir 3 siparis var.")
        checks = (state.active_entities.get("response_verifications") or [])
        reasons = [code for row in checks for code in (row.get("reason_codes") or [])]
        self.assertTrue(any(code.startswith("ungrounded_number:4") for code in reasons), reasons)
        self.assertTrue(any(code.startswith("ungrounded_identifier:ORD-FAKE-999") for code in reasons), reasons)

    def test_response_verifier_accepts_locale_grouped_authoritative_integer(self) -> None:
        state = self._completed_response_state(
            goal="Tüm siparişlerin genel özetini ver",
            operation="orders.summary",
            tool_result={"total_orders": 3112, "dominant_status_rate": 94.79},
            authoritative_answer="Toplam 3112 sipariş var.",
            requested_fields=["count"],
        )

        verification = response_verifier.verify_response_projection(
            "Toplam 3.112 sipariş var.",
            state,
            source="model_candidate",
        )

        self.assertTrue(verification.success, verification.data)
        self.assertNotIn(
            "ungrounded_number:3.112",
            list((verification.data or {}).get("reason_codes") or []),
        )

        natural_wording = response_verifier.verify_response_projection(
            "3.112 siparisi analiz ettim.",
            state,
            source="model_candidate",
        )
        self.assertTrue(natural_wording.success, natural_wording.data)

        rate_wording = response_verifier.verify_response_projection(
            "Toplam siparislerin %94,79'u ana grupta; 3.112 siparisi analiz ettim.",
            state,
            source="model_candidate",
        )
        self.assertTrue(rate_wording.success, rate_wording.data)

    def test_response_verifier_accepts_locale_grouped_decimal_amount(self) -> None:
        state = self._completed_response_state(
            goal="Sipariş cirosunu ver",
            operation="orders.revenue_total",
            tool_result={"total_revenue": 37934038.55},
            authoritative_answer="Ciro 37934038.55 TRY.",
            requested_fields=["amount"],
        )

        verification = response_verifier.verify_response_projection(
            "Ciro 37.934.038,55 TRY.",
            state,
            source="model_candidate",
        )

        self.assertTrue(verification.success, verification.data)

        short_fraction = self._completed_response_state(
            goal="Siparis cirosunu ver",
            operation="orders.revenue_total",
            tool_result={"total_revenue": 3859.5},
            authoritative_answer="Ciro 3859.5 TRY.",
            requested_fields=["amount"],
        )
        localized = response_verifier.verify_response_projection(
            "Ciro 3.859,50 TRY.",
            short_fraction,
            source="model_candidate",
        )
        self.assertTrue(localized.success, localized.data)

        missing = response_verifier.verify_response_projection(
            "Ciro verisi incelendi.",
            state,
            source="model_candidate",
        )
        self.assertFalse(missing.success)
        self.assertIn(
            "amount_projection_missing",
            list(
                (
                    (missing.data or {}).get("response_verification") or {}
                ).get("reason_codes")
                or []
            ),
        )

