    def test_cargo_provider_options_require_complete_names_and_reject_fake_date(self) -> None:
        state = self._completed_response_state(
            goal="Bu 2 hazır sipariş için uygun kargo firması seçeneklerini göster",
            operation="orders.cargo_provider_options",
            tool_result={
                "count": 2,
                "providers": [
                    {"code": "ARASMP", "name": "Aras Kargo Marketplace"},
                    {"code": "YKMP", "name": "Yurtici Kargo Marketplace"},
                ],
            },
            authoritative_answer="2 kargo firması bulundu.",
            requested_fields=["cargo_options"],
        )

        incomplete = response_verifier.verify_response_projection(
            "2 Haziran için 2 kargo seçeneği bulundu.",
            state,
            source="model_candidate",
        )
        complete = response_verifier.verify_response_projection(
            "Seçenekler: Aras Kargo Marketplace ve Yurtici Kargo Marketplace.",
            state,
            source="model_candidate",
        )
        fallback = response_verifier.project_fallback_response(
            state,
            "Authoritative kargo seçenekleri hazır.",
        )

        self.assertFalse(incomplete.success)
        reasons = list(
            (
                (incomplete.data or {}).get("response_verification") or {}
            ).get("reason_codes")
            or []
        )
        self.assertIn("cargo_option_projection_missing:ARASMP", reasons)
        self.assertIn("cargo_option_projection_missing:YKMP", reasons)
        self.assertIn("unsubstantiated_provider_catalog_date:2 haziran", reasons)
        self.assertTrue(complete.success, complete.data)
        self.assertIn("Aras Kargo Marketplace (ARASMP)", fallback)
        self.assertIn("Yurtici Kargo Marketplace (YKMP)", fallback)

    def test_summary_projection_rejects_sample_price_false_total_and_incomplete_statuses(
        self,
    ) -> None:
        state = self._completed_response_state(
            goal=(
                "Mağazanın sipariş durum dağılımını, kargoya hazır adedi, "
                "ciroyu, kapsamı ve riskleri birlikte göster"
            ),
            operation="orders.status_counts",
            tool_result={
                "total_orders": 100,
                "status_counts": {
                    "Delivered": 80,
                    "ReadyToShip": 12,
                    "Cancelled": 8,
                },
                "account_scopes": [
                    {
                        "api_account_id": 1,
                        "store_name": "MDB",
                        "platform": "TRENDYOL",
                        "environment": "production",
                    }
                ],
            },
            authoritative_answer="Sipariş durum dağılımı getirildi.",
            requested_fields=["status", "count", "amount", "risk", "store", "scope"],
        )
        state.add_selection_snapshot(
            SelectionSnapshot.from_order_numbers(
                ["ORD-SUMMARY-SCOPE-1"],
                source_tool="orders.ready_to_ship",
                listed_count=1,
                total_count=1,
                account_by_order={"ORD-SUMMARY-SCOPE-1": "1"},
                environment_by_account={"1": "production"},
                account_scopes=[
                    {
                        "api_account_id": 1,
                        "store_name": "MDB",
                        "platform": "TRENDYOL",
                        "environment": "production",
                    }
                ],
            )
        )
        state.completed_steps.extend(
            [
                AgentTaskStep(
                    index=2,
                    step_id="ready_count",
                    prompt="Kargoya hazır adedi",
                    status="completed",
                    result_message="Kargoya hazır 12 sipariş var.",
                    tool_names=["orders.ready_to_ship_count"],
                    result_data={
                        "answer": "Kargoya hazır 12 sipariş var.",
                        "tool_result": {"count": 12},
                    },
                ),
                AgentTaskStep(
                    index=3,
                    step_id="summary",
                    prompt="Ciro",
                    status="completed",
                    result_message="Tahmini ciro 5000 TRY.",
                    tool_names=["orders.summary"],
                    result_data={
                        "answer": "Tahmini ciro 5000 TRY.",
                        "tool_result": {
                            "estimated_revenue": 5000.0,
                            "sample_orders": [{"total_price": 299.99}],
                        },
                    },
                ),
                AgentTaskStep(
                    index=4,
                    step_id="risk",
                    prompt="Risk",
                    status="completed",
                    result_message="9 fulfillment risk kaydı var.",
                    tool_names=["orders.fulfillment_risk_count"],
                    result_data={
                        "answer": "9 fulfillment risk kaydı var.",
                        "tool_result": {"risk_count": 9},
                    },
                ),
            ]
        )

        bad = response_verifier.verify_response_projection(
            (
                "MDB (TRENDYOL / production) kapsamında toplam 12 adet siparişiniz "
                "bulunmaktadır ve tamamı kargoya hazırdır. Toplam ciro 299,99 TRY. "
                "Fulfillment riski 9 kayıttır."
            ),
            state,
            source="model_repair_candidate",
        )

        self.assertFalse(bad.success)
        reasons = list(
            ((bad.data or {}).get("response_verification") or {}).get("reason_codes")
            or []
        )
        self.assertIn("aggregate_amount_claim_mismatch:299,99", reasons)
        self.assertIn("total_order_claim_mismatch:12", reasons)
        self.assertIn("all_orders_ready_claim_conflicts_with_totals", reasons)
        self.assertIn("status_projection_missing:Delivered", reasons)

        fallback = response_verifier.project_fallback_response(
            state,
            "Authoritative özet hazır.",
        )
        self.assertIn("Toplam 100 siparis", fallback)
        self.assertIn("Kargoya hazir 12 siparis", fallback)
        self.assertIn("Magaza: MDB.", fallback)
        self.assertNotIn("Magaza: 1", fallback)
        self.assertIn("Delivered 80", fallback)
        self.assertIn("ReadyToShip 12", fallback)
        self.assertIn("Cancelled 8", fallback)
        self.assertIn("Tahmini ciro: 5000", fallback)
        self.assertIn("Fulfillment riski: 9", fallback)
        verified_fallback = response_verifier.verify_response_projection(
            fallback,
            state,
            source="verified_fallback",
        )
        self.assertTrue(verified_fallback.success, verified_fallback.data)

