        self.assertIn("2000.0 TRY", fallback)
        self.assertIn("2026-07-27 14:48", fallback)
        self.assertIn("Müşteri Bir", fallback)
        localized = response_verifier.verify_response_projection(
            "\n".join(
                [
                    "ORD-RECENT-1 | Picking | 2.000 TRY | 27.07.2026 | Müşteri Bir",
                    "ORD-RECENT-2 | Kargoya Hazır | 299,99 TRY | 27.07.2026 | Müşteri İki",
                ]
            ),
            state,
            source="model_candidate",
        )
        self.assertTrue(localized.success, localized.data)
        self.assertTrue(
            task_runtime._generated_task_answer_is_grounded(
                "ORD-RECENT-1 ve ORD-RECENT-2 siparişleri listelendi.",
                state,
            )
        )

