    def test_production_sync_with_explicit_label_prohibition_selects_only_fetch(self) -> None:
        with Session(get_engine(self.db_path)) as session:
            session.add(
                ApiAccount(
                    pk=1,
                    account_id="seller-sync-negative-label",
                    comp_name="Sync Negative Label Seller",
                    platform="trendyol",
                )
            )
            session.commit()

        repair_prompts: list[str] = []

        def planner(prompt: str) -> str:
            if prompt.startswith("OrderScout semantic action verifier"):
                return json.dumps({"verdict": "allow", "objective_aligned": True, "domain_aligned": True, "unwanted_effect": False, "reason": "Exact production sync plan is aligned."})
            if prompt.startswith("Orders model plan semantic repair"):
                repair_prompts.append(prompt)
                return json.dumps(
                    {
                        "steps": [
                            {
                                "id": "sync_orders",
                                "operation_id": "orders.fetch.prepare",
                                "arguments_json": json.dumps(
                                    {
                                        "api_account_ids": [1],
                                        "fetch_returns": True,
                                    }
                                ),
                                "depends_on": [],
                                "objective": "Production siparis ve iadelerini senkronize et",
                                "expected_evidence": [
                                    "api_account_ids",
                                    "fetch_returns",
                                    "save_to_db",
                                ],
                            }
                        ]
                    }
                )
            if prompt.startswith("Orders domain agent task plan"):
                return json.dumps(
                    {
                        "steps": [
                            {"id": "orders.ready_to_ship", "operation_id": "orders.ready_to_ship",
                             "arguments_json": "{}", "depends_on": [], "expected_evidence": ["order_numbers"]},
                            {"id": "orders.labels.prepare", "operation_id": "labels.create_from_orders.prepare",
                             "arguments_json": "{}", "depends_on": ["orders.ready_to_ship"], "expected_evidence": ["action"]},
                        ]
                    }
                )
            return '{"mode":"answer","answer":"unused"}'

        result = run_agent_task(
            "Şimdi yalnızca PRODUCTION Trendyol API hesaplarının güncel sipariş "
            "ve iade verilerini GET ile çek; yerel veritabanına kaydet ve "
            "senkronize et. Pazaryerinde durum değiştirme, etiket oluşturma ve "
            "yazdırma kesinlikle yapma.",
            planner_client=planner,
            db_name=self.db_path,
            turn_interpretation={"mode": "act", "domain": "orders", "objective": "Siparis ve iade verilerini senkronize et", "valid": True},
        )

        self.assertTrue(result.success, result.message)
        self.assertIs((result.data or {}).get("model_invoked"), True)
        state = (result.data or {}).get("state") or {}
        plan = ((state.get("active_entities") or {}).get("task_plan") or {})
        self.assertEqual(plan.get("source"), "llm_direct_repaired")
        self.assertTrue(plan.get("planner_repair_invoked"))
        self.assertTrue(plan.get("planner_repair_accepted"))
        self.assertEqual(len(repair_prompts), 1)
        self.assertIn(
            "no_valid_atomic_operation",
            repair_prompts[0],
        )
        self.assertIn(
            "no_valid_atomic_operation",
            plan.get("initial_plan_reason_codes") or [],
        )
        self.assertEqual(plan.get("step_ids"), ["sync_orders"])
        self.assertEqual(
            [step.get("tool_names") for step in state.get("completed_steps") or []],
            [["orders.fetch.prepare"]],
        )
        pending = state.get("pending_actions") or []
        self.assertEqual(len(pending), 1)
        self.assertEqual(
            pending[0].get("action_type"),
            "orders.get_orders_from_companies",
        )

    def test_wrong_sync_plan_is_not_replaced_by_deterministic_business_template(self) -> None:
        planner_calls = 0

        def planner(prompt: str) -> str:
            nonlocal planner_calls
            planner_calls += 1
            return json.dumps(
                {
                    "steps": [
                        {
                            "id": "wrong_ready_read",
                            "operation_id": "orders.ready_to_ship",
                            "arguments_json": "{}",
                            "depends_on": [],
                            "objective": "Bekleyen siparisleri listele",
                            "expected_evidence": ["order_numbers"],
                        }
                    ]
                }
            )

        result = run_agent_task(
            "Guncel siparisleri API'den cek, kaydet ve senkronize et",
            planner_client=planner,
            db_name=self.db_path,
        )

        self.assertTrue(result.success, result.message)
        self.assertEqual(planner_calls, 2)
        self.assertTrue((result.data or {}).get("plan_rejected"))
        self.assertTrue((result.data or {}).get("model_invoked"))
        state = (result.data or {}).get("state") or {}
        self.assertEqual(state.get("status"), "needs_clarification")
        self.assertEqual(state.get("completed_steps"), [])
        self.assertEqual(state.get("pending_actions"), [])
        plan = ((state.get("active_entities") or {}).get("task_plan") or {})
        self.assertEqual(plan.get("source"), "model_plan_rejected")
        self.assertTrue(plan.get("planner_repair_invoked"))
        self.assertIn(
            "deterministic_business_plan_rewrite_required",
            plan.get("initial_plan_reason_codes") or [],
        )
        self.assertEqual(plan.get("step_ids"), [])

