    def test_distinct_task_sessions_do_not_reuse_implicit_idempotency_key(self) -> None:
        with Session(get_engine(self.db_path)) as session:
            session.add(
                ApiAccount(
                    pk=1,
                    account_id="seller-fresh-task-idempotency",
                    comp_name="Fresh Task Idempotency Seller",
                    platform="trendyol",
                )
            )
            session.commit()

        first = run_agent_task(
            "Trendyol siparis verilerini cek",
            db_name=self.db_path,
        )
        second = run_agent_task(
            "Trendyol siparis verilerini cek",
            db_name=self.db_path,
        )
        first_state = (first.data or {}).get("state") or {}
        second_state = (second.data or {}).get("state") or {}
        observed_keys: list[str] = []

        def fake_execute(
            action,
            *,
            approved_by="user",
            audit_path=None,
            idempotency_key=None,
        ):
            observed_keys.append(str(idempotency_key or ""))
            return Result.ok(
                "fake verified execute",
                close_dialog=False,
                data={"verify": {"verified": True}},
            )

        with patch(
            "AI.processors.task_runtime.execute_approved_operation",
            side_effect=fake_execute,
        ):
            first_resume = resume_agent_task_with_approval(
                first_state,
                continue_after_execute=False,
            )
            second_resume = resume_agent_task_with_approval(
                second_state,
                continue_after_execute=False,
            )

        self.assertTrue(first_resume.success, first_resume.message)
        self.assertTrue(second_resume.success, second_resume.message)
        self.assertEqual(len(observed_keys), 2)
        self.assertNotEqual(observed_keys[0], observed_keys[1])
        self.assertTrue(
            observed_keys[0].startswith(
                f"agent-task:{first_state.get('session_id')}:"
            )
        )
        self.assertTrue(
            observed_keys[1].startswith(
                f"agent-task:{second_state.get('session_id')}:"
            )
        )

