    def test_resume_rejects_pending_action_when_prepare_record_scope_was_tampered(self) -> None:
        raw_action = {
            "action_type": "labels.action_create_labels_from_selected_orders",
            "approval_required": True,
            "execute_enabled": True,
            "arguments": {"payload": {"order_numbers": ["A", "B", "C"]}},
            "rows": [
                {"order_number": "A"},
                {"order_number": "B"},
                {"order_number": "C"},
            ],
        }
        prepared = PendingActionSnapshot.from_action(raw_action).to_action(raw_action)
        prepared["arguments"]["payload"]["order_numbers"] = ["A", "B"]
        state = AgentSessionState(
            goal="Create labels",
            status="pending_approval",
            pending_actions=[prepared],
        )

        resumed = resume_agent_task_with_approval(
            state.to_dict(),
            db_name=self.db_path,
        )

        self.assertFalse(resumed.success)
        self.assertTrue((resumed.data or {}).get("requires_reprepare"))
        self.assertIn(
            "prepare_payload_record_refs_mismatch",
            (resumed.data or {}).get("invariant_problems") or [],
        )

    def test_resume_rejects_superseded_action_id_without_executing(self) -> None:
        state = AgentSessionState(
            goal="Only execute the latest prepared order selection",
            status="pending_approval",
        )
        old_action = state.add_pending_action(
            {
                "action_type": "labels.action_create_labels_from_selected_orders",
                "arguments": {"payload": {"order_numbers": ["OLD-ORDER"]}},
                "rows": [{"order_number": "OLD-ORDER"}],
            }
        )
        current_action = state.add_pending_action(
            {
                "action_type": "labels.action_create_labels_from_selected_orders",
                "arguments": {"payload": {"order_numbers": ["CURRENT-ORDER"]}},
                "rows": [{"order_number": "CURRENT-ORDER"}],
            }
        )

        with patch("AI.processors.task_runtime.execute_approved_operation") as execute_mock:
            resumed = resume_agent_task_with_approval(
                state.to_dict(),
                action_id=old_action["action_id"],
                db_name=self.db_path,
            )

        self.assertFalse(resumed.success)
        self.assertTrue((resumed.data or {}).get("stale_approval"))
        self.assertEqual(
            (resumed.data or {}).get("active_pending_action_id"),
            current_action["action_id"],
        )
        execute_mock.assert_not_called()

