    def test_transient_step_failure_retries_once_and_preserves_attempt_evidence(self) -> None:
        with patch(
            "AI.processors.task_runtime._orders_task_plan",
            return_value=(["orders.recent"], {"source": "test"}),
        ), patch(
            "AI.processors.task_runtime.run_agent_turn",
            side_effect=[
                Result.fail("provider connection timeout", error=TimeoutError("timeout")),
                Result.ok(
                    "ok",
                    close_dialog=False,
                    data={
                        "answer": "Son siparisler getirildi.",
                        "tool_call": {"tool": "orders.query", "arguments": {}},
                        "tool_result": {"count": 2},
                    },
                ),
            ],
        ) as turn_mock:
            result = run_agent_task("Son siparisleri getir", db_name=self.db_path)

        self.assertTrue(result.success, result.message)
        state = (result.data or {}).get("state") or {}
        self.assertEqual(state.get("status"), "complete")
        step = (state.get("completed_steps") or [])[0]
        self.assertEqual((step.get("result_data") or {}).get("attempt_count"), 2)
        self.assertEqual(len((step.get("result_data") or {}).get("attempt_failures") or []), 1)
        self.assertEqual(step.get("attempt_count"), 2)
        self.assertEqual(step.get("verification_status"), "observed")
        self.assertEqual(len(step.get("observation_ids") or []), 1)
        plans = state.get("goal_plans") or []
        self.assertEqual(len(plans), 1)
        self.assertEqual(state.get("active_goal_plan_id"), plans[0].get("plan_id"))
        self.assertEqual(plans[0].get("status"), "complete")
        self.assertEqual(
            (plans[0].get("steps") or [])[0].get("observation_ids"),
            step.get("observation_ids"),
        )
        self.assertIn(
            "step_retrying",
            {row.get("phase") for row in state.get("progress_events") or []},
        )
        self.assertEqual(turn_mock.call_count, 2)

    def test_failed_step_replans_to_safe_catalog_alternative_and_completes(self) -> None:
        def planner(prompt: str) -> str:
            self.assertIn("Basarisiz step: orders.ready_to_ship", prompt)
            return json.dumps(
                {
                    "steps": [{"id": "orders.fulfillment_risk"}],
                    "reason": "Ready listesi kullanilamadi; risk gorunumu ile sinirli sonucu topla.",
                }
            )

        with patch(
            "AI.processors.task_runtime._orders_task_plan",
            return_value=(["orders.ready_to_ship"], {"source": "test"}),
        ), patch(
            "AI.processors.task_runtime.run_agent_turn",
            side_effect=[
                Result.fail("schema validation failed"),
                Result.ok(
                    "ok",
                    close_dialog=False,
                    data={
                        "answer": "Riskli siparis gorunumu getirildi.",
                        "tool_call": {"tool": "orders.fulfillment_risk", "arguments": {}},
                        "tool_result": {"risk_count": 1},
                    },
                ),
            ],
        ) as turn_mock:
            result = run_agent_task(
                "Siparis risklerini incele",
                planner_client=planner,
                db_name=self.db_path,
            )

        self.assertTrue(result.success, result.message)
        state = (result.data or {}).get("state") or {}
        self.assertEqual(state.get("status"), "complete")
        steps = state.get("completed_steps") or []
        self.assertEqual([row.get("step_id") for row in steps], ["orders.ready_to_ship", "orders.fulfillment_risk"])
        self.assertEqual((steps[0].get("result_data") or {}).get("replan_status"), "superseded")
        replans = (state.get("active_entities") or {}).get("replans") or []
        self.assertEqual(replans[0].get("accepted_step_ids"), ["orders.fulfillment_risk"])
        self.assertTrue(replans[0].get("applied"))
        goal_plan = (state.get("goal_plans") or [])[0]
        self.assertEqual(goal_plan.get("revision"), 2)
        self.assertEqual(goal_plan.get("status"), "complete")
        self.assertEqual(
            [row.get("step_id") for row in goal_plan.get("steps") or []],
            ["orders.ready_to_ship", "orders.fulfillment_risk"],
        )
        self.assertEqual(
            ((goal_plan.get("metadata") or {}).get("replans") or [])[0].get(
                "replacement_step_ids"
            ),
            ["orders.fulfillment_risk"],
        )
        self.assertIn("replanned", {row.get("phase") for row in state.get("progress_events") or []})
        self.assertEqual(turn_mock.call_count, 2)

