        def chat_client(prompt: str) -> str:
            final_prompts.append(prompt)
            return "**Operasyon Özeti:**"

        with patch(
            "AI.processors.task_runtime.run_agent_turn",
            return_value=Result.ok(
                "ok",
                close_dialog=False,
                data={
                    "answer": authoritative_answer,
                    "tool_call": {
                        "tool": "stock.zero_or_negative_count",
                        "arguments": {},
                    },
                    "tool_result": {"count": 2},
                    "conversation_context": scalar_context,
                },
            ),
        ):
            result = run_agent_task(
                "Sıfır veya negatif bakiyeli stok kartı sayısını tek sayı olarak doğrula",
                domain="stock",
                planner_client=planner,
                chat_client=chat_client,
                db_name=self.db_path,
            )

        self.assertTrue(result.success, result.message)
        self.assertEqual((result.data or {}).get("answer"), authoritative_answer)
        self.assertTrue(final_prompts)
        self.assertTrue(final_prompts[0].startswith("Stock agent task final cevabi"))
        step = (((result.data or {}).get("state") or {}).get("completed_steps") or [])[0]
        self.assertEqual(
            (step.get("result_data") or {}).get("conversation_context"),
            scalar_context,
        )

