    def test_text_guarded_orders_invalid_plan_does_not_invent_contextual_write_steps(self) -> None:
        for index, order_number in enumerate(
            ("ORD-GUARDED-CONTEXT-1", "ORD-GUARDED-CONTEXT-2", "ORD-GUARDED-UNRELATED"),
            start=1,
        ):
            self._insert_order(
                order_number,
                1_750_000_000_000 + index,
                package_id=7_700 + index,
                status="ReadyToShip",
                cargo_tracking_number=f"TRK-{order_number}",
                cargo_provider_name="Trendyol Express",
            )

        def planner(_prompt: str) -> str:
            return "{}"

        planner.resource_plan = {
            "provider_code": "local",
            "num_ctx": 768,
            "capability_profile": {
                "provider_code": "local",
                "model_id": "guarded.gguf",
                "degradation_mode": "text_guarded",
                "prepare_write_allowed": True,
                "external_write_planning_allowed": False,
            },
        }
        history = [
            {"role": "user", "content": "Son iki siparisi getir"},
            {
                "role": "assistant",
                "content": "1. ORD-GUARDED-CONTEXT-1\n2. ORD-GUARDED-CONTEXT-2",
            },
        ]

        result = run_agent_task(
            "bu iki siparisi yazdir, sonra fis cikarildi isaretle",
            planner_client=planner,
            chat_client=planner,
            db_name=self.db_path,
            history=history,
            turn_interpretation={
                "mode": "act",
                "domain": "orders",
                "objective": "Secili iki siparisi yazdir ve fis cikarildi isaretle",
                "requested_fields": ["action_result"],
                "requires_clarification": False,
                "valid": True,
            },
        )

        self.assertTrue(result.success, result.message)
        state = (result.data or {}).get("state") or {}
        plan = (state.get("active_entities") or {}).get("task_plan") or {}
        self.assertEqual(plan.get("source"), "model_plan_rejected")
        self.assertTrue(plan.get("planner_repair_invoked"))
        self.assertEqual(plan.get("step_ids"), [])
        self.assertEqual(state.get("status"), "needs_clarification")
        self.assertEqual(state.get("pending_actions"), [])
        self.assertEqual(state.get("completed_steps"), [])

