        self.assertTrue(resumed.success, resumed.message)
        resumed_state = (resumed.data or {}).get("state") or {}
        self.assertEqual(resumed_state.get("status"), "complete")
        self.assertEqual(resumed_state.get("pending_actions") or [], [])
        with Session(get_engine(self.db_path)) as session:
            saved = session.exec(
                select(FinanceCostItem).where(FinanceCostItem.name == "Task Runtime Paketleme")
            ).one()
        self.assertEqual(float(saved.defaultAmount), 12.5)
        self.assertIn('"operation": "finance.save_finance_cost_item"', audit_text)
        self.assertIn('"verified_by": "db"', audit_text)

