    def test_returns_reconcile_snapshot_uses_exact_remote_epoch_window(self) -> None:
        now_ms = int(datetime.now(TZ_GMT3).timestamp() * 1000)
        old_ms = now_ms - (3 * 24 * 60 * 60 * 1000)
        self._insert_waiting_return(
            "CLAIM-OUTSIDE-REMOTE-WINDOW",
            "ORD-OUTSIDE-WINDOW",
            old_ms,
        )
        self._insert_waiting_return(
            "CLAIM-IN-REMOTE-WINDOW",
            "ORD-IN-WINDOW",
            old_ms,
        )
        with Session(get_engine(self.db_path)) as session:
            recently_modified = session.exec(
                select(ReturnClaim).where(
                    ReturnClaim.claimId
                    == "CLAIM-IN-REMOTE-WINDOW"
                )
            ).one()
            recently_modified.lastModifiedDate = now_ms
            session.add(recently_modified)
            session.commit()

        result = available_tools()[
            "returns.reconcile_snapshot"
        ].handler(
            db_name=self.db_path,
            observed_claim_ids=["CLAIM-IN-REMOTE-WINDOW"],
            period="all",
            start_ms=now_ms - 60_000,
            end_ms=now_ms + 60_000,
            snapshot_complete=True,
        )

        self.assertTrue(result.success, result.message)
        data = result.data or {}
        self.assertFalse(data.get("needs_remote_snapshot"))
        self.assertTrue(data.get("snapshot_complete"))
        self.assertEqual(data.get("period"), "exact_epoch_window")
        self.assertEqual(data.get("window_field"), "lastModifiedDate")
        self.assertEqual(data.get("local_count"), 1)
        self.assertEqual(data.get("observed_count"), 1)
        self.assertEqual(data.get("stale_count"), 0)
        self.assertEqual(data.get("confirmed_count"), 1)

        empty_window = available_tools()[
            "returns.reconcile_snapshot"
        ].handler(
            db_name=self.db_path,
            observed_claim_ids=[],
            period="all",
            start_ms=now_ms + 120_000,
            end_ms=now_ms + 180_000,
            snapshot_complete=True,
        )
        self.assertTrue(empty_window.success, empty_window.message)
        empty_data = empty_window.data or {}
        self.assertFalse(empty_data.get("needs_remote_snapshot"))
        self.assertTrue(empty_data.get("snapshot_complete"))
        self.assertEqual(empty_data.get("local_count"), 0)
        self.assertEqual(empty_data.get("observed_count"), 0)
        self.assertEqual(empty_data.get("stale_count"), 0)

    def test_returns_mark_stale_prepare_execute_hides_claim_from_active_results(self) -> None:
        now_ms = int(datetime.now(TZ_GMT3).timestamp() * 1000)
        self._insert_waiting_return("CLAIM-LOCAL-STALE", "ORD-STALE-1", now_ms)
        self._insert_waiting_return("CLAIM-REMOTE-OK", "ORD-OK-1", now_ms + 1_000)

        prepare = available_tools()["returns.mark_stale.prepare"].handler(
            db_name=self.db_path,
            observed_claim_ids=["CLAIM-REMOTE-OK"],
            period="all",
        )

        self.assertTrue(prepare.success, prepare.message)
        action = (prepare.data or {}).get("action") or {}
        self.assertEqual(action.get("action_type"), "orders.mark_return_claims_stale")
        self.assertTrue(action.get("execute_enabled"))
        payload = (action.get("arguments") or {}).get("payload") or {}
        self.assertEqual(payload.get("claim_ids"), ["CLAIM-LOCAL-STALE"])
        self.assertEqual((payload.get("claim_keys") or [])[0].get("claim_id"), "CLAIM-LOCAL-STALE")

        with tempfile.TemporaryDirectory() as temp_dir:
            execute = operation_runtime.execute_approved_operation(
                action,
                approved_by="test",
                idempotency_key=f"test-mark-stale-{now_ms}",
                audit_path=Path(temp_dir) / "orders-agent-audit.jsonl",
            )

        self.assertTrue(execute.success, execute.message)
        verify = (execute.data or {}).get("verify") or {}
        self.assertTrue(verify.get("verified"))
        lookup = available_tools()["returns.lookup"].handler(db_name=self.db_path, query="CLAIM-LOCAL-STALE")
        self.assertTrue(lookup.success, lookup.message)
        lookup_claim_ids = {row.get("claim_id") for row in ((lookup.data or {}).get("returns") or [])}
        self.assertNotIn("CLAIM-LOCAL-STALE", lookup_claim_ids)
        reconcile = available_tools()["returns.reconcile_snapshot"].handler(
            db_name=self.db_path,
            observed_claim_ids=["CLAIM-REMOTE-OK"],
            period="all",
        )
        self.assertTrue(reconcile.success, reconcile.message)
        self.assertEqual((reconcile.data or {}).get("stale_count"), 0)

