    def test_orders_task_runtime_complete_task_returns_final_answer(self) -> None:
        today = datetime.now(TZ_GMT3).date()
        today_start = int(datetime.combine(today, datetime.min.time(), tzinfo=TZ_GMT3).timestamp() * 1000)
        self._insert_order("ORD-TASK-SUMMARY-READY", today_start + 1_000, package_id=903, cargo_tracking_number="TRK-903", cargo_provider_name="Aras")
        self._insert_order("ORD-TASK-SUMMARY-RISK", today_start + 2_000, package_id=904)
        self._insert_waiting_return("CLAIM-TASK-SUMMARY-WAIT", "ORD-TASK-SUMMARY-RET", today_start + 3_000)

        final_prompts: list[str] = []

        def chat_client(prompt: str) -> str:
            if prompt.startswith("Orders agent task final cevabi"):
                final_prompts.append(prompt)
                return (
                    "Bugunku operasyon ozeti hazir: kargoya hazir siparis, risk kontrolu ve bekleyen iade kontrol edildi.\n"
                    "Kritik bekleyen is gorunmuyor.\n"
                    "Diger tum islemler tamamlanmis ve onay bekleyen bir iade, fulfillment riski ya da eksik kargo bulunmamaktadir."
                )
            return ""

        result = run_agent_task("Bugunku siparis operasyonunu toparla", db_name=self.db_path, chat_client=chat_client)

        self.assertTrue(result.success, result.message)
        self.assertTrue(final_prompts)
        data = result.data or {}
        self.assertIn("Agent gorevi tamamlandi", data.get("answer") or "")
        self.assertIn("fulfillment risk kaydi", data.get("answer") or "")
        self.assertIn("iade buldum", data.get("answer") or "")
        self.assertNotIn("Kritik bekleyen is gorunmuyor", data.get("answer") or "")
        self.assertNotIn("Diger tum islemler tamamlanmis", data.get("answer") or "")
        self.assertNotIn("onay bekleyen bir iade", data.get("answer") or "")
        self.assertNotIn("eksik kargo bulunmamaktadir", data.get("answer") or "")
        state = data.get("state") or {}
        synthesis = ((state.get("active_entities") or {}).get("response_synthesis") or {})
        self.assertIn(
            "contradictory_global_pending_clearance",
            synthesis.get("candidate_projection_reason_codes") or [],
        )
        self.assertEqual(((state.get("active_entities") or {}).get("final_answer")), data.get("answer"))
        self.assertIn("orders.ready_to_ship", final_prompts[0])
        self.assertIn("orders.fulfillment_risk", final_prompts[0])
        self.assertIn("returns.query", final_prompts[0])

    def test_orders_task_runtime_accepts_guardrailed_llm_plan_steps(self) -> None:
        calls: list[str] = []

        def planner(prompt: str) -> str:
            calls.append(prompt)
            if prompt.startswith("Orders model plan semantic repair"):
                return json.dumps(
                    {
                        "steps": [
                            {
                                "id": "ready",
                                "operation_id": "orders.ready_to_ship",
                                "arguments_json": "{}",
                                "depends_on": [],
                            },
                            {
                                "id": "risk",
                                "operation_id": "orders.fulfillment_risk",
                                "arguments_json": "{}",
                                "depends_on": [],
                            },
                            {
                                "id": "waiting_returns",
                                "operation_id": "returns.query",
                                "arguments_json": json.dumps(
                                    {"filters": {"waiting_action_only": True}}
                                ),
                                "depends_on": [],
                            },
                        ]
                    }
                )
            if prompt.startswith("Orders domain agent task plan"):
                return json.dumps({"steps": [{"id": "orders.fulfillment_risk"}, {"id": "orders.ready_to_ship"}]})
            return '{"mode":"tool","tool":"orders.count","arguments":{"period":"today"}}'

        result = run_agent_task("Bugunku siparis operasyonunu toparla", db_name=self.db_path, planner_client=planner)

        self.assertTrue(result.success, result.message)
        state = (result.data or {}).get("state") or {}
        plan = ((state.get("active_entities") or {}).get("task_plan") or {})
        self.assertEqual(plan.get("source"), "llm_direct_repaired")
        self.assertTrue(plan.get("planner_repair_accepted"))
        self.assertEqual(plan.get("step_ids"), ["ready", "risk", "waiting_returns"])
        self.assertTrue(calls and calls[0].startswith("Orders domain agent task plan"))
        self.assertEqual(len(state.get("completed_steps") or []), 3)

    def test_direct_goal_plan_executes_typed_atomic_operation_without_second_llm_decision(self) -> None:
        now_ms = int(datetime.now(TZ_GMT3).timestamp() * 1000)
        self._insert_order(
            "ORD-DIRECT-READY-1",
            now_ms,
            package_id=97001,
            status="ReadyToShip",
            cargo_tracking_number="TRK-DIRECT-READY-1",
            cargo_provider_name="Trendyol Express",
        )
        self._insert_order(
            "ORD-DIRECT-DELIVERED-1",
            now_ms + 1_000,
            package_id=97002,
            status="Delivered",
            cargo_tracking_number="TRK-DIRECT-DELIVERED-1",
            cargo_provider_name="Trendyol Express",
        )

        def planner(prompt: str) -> str:
            self.assertTrue(prompt.startswith("Orders domain agent task plan"))
            self.assertIn("orders.query", prompt)
            return json.dumps(
                {
                    "steps": [
                        {
                            "id": "count_ready",
                            "operation_id": "orders.query",
                            "arguments": {
                                "period": "all",
                                "filters": {"status": "ReadyToShip"},
                                "mode": "count",
                            },
                            "depends_on": [],
                            "objective": "Kargoya hazir siparislerin kesin sayisini getir",
                            "expected_evidence": ["count", "filters"],
                        }
                    ],
                    "reason": "Tek atomic sorgu yeterli.",
                }
            )

        with patch(
            "AI.processors.task_runtime.run_agent_turn",
            side_effect=AssertionError("direct step must not ask the LLM to choose a tool again"),
        ) as turn_mock:
            result = run_agent_task(
                "ReadyToShip durumundaki siparislerin sayisini getir",
                db_name=self.db_path,
                planner_client=planner,
            )

        self.assertTrue(result.success, result.message)
        turn_mock.assert_not_called()
        state = (result.data or {}).get("state") or {}
        task_plan = (state.get("active_entities") or {}).get("task_plan") or {}
        self.assertEqual(task_plan.get("source"), "llm_direct")
        self.assertEqual(task_plan.get("step_ids"), ["count_ready"])
        goal_plan = (state.get("goal_plans") or [])[0]
        planned_step = (goal_plan.get("steps") or [])[0]
        self.assertEqual(planned_step.get("operation_candidates"), ["orders.query"])
        self.assertEqual(planned_step.get("arguments", {}).get("mode"), "count")
        self.assertEqual(planned_step.get("expected_evidence"), ["count", "filters"])
        completed = (state.get("completed_steps") or [])[0]
        self.assertEqual(completed.get("tool_names"), ["orders.query"])
        self.assertEqual(completed.get("verification_status"), "observed")
        self.assertEqual(len(completed.get("observation_ids") or []), 1)
        self.assertEqual(
            ((completed.get("result_data") or {}).get("tool_result") or {}).get("count"),
            1,
        )

    def test_direct_goal_plan_honors_declared_dependencies_even_when_steps_are_out_of_order(self) -> None:
        now_ms = int(datetime.now(TZ_GMT3).timestamp() * 1000)
        self._insert_order(
            "ORD-DIRECT-GRAPH-1",
            now_ms,
            package_id=97011,
            status="ReadyToShip",
            cargo_tracking_number="TRK-DIRECT-GRAPH-1",
            cargo_provider_name="Trendyol Express",
        )

        def planner(_prompt: str) -> str:
            if _prompt.startswith("GoalPlan observation"):
                return json.dumps({"decision": "complete", "reason": "Declared evidence observed"})
            return json.dumps(
                {
                    "steps": [
                        {
                            "id": "status_distribution",
                            "operation_id": "orders.status_counts",
                            "arguments": {"period": "all"},
                            "depends_on": ["ready_count"],
                            "objective": "Siparis durum dagilimini getir",
                            "expected_evidence": ["status_counts"],
                        },
                        {
                            "id": "ready_count",
                            "operation_id": "orders.ready_to_ship_count",
                            "arguments": {"period": "all"},
                            "depends_on": [],
                            "objective": "Kargoya hazir siparis sayisini getir",
                            "expected_evidence": ["count"],
                        },
                    ]
                }
            )

        with patch(
            "AI.processors.task_runtime.run_agent_turn",
            side_effect=AssertionError("direct graph steps must execute their bound tools"),
        ) as turn_mock:
            result = run_agent_task(
                "Kargoya hazir siparis sayisini ve siparis durum dagilimini getir",
                db_name=self.db_path,
                planner_client=planner,
            )

        self.assertTrue(result.success, result.message)
        turn_mock.assert_not_called()
        state = (result.data or {}).get("state") or {}
        self.assertEqual(
            [step.get("step_id") for step in state.get("completed_steps") or []],
            ["ready_count", "status_distribution"],
        )
        self.assertEqual(len(state.get("observations") or []), 2)
        goal_plan = (state.get("goal_plans") or [])[0]
        by_id = {
            step.get("step_id"): step
            for step in goal_plan.get("steps") or []
        }
        self.assertEqual(
            by_id["status_distribution"].get("depends_on"),
            ["ready_count"],
        )
        self.assertEqual(goal_plan.get("status"), "complete")

