    def test_r314_overlapping_metric_reads_require_model_minimal_plan_repair(
        self,
    ) -> None:
        goal = (
            "Pazaryerinden güncelleme yapmadan yerel kayıttaki toplam sipariş "
            "sayısını ve bütün durum dağılımını ver; dağılımdaki adetlerin "
            "toplamının genel toplamla tutarlı olup olmadığını işlemiyle göster."
        )
        responses = iter(
            [
                {
                    "steps": [
                        {
                            "id": "count",
                            "operation_id": "orders.count",
                            "arguments": {"period": "all"},
                            "depends_on": [],
                            "objective": "Toplam siparişi getir",
                            "expected_evidence": ["count"],
                        },
                        {
                            "id": "statuses",
                            "operation_id": "orders.status_counts",
                            "arguments": {"period": "all"},
                            "depends_on": [],
                            "objective": "Toplam ve durumları getir",
                            "expected_evidence": ["total_orders", "status_counts"],
                        },
                        {
                            "id": "summary",
                            "operation_id": "orders.summary",
                            "arguments": {"period": "all"},
                            "depends_on": [],
                            "objective": "Genel özeti getir",
                            "expected_evidence": ["total_orders", "status_counts"],
                        },
                    ]
                },
                {
                    "steps": [
                        {
                            "id": "statuses",
                            "operation_id": "orders.status_counts",
                            "arguments": {"period": "all"},
                            "depends_on": [],
                            "objective": "Toplam ve durumları tek okumada getir",
                            "expected_evidence": ["total_orders", "status_counts"],
                        }
                    ]
                },
            ]
        )

        prompts: list[str] = []

        def planner(_prompt: str) -> str:
            prompts.append(_prompt)
            return json.dumps(next(responses), ensure_ascii=False)

        tools = available_tools()
        candidates = {
            operation_id: tools[operation_id]
            for operation_id in (
                "orders.count",
                "orders.status_counts",
                "orders.summary",
            )
        }
        interpretation = {
            "mode": "inspect",
            "domain": "orders",
            "intent_kind": "data_read",
            "requested_fields": ["count", "status", "calculation"],
            "semantic_contract": {
                "entity": "order",
                "metric": "derived",
                "status_scope": "all",
                "record_scope": "all_matching",
                "period": "all",
                "projection": ["count", "status", "calculation"],
                "direct_projection": ["count", "status"],
                "metric_requirements": [
                    ORDER_TOTAL_COUNT_METRIC,
                    ORDER_STATUS_DISTRIBUTION_METRIC,
                ],
                "derived_calculation": {
                    "operator": "add",
                    "operands": [{"ref": "orders.status_counts"}],
                    "result_kind": "count",
                    "precision": 0,
                    "show_work": True,
                    "comparison": {
                        "operator": "equal",
                        "operand": {"ref": "orders.total_count"},
                    },
                },
            },
        }

        with patch(
            "AI.processors.task_runtime._planner_operation_candidates",
            return_value=candidates,
        ):
            step_ids, meta = task_runtime._orders_task_plan(
                goal,
                planner_client=planner,
                max_steps=8,
                turn_interpretation=interpretation,
            )

        self.assertEqual(meta.get("source"), "llm_direct_repaired")
        self.assertTrue(meta.get("planner_repair_accepted"))
        initial_reasons = set(meta.get("initial_plan_reason_codes") or [])
        self.assertIn(
            "redundant_projection_read_operation:orders.count",
            initial_reasons,
        )
        self.assertIn(
            "redundant_projection_read_operation:orders.summary",
            initial_reasons,
        )
        self.assertEqual(
            meta.get("initial_compile_verification", {}).get(
                "minimal_metric_cover_operation_ids"
            ),
            ["orders.status_counts"],
        )
        self.assertEqual(len(prompts), 2)
        self.assertIn(
            '"minimal_metric_cover_operation_ids": ["orders.status_counts"]',
            prompts[1],
        )
        self.assertIn(
            '"redundant_metric_operation_ids": ["orders.count", "orders.summary"]',
            prompts[1],
        )
        self.assertEqual(step_ids, ["statuses"])
        self.assertEqual(
            [
                row.get("operation_id")
                for row in list(meta.get("step_specs") or [])
            ],
            ["orders.status_counts"],
        )

