    def test_direct_plan_accepts_safe_indexed_dependency_binding_for_single_record_action(
        self,
    ) -> None:
        registry = available_tools()
        allowed = {
            name: registry[name]
            for name in (
                "orders.query",
                "orders.change_cargo_provider.prepare",
            )
        }
        goal = (
            "Stage Seller 2738 test hesabında kargo değişikliğine uygun en "
            "yeni Picking siparişini bul; kargo firmasını ARASMP yapmaya "
            "hazırla ama kesinlikle çalıştırma."
        )

        accepted, rejected = task_runtime._validate_direct_plan_specs(
            "orders",
            [
                {
                    "id": "step_1",
                    "operation_id": "orders.query",
                    "arguments": {
                        "api_account_ids": [2738],
                        "filters": {"status": "Picking"},
                        "sort": "order_date_desc",
                        "limit": 1,
                        "mode": "list",
                    },
                    "depends_on": [],
                },
                {
                    "id": "step_2",
                    "operation_id": "orders.change_cargo_provider.prepare",
                    "arguments": {
                        "cargo_provider": "ARASMP",
                        "order_numbers": [
                            {
                                "$from_step": "step_1",
                                "path": "tool_result.orders[0].order_number",
                            }
                        ],
                        "query": "en yeni Picking siparişi",
                    },
                    "depends_on": ["step_1"],
                },
            ],
            goal,
            allowed_operations=allowed,
            max_steps=4,
            authorization_context={
                "mode": "act",
                "intent_kind": "action",
                "requested_fields": [
                    "order_number",
                    "status",
                    "cargo",
                    "scope",
                ],
                "semantic_contract": {
                    "entity": "order",
                    "metric": "detail",
                    "status_scope": "all",
                    "record_scope": "all_matching",
                    "period": "all",
                },
            },
        )

        self.assertEqual(rejected, [])
        self.assertEqual(
            [row.get("id") for row in accepted],
            ["step_1", "step_2"],
        )

        source = AgentTaskStep(
            index=1,
            step_id="step_1",
            prompt="En yeni siparişi bul",
            status="completed",
            result_data={
                "tool_result": {
                    "orders": [
                        {"order_number": "ORD-STAGE-PICKING-1"}
                    ]
                }
            },
        )
        found, value = task_runtime._resolve_step_output_path(
            source,
            "tool_result.orders[0].order_number",
        )
        self.assertTrue(found)
        self.assertEqual(value, "ORD-STAGE-PICKING-1")
        self.assertEqual(
            task_runtime._resolve_step_output_path(
                source,
                "tool_result.orders[-1].order_number",
            ),
            (False, None),
        )

