    def test_direct_plan_is_compiled_to_exact_context_and_explicit_intent_coverage(self) -> None:
        now_ms = int(datetime.now(TZ_GMT3).timestamp() * 1000)
        selected = {"ORD-DIRECT-CONTEXT-1", "ORD-DIRECT-CONTEXT-2"}
        for index, order_number in enumerate(
            (*sorted(selected), "ORD-DIRECT-CONTEXT-UNRELATED"),
            start=1,
        ):
            self._insert_order(
                order_number,
                now_ms + index,
                package_id=97_050 + index,
                status="ReadyToShip",
                cargo_tracking_number=f"TRK-{order_number}",
                cargo_provider_name="Trendyol Express",
            )

        def incomplete_broad_planner(prompt: str) -> str:
            if prompt.startswith("OrderScout semantic action verifier"):
                return json.dumps(
                    {
                        "verdict": "allow",
                        "objective_aligned": True,
                        "domain_aligned": True,
                        "unwanted_effect": False,
                        "reason": "Exact secili siparislerde iki acik islem hedefle uyumlu.",
                    }
                )
            if prompt.startswith("Orders model plan semantic repair"):
                return json.dumps(
                    {
                        "steps": [
                            {
                                "id": "step_2",
                                "operation_id": "labels.create_from_orders.prepare",
                                "arguments_json": json.dumps(
                                    {"order_numbers": sorted(selected)}
                                ),
                                "depends_on": [],
                                "objective": "Etiketleri hazirla",
                                "expected_evidence": ["action"],
                            },
                            {
                                "id": "step_3",
                                "operation_id": "labels.mark_extracted.prepare",
                                "arguments_json": json.dumps(
                                    {"order_numbers": sorted(selected)}
                                ),
                                "depends_on": ["step_2"],
                                "objective": "Ayni siparisleri fis cikarildi isaretle",
                                "expected_evidence": ["action"],
                            },
                        ]
                    }
                )
            if prompt.startswith("Orders domain agent task plan"):
                return json.dumps(
                    {
                        "steps": [
                            {
                                "id": "step_1",
                                "operation_id": "orders.ready_to_ship",
                                "arguments_json": json.dumps(
                                    {
                                        "limit": 2,
                                        "only_not_printed": True,
                                        "period": "all",
                                    }
                                ),
                                "depends_on": [],
                                "objective": "Kargoya hazir siparisleri yeniden listele",
                                "expected_evidence": ["order_numbers"],
                            },
                            {
                                "id": "step_2",
                                "operation_id": "labels.create_from_orders.prepare",
                                "arguments_json": "{}",
                                "depends_on": ["step_1"],
                                "objective": "Etiketleri hazirla",
                                "expected_evidence": ["action"],
                            },
                        ]
                    }
                )
            return json.dumps({"decision": "continue", "reason": "Plan devam ediyor"})

        history = [
            {"role": "user", "content": "Son iki siparisi getir"},
            {
                "role": "assistant",
                "content": "1. ORD-DIRECT-CONTEXT-1\n2. ORD-DIRECT-CONTEXT-2",
            },
        ]
        result = run_agent_task(
            "bu iki siparisi yazdir, sonra fis cikarildi isaretle; bitene kadar devam et",
            planner_client=incomplete_broad_planner,
            db_name=self.db_path,
            history=history,
            turn_interpretation={
                "mode": "act",
                "domain": "orders",
                "objective": "Secili siparisleri yazdir ve fis cikarildi olarak isaretle",
                "requested_fields": ["action_result"],
                "requires_clarification": False,
                "valid": True,
                "planner_invoked": True,
            },
        )

        self.assertTrue(result.success, result.message)
        state = (result.data or {}).get("state") or {}
        plan = ((state.get("active_entities") or {}).get("task_plan") or {})
        self.assertEqual(plan.get("source"), "llm_direct_repaired")
        self.assertTrue(plan.get("direct_plan_compiled"), plan)
        self.assertFalse(plan.get("semantic_coverage_normalized"), plan)
        self.assertEqual(
            plan.get("initial_compile_verification", {}).get("semantic_missing_step_ids"),
            ["orders.labels.extracted.prepare"],
        )
        self.assertEqual(plan.get("semantic_inserted_step_ids"), [])
        self.assertFalse(plan.get("deterministic_business_steps_inserted"))
        self.assertTrue(plan.get("contextual_history_used"), plan)
        self.assertEqual(plan.get("context_removed_step_ids"), [])
        self.assertEqual(plan.get("context_removed_semantic_step_ids"), [])
        self.assertEqual(
            plan.get("step_ids"),
            ["step_2", "step_3"],
        )
        completed = state.get("completed_steps") or []
        self.assertEqual(
            [row.get("tool_names") for row in completed],
            [["labels.create_from_orders.prepare"]],
        )
        action = (state.get("pending_actions") or [])[0]
        payload = ((action.get("arguments") or {}).get("payload") or {})
        self.assertEqual(set(payload.get("order_numbers") or []), selected)
        self.assertNotIn(
            "ORD-DIRECT-CONTEXT-UNRELATED",
            payload.get("order_numbers") or [],
        )
        remaining = state.get("remaining_steps") or []
        self.assertEqual(len(remaining), 1)
        self.assertEqual(
            remaining[0].get("operation_candidates"),
            ["labels.mark_extracted.prepare"],
        )
        self.assertEqual(
            set((remaining[0].get("arguments") or {}).get("order_numbers") or []),
            selected,
        )

        label_calls: list[list[str]] = []

        def fake_create_order_label_from_orders(
            order_numbers,
            *,
            brand_code="TANEX",
            model_code="TANEX_2736",
            db_name=None,
        ):
            label_calls.append(list(order_numbers))
            return Result.ok(
                "Etiketler olusturuldu.",
                close_dialog=False,
                data={"order_numbers": list(order_numbers)},
            )

        with tempfile.TemporaryDirectory() as temp_dir, patch(
            "Labels.processors.pipeline.create_order_label_from_orders",
            side_effect=fake_create_order_label_from_orders,
        ):
            audit_path = str(Path(temp_dir) / "direct-context-audit.jsonl")
            first_resume = resume_agent_task_with_approval(
                state,
                approved_by="direct-context-test",
                planner_client=incomplete_broad_planner,
                db_name=self.db_path,
                audit_path=audit_path,
                idempotency_key="direct-context-label",
            )
            self.assertTrue(first_resume.success, first_resume.message)
            second_state = (first_resume.data or {}).get("state") or {}
            self.assertEqual(second_state.get("status"), "pending_approval")
            second_action = (second_state.get("pending_actions") or [])[0]
            self.assertEqual(
                second_action.get("action_type"),
                "labels.mark_orders_extracted_from_label_result",
            )
            second_payload = (
                (second_action.get("arguments") or {}).get("payload") or {}
            )
            self.assertEqual(set(second_payload.get("order_numbers") or []), selected)

            second_resume = resume_agent_task_with_approval(
                second_state,
                approved_by="direct-context-test",
                planner_client=incomplete_broad_planner,
                db_name=self.db_path,
                audit_path=audit_path,
                idempotency_key="direct-context-extracted",
            )

        self.assertTrue(second_resume.success, second_resume.message)
        final_state = (second_resume.data or {}).get("state") or {}
        self.assertEqual(final_state.get("status"), "complete")
        self.assertEqual([set(row) for row in label_calls], [selected])
        with Session(get_engine(self.db_path)) as session:
            rows = session.exec(
                select(OrderHeader).where(
                    OrderHeader.orderNumber.in_(
                        [*sorted(selected), "ORD-DIRECT-CONTEXT-UNRELATED"]
                    )
                )
            ).all()
        extracted = {row.orderNumber for row in rows if row.is_extracted}
        self.assertEqual(extracted, selected)

    def test_new_task_turn_resolves_deictic_order_from_prior_typed_pending_context(self) -> None:
        now_ms = int(datetime.now(TZ_GMT3).timestamp() * 1000)
        order_number = "ORD-TYPED-FOLLOWUP-1"
        self._insert_order(
            order_number,
            now_ms,
            package_id=97_091,
            status="ReadyToShip",
            cargo_tracking_number="TRK-TYPED-FOLLOWUP-1",
            cargo_provider_name="Trendyol Express",
            first_name="Typed",
            last_name="Customer",
        )
        self._insert_order_item(
            order_number,
            now_ms + 1_000,
            product_name="Typed Followup Product",
            line_id=97_091,
        )
        first = run_agent_task(
            f"{order_number} siparisini TANEX 2610 etiketiyle yazdir",
            db_name=self.db_path,
            planner_client=self._direct_label_planner([order_number]),
            turn_interpretation={
                "mode": "act",
                "domain": "orders",
                "objective": f"{order_number} siparisini etikete hazirla",
                "requires_clarification": False,
                "valid": True,
            },
        )
        previous_state = (first.data or {}).get("state") or {}
        self.assertEqual(previous_state.get("status"), "pending_approval")

        def followup_planner(prompt: str) -> str:
            if prompt.startswith("Orders domain agent task plan"):
                self.assertIn(order_number, prompt)
                return json.dumps(
                    {
                        "steps": [
                            {
                                "id": "inspect_context_order",
                                "operation_id": "orders.full_context",
                                "arguments": {"query": "bu siparis ne kimin"},
                                "depends_on": [],
                                "objective": "Onceki typed siparisin tam baglamini getir",
                                "expected_evidence": ["contexts", "order_numbers"],
                            }
                        ]
                    }
                )
            if prompt.startswith("OrderScout projection contract reconciler"):
                return json.dumps(
                    {
                        "decisions": {
                            "customer_name": "visible_requested",
                        },
                        "reason": "Kullanici siparisin kime ait oldugunu istedi.",
                    }
                )
            return json.dumps({"decision": "continue", "reason": "Tek read adimi yeterli"})

        second = run_agent_task(
            "Bu siparis ne, kimin siparisi?",
            db_name=self.db_path,
            planner_client=followup_planner,
            session_state=previous_state,
            turn_interpretation={
                "mode": "inspect",
                "domain": "orders",
                "objective": "Onceki typed siparisin sahibini ve baglamini incele",
                "requested_fields": ["order_number", "customer_name"],
                "requires_clarification": False,
                "valid": True,
            },
        )

        self.assertTrue(second.success, second.message)
        state = (second.data or {}).get("state") or {}
        self.assertNotEqual(state.get("session_id"), previous_state.get("session_id"))
        completed = state.get("completed_steps") or []
        self.assertEqual(len(completed), 1)
        data = (completed[0].get("result_data") or {})
        self.assertEqual(
            (data.get("dependency_bindings") or {}).get("order_numbers"),
            "session_context:pending_action.order_numbers",
        )
        tool_result = data.get("tool_result") or {}
        self.assertEqual(tool_result.get("order_numbers"), [order_number])
        self.assertEqual(
            (((tool_result.get("contexts") or [])[0].get("order") or {}).get("customer")),
            "Typed Customer",
        )

    def test_model_reconciles_plan_customer_evidence_into_visible_projection(self) -> None:
        now_ms = int(datetime.now(TZ_GMT3).timestamp() * 1000)
        order_number = "ORD-PROJECTION-RECONCILE-1"
        self._insert_order(
            order_number,
            now_ms,
            package_id=97_095,
            status="Delivered",
            cargo_tracking_number="TRK-PROJECTION-RECONCILE-1",
            cargo_provider_name="Trendyol Express",
            first_name="Reconciled",
            last_name="Customer",
        )
        self._insert_order_item(
            order_number,
            now_ms + 1_000,
            product_name="Projection Reconcile Product",
            line_id=97_095,
        )
        prompts: list[str] = []

        def planner(prompt: str) -> str:
            prompts.append(prompt)
            if prompt.startswith("Orders domain agent task plan"):
                return json.dumps(
                    {
                        "steps": [
                            {
                                "id": "detail",
                                "operation_id": "orders.full_context",
                                "arguments_json": json.dumps(
                                    {"order_numbers": [order_number]}
                                ),
                                "depends_on": [],
                                "objective": (
                                    "Secili siparisin sahibini, urununu ve "
                                    "kargo detaylarini getir"
                                ),
                                "expected_evidence": [
                                    "order_number",
                                    "customer",
                                    "items",
                                    "cargo",
                                    "tracking_number",
                                ],
                            }
                        ]
                    }
                )
            if prompt.startswith("OrderScout projection contract reconciler"):
                self.assertIn("customer_name", prompt)
                return json.dumps(
                    {
                        "decisions": {
                            "customer_name": "visible_requested",
                            "tracking_number": "visible_requested",
                        },
                        "reason": "Eksik gorunur alan model tarafindan uzlastirildi.",
                    }
                )
            return json.dumps(
                {"decision": "complete", "reason": "Kanit yeterli", "steps": []}
            )

        result = run_agent_task(
            (
                f"{order_number} kaydinin kime ait oldugunu, numarasini, urun "
                "icerigini ve takip numarasiyla kargo detayini goster"
            ),
            db_name=self.db_path,
            planner_client=planner,
            turn_interpretation={
                "mode": "inspect",
                "domain": "orders",
                "objective": "Siparis sahibini ve tam siparis baglamini goster",
                "intent_kind": "data_read",
                "request_shape": "record_detail",
                # Reproduce R161: interpretation omits customer_name while the
                # same model-authored plan explicitly expects customer evidence.
                "requested_fields": [
                    "order_number",
                    "cargo",
                    "tracking_number",
                    "item",
                ],
                "semantic_contract": {
                    "entity": "order",
                    "metric": "list",
                    "record_scope": "exact_ids",
                    "projection": [
                        "order_number",
                        "cargo",
                        "tracking_number",
                        "item",
                    ],
                },
                "requires_clarification": False,
                "planner_invoked": True,
                "valid": True,
                "decision_path": "typed_model_turn_interpretation",
            },
        )

        self.assertTrue(result.success, result.message)
        state = dict((result.data or {}).get("state") or {})
        interpretation = dict(
            (state.get("active_entities") or {}).get("turn_interpretation") or {}
        )
        self.assertIn("customer_name", interpretation.get("requested_fields") or [])
        self.assertIn(
            "customer_name",
            (interpretation.get("semantic_contract") or {}).get("projection") or [],
        )
        plan = dict(
            (state.get("active_entities") or {}).get("task_plan") or {}
        )
        self.assertTrue(plan.get("projection_contract_repair_invoked"))
        self.assertEqual(
            plan.get("projection_contract_fields_added"),
            ["customer_name"],
        )
        self.assertIn("Reconciled Customer", str((result.data or {}).get("answer") or ""))
        self.assertTrue(
            any(
                prompt.startswith("OrderScout projection contract reconciler")
                for prompt in prompts
            )
        )

    def test_model_can_keep_plan_customer_evidence_internal_without_privacy_leak(self) -> None:
        now_ms = int(datetime.now(TZ_GMT3).timestamp() * 1000)
        order_number = "ORD-PROJECTION-INTERNAL-1"
        self._insert_order(
            order_number,
            now_ms,
            package_id=97_096,
            status="Delivered",
            cargo_tracking_number="TRK-PROJECTION-INTERNAL-1",
            cargo_provider_name="Trendyol Express",
            first_name="Private",
            last_name="Hidden",
        )
        self._insert_order_item(
            order_number,
            now_ms + 1_000,
            product_name="Visible Product Only",
            line_id=97_096,
        )

        def planner(prompt: str) -> str:
            if prompt.startswith("Orders domain agent task plan"):
                return json.dumps(
                    {
                        "steps": [
                            {
                                "id": "detail",
                                "operation_id": "orders.full_context",
                                "arguments_json": json.dumps(
                                    {"order_numbers": [order_number]}
                                ),
                                "depends_on": [],
                                "objective": "Siparis urun icerigini getir",
                                "expected_evidence": [
                                    "order_number",
                                    "customer",
                                    "items",
                                ],
                            }
                        ]
                    }
                )
            if prompt.startswith("OrderScout projection contract reconciler"):
                return json.dumps(
                    {
                        "decisions": {
                            "customer_name": "internal_only",
                        },
                        "reason": "Private alan yalniz internal evidence.",
                    }
                )
            return json.dumps(
                {"decision": "complete", "reason": "Kanit yeterli", "steps": []}
            )

        result = run_agent_task(
            f"{order_number} siparisinin yalniz urun icerigini goster",
            db_name=self.db_path,
            planner_client=planner,
            turn_interpretation={
                "mode": "inspect",
                "domain": "orders",
                "objective": "Siparis urun icerigini goster",
                "intent_kind": "data_read",
                "request_shape": "record_detail",
                # A first-pass model may over-project a private field.  The
                # privacy contract must be able to remove it before rendering.
                "requested_fields": [
                    "order_number",
                    "item",
                    "customer_name",
                ],
                "semantic_contract": {
                    "entity": "order",
                    "metric": "list",
                    "record_scope": "exact_ids",
                    "projection": [
                        "order_number",
                        "item",
                        "customer_name",
                    ],
                },
                "requires_clarification": False,
                "planner_invoked": True,
                "valid": True,
                "decision_path": "typed_model_turn_interpretation",
            },
        )

        self.assertTrue(result.success, result.message)
        answer = str((result.data or {}).get("answer") or "")
        self.assertIn("Visible Product Only", answer)
        self.assertNotIn("Private Hidden", answer)
        state = dict((result.data or {}).get("state") or {})
        interpretation = dict(
            (state.get("active_entities") or {}).get("turn_interpretation") or {}
        )
        self.assertNotIn(
            "customer_name", interpretation.get("requested_fields") or []
        )
        plan = dict(
            (state.get("active_entities") or {}).get("task_plan") or {}
        )
        self.assertEqual(
            (plan.get("projection_contract_decisions") or [])[0].get(
                "disposition"
            ),
            "internal_only",
        )
        self.assertEqual(
            plan.get("projection_contract_fields_removed"),
            ["customer_name"],
        )

