    def test_r400_hidden_order_numbers_render_as_verified_stable_ordinals(self) -> None:
        state = AgentSessionState(
            goal="Son iki siparisi kimliklerini gostermeden sira numarasiyla listele",
            active_domain="orders",
            status="complete",
        )
        state.active_entities["turn_interpretation"] = {
            "requested_fields": ["status"],
            "semantic_contract": {
                "entity": "order",
                "metric": "list",
                "record_scope": "all_matching",
                "projection": ["status"],
            },
        }
        state.completed_steps = [
            AgentTaskStep(
                index=1,
                step_id="recent",
                prompt="Son iki siparisi getir",
                operation_domain="orders",
                status="completed",
                tool_names=["orders.recent"],
                result_data={
                    "tool_result": {
                        "tool": "orders.recent",
                        "orders": [
                            {
                                "order_number": "ORD-R400-PRIVATE-1",
                                "status": "Delivered",
                            },
                            {
                                "order_number": "ORD-R400-PRIVATE-2",
                                "status": "Shipped",
                            },
                        ],
                    }
                },
            )
        ]

        answer = response_verifier.project_fallback_response(state, "")
        verified = response_verifier.verify_response_projection(
            answer,
            state,
            source="deterministic_verified_projection",
        )
        leaked = response_verifier.verify_response_projection(
            "- ORD-R400-PRIVATE-1 | durum: Delivered\n"
            "- ORD-R400-PRIVATE-2 | durum: Shipped",
            state,
            source="model_authored_projection",
        )

        self.assertIn("1. siparis", answer)
        self.assertIn("2. siparis", answer)
        self.assertNotIn("ORD-R400-PRIVATE", answer)
        self.assertTrue(verified.success, verified.data)
        self.assertFalse(leaked.success)
        self.assertTrue(
            any(
                "unrequested_sensitive_projection:order_number" in problem
                for problem in list(
                    ((leaked.data or {}).get("response_verification") or {}).get(
                        "reason_codes"
                    )
                    or []
                )
            ),
            leaked.data,
        )

