        self.assertEqual(problems, [])
        self.assertEqual(arguments.get("order_numbers"), [order_number])
        self.assertEqual(arguments.get("item_ordinal"), 1)
        self.assertEqual(arguments.get("research_facets"), ["user_opinions"])
        self.assertEqual(
            bindings.get("item_ordinal"),
            "typed_semantic_contract.contextual_product_ordinal",
        )
        self.assertEqual(
            bindings.get("research_facets"),
            "typed_semantic_contract.public_research_facets",
        )
        identity_result = available_tools()[
            "orders.product_public_identities"
        ].handler(db_name=self.db_path, **arguments)
        self.assertTrue(identity_result.success, identity_result.data)
        identity_data = dict(identity_result.data or {})
        self.assertEqual(identity_data.get("identity_count"), 1)
        self.assertEqual(identity_data.get("selected_item_ordinal"), 1)
        self.assertEqual(identity_data.get("research_facets"), ["user_opinions"])
        self.assertIn(
            "kullanıcı yorumları değerlendirme deneyim",
            identity_data.get("primary_public_query") or "",
        )
        self.assertEqual(
            (identity_data.get("product_identities") or [])[0].get(
                "product_name"
            ),
            "R385 First Public Product",
        )
        serialized = json.dumps(identity_data, ensure_ascii=False)
        self.assertNotIn("R385 Second Public Product", serialized)
        self.assertNotIn(order_number, serialized)
        self.assertNotIn("Private R385 Customer", serialized)

        verifier_state = AgentSessionState(
            goal=message,
            active_domain="orders",
            status="complete",
        )
        verifier_state.active_entities["turn_interpretation"] = interpretation
        verifier_state.completed_steps = [
            AgentTaskStep(
                index=1,
                step_id="identity",
                prompt=message,
                status="completed",
                tool_names=["orders.product_public_identities"],
                verification_status="verified",
                result_data={"tool_result": identity_data},
            )
        ]
        projected = response_verifier._full_order_context_projection_problems(
            "R385 First Public Product için kullanıcı yorumları özetlendi.",
            verifier_state,
            {"item", "research_findings", "web_sources"},
        )
        self.assertEqual(projected, [])
        unrelated = response_verifier._full_order_context_projection_problems(
            "Tamamen farklı bir güneş enerjili bahçe lambası incelendi.",
            verifier_state,
            {"item", "research_findings", "web_sources"},
        )
        self.assertIn("public_product_projection_missing:1", unrelated)

