    def test_count_then_print_followup_keeps_the_same_four_ready_orders(self) -> None:
        now_ms = int(datetime.now(TZ_GMT3).timestamp() * 1000)
        ready_numbers = [f"ORD-COUNT-PRINT-{index}" for index in range(1, 5)]
        for index, order_number in enumerate(ready_numbers, start=1):
            self._insert_order(
                order_number,
                now_ms + index * 1_000,
                package_id=97_200 + index,
                status="ReadyToShip",
                cargo_tracking_number=f"TRK-{order_number}",
                cargo_provider_name="Trendyol Express",
            )

        def count_planner(prompt: str) -> str:
            if prompt.startswith("Orders domain agent task plan"):
                return json.dumps(
                    {
                        "steps": [
                            {
                                "id": "ready_count",
                                "operation_id": "orders.ready_to_ship_count",
                                "arguments": {"period": "all"},
                                "depends_on": [],
                                "objective": "Kargoya hazir siparisleri exact say",
                                "expected_evidence": ["count", "order_numbers"],
                            }
                        ]
                    }
                )
            return json.dumps({"decision": "continue", "reason": "Sayim tamam"})

        counted = run_agent_task(
            "Kac siparis var bekleyen?",
            db_name=self.db_path,
            planner_client=count_planner,
            turn_interpretation={
                "mode": "inspect",
                "domain": "orders",
                "objective": "Kargoya hazir siparis sayisini getir",
                "requested_fields": ["count"],
                "requires_clarification": False,
                "valid": True,
            },
        )
        count_state = (counted.data or {}).get("state") or {}
        selection = (count_state.get("selection_snapshots") or [])[0]
        self.assertEqual(selection.get("listed_count"), 4)
        self.assertEqual(
            {row.get("record_id") for row in selection.get("record_refs") or []},
            set(ready_numbers),
        )

        def print_planner(prompt: str) -> str:
            if prompt.startswith("OrderScout semantic action verifier"):
                return json.dumps(
                    {
                        "verdict": "allow",
                        "objective_aligned": True,
                        "domain_aligned": True,
                        "unwanted_effect": False,
                        "reason": "Kullanici onceki exact dort siparisi yazdirmayi istedi.",
                    }
                )
            if prompt.startswith("Orders domain agent task plan"):
                for order_number in ready_numbers:
                    self.assertIn(order_number, prompt)
                return json.dumps(
                    {
                        "steps": [
                            {
                                "id": "print_prior_ready",
                                "operation_id": "labels.create_from_orders.prepare",
                                "arguments": {"brand_code": "TANEX", "model_code": "2610"},
                                "depends_on": [],
                                "objective": "Bu siparisleri TANEX 2610 etiketine hazirla",
                                "expected_evidence": ["record_refs", "selected_record_count"],
                            }
                        ]
                    }
                )
            return json.dumps({"steps": [], "reason": "Baska adim yok"})

        prepared = run_agent_task(
            "Bu siparisleri etiket olarak yazdir, 2610 kullan",
            db_name=self.db_path,
            planner_client=print_planner,
            session_state=count_state,
            turn_interpretation={
                "mode": "act",
                "domain": "orders",
                "objective": "Onceki exact bekleyen siparisleri TANEX 2610 ile yazdir",
                "requested_fields": ["action_result"],
                "requires_clarification": False,
                "valid": True,
            },
        )

        self.assertTrue(prepared.success, prepared.message)
        state = (prepared.data or {}).get("state") or {}
        self.assertEqual(state.get("status"), "pending_approval", state)
        completed = state.get("completed_steps") or []
        self.assertEqual(
            ((completed[-1].get("result_data") or {}).get("dependency_bindings") or {}).get("order_numbers"),
            "session_context:order_selection.order_numbers",
        )
        action = (state.get("pending_actions") or [])[0]
        payload = ((action.get("arguments") or {}).get("payload") or {})
        self.assertEqual(set(payload.get("order_numbers") or []), set(ready_numbers))
        self.assertEqual(action.get("selected_record_count"), 4)
        self.assertEqual(action.get("preview_item_count"), 4)
        self.assertEqual(action.get("execute_input_count"), 4)

    def test_phase8a_frozen_deepseek_count_and_correction_use_one_exact_truth_set(self) -> None:
        now_ms = int(datetime.now(TZ_GMT3).timestamp() * 1000)
        ready_numbers = [f"ORD-PHASE8A-READY-{index:02d}" for index in range(1, 12)]
        for index, order_number in enumerate(ready_numbers, start=1):
            self._insert_order(
                order_number,
                now_ms - index * 60_000,
                package_id=98_000 + index,
                status="ReadyToShip",
                cargo_tracking_number=f"TRK-{order_number}",
                cargo_provider_name="Trendyol Express",
            )
        for index in range(1, 6):
            self._insert_order(
                f"SIM-PHASE8A-{index:02d}",
                now_ms - index * 30_000,
                package_id=98_100 + index,
                status="ReadyToShip",
                cargo_tracking_number=f"SIM-TRK-{index}",
                cargo_provider_name="Simulated Trendyol Express",
            )

        task_plan_calls = 0

        def weak_cloud(prompt: str) -> str:
            nonlocal task_plan_calls
            if prompt.startswith("OrderScout typed tur yorumu"):
                return json.dumps(
                    {
                        "mode": "inspect",
                        "domain": "orders",
                        "objective": "Bekleyen siparis sayisini getir",
                        "intent_kind": "data_read",
                        "requested_fields": ["count"],
                        "entity": "order",
                        "metric": "list",
                        "status_scope": "waiting_action",
                        "period": "all",
                        "freshness": "local_snapshot",
                        "reason": "Count requested",
                        "requires_clarification": False,
                        "clarification": "",
                    }
                )
            if prompt.startswith("Orders domain agent task plan"):
                task_plan_calls += 1
                return json.dumps(
                    {
                        "steps": [
                            {
                                "id": "ready_count",
                                "operation_id": "orders.ready_to_ship_count",
                                "arguments_json": '{"period":"all"}',
                                "depends_on": [],
                                "objective": "Bekleyen siparişleri exact say",
                                "expected_evidence": [
                                    "count",
                                    "order_numbers",
                                ],
                            },
                        ]
                    }
                )
            return json.dumps(
                {"decision": "complete", "reason": "Done", "steps": []}
            )

