    def test_pending_prepare_blocks_when_active_source_snapshot_changed(self) -> None:
        selection = SelectionSnapshot.from_order_numbers(
            ["ORD-STALE-PREPARE-1", "ORD-STALE-PREPARE-2"],
            source_tool="orders.ready_to_ship_count",
            listed_count=2,
            total_count=2,
            truncated=False,
            account_by_order={
                "ORD-STALE-PREPARE-1": "1",
                "ORD-STALE-PREPARE-2": "1",
            },
            environment_by_account={"1": "production"},
            query_fingerprint="query-before-prepare",
            source_revision="100",
            source_snapshot_hash="snapshot-before-prepare",
        )
        state = AgentSessionState(
            goal="Exact secimi etikete hazirla",
            active_domain="orders",
        )
        state.add_selection_snapshot(selection)
        action = {
            "action_type": "labels.action_create_labels_from_selected_orders",
            "approval_required": True,
            "execute_enabled": True,
            "arguments": {
                "validation_source_revision": "101",
                "validation_source_snapshot_hash": "snapshot-after-change",
            },
            "record_refs": [ref.to_dict() for ref in selection.refs],
            "selected_record_count": 2,
            "preview_item_count": 2,
            "execute_input_count": 2,
            "warnings": [],
        }

        bound = task_runtime._bind_pending_action_to_active_selection(
            action,
            state,
        )

        self.assertEqual(bound.get("selection_id"), selection.selection_id)
        self.assertFalse(bound.get("execute_enabled"))
        self.assertTrue(bound.get("requires_reprepare"))
        self.assertEqual(bound.get("stale_reason"), "source_snapshot_changed")
        self.assertEqual(
            (bound.get("arguments") or {}).get("source_snapshot_hash"),
            "snapshot-before-prepare",
        )
        self.assertTrue(bound.get("warnings"))

    def _direct_label_planner(
        self,
        order_numbers: list[str],
        *,
        semantic_verdict: str = "allow",
    ):
        def planner(prompt: str) -> str:
            if prompt.startswith("OrderScout semantic action verifier"):
                allowed = semantic_verdict == "allow"
                return json.dumps(
                    {
                        "verdict": semantic_verdict,
                        "objective_aligned": allowed,
                        "domain_aligned": True,
                        "unwanted_effect": not allowed,
                        "reason": "Test semantic action verdict",
                    }
                )
            if "yeniden planla" in prompt:
                return json.dumps({"steps": [], "reason": "Guvenli alternatif yok"})
            return json.dumps(
                {
                    "steps": [
                        {
                            "id": "prepare_labels",
                            "operation_id": "labels.create_from_orders.prepare",
                            "arguments": {
                                "order_numbers": list(order_numbers),
                                "brand_code": "TANEX",
                                "model_code": "2610",
                                "only_not_printed": True,
                            },
                            "depends_on": [],
                            "objective": "Exact siparisler icin TANEX 2610 etiket onayi hazirla",
                            "expected_evidence": ["selected_record_count", "record_refs"],
                        }
                    ]
                }
            )

        return planner

    def test_direct_effectful_plan_requires_typed_act_mode_before_prepare(self) -> None:
        planner = self._direct_label_planner(["ORD-SEMANTIC-MODE-1"])

        with patch(
            "AI.processors.tools.labels_prepare_create_from_orders",
            side_effect=AssertionError("inspect mode must be rejected before prepare"),
        ) as prepare_mock:
            result = run_agent_task(
                "ORD-SEMANTIC-MODE-1 siparisini TANEX 2610 etiketiyle yazdir",
                db_name=self.db_path,
                planner_client=planner,
                turn_interpretation={
                    "mode": "inspect",
                    "domain": "orders",
                    "objective": "Etiket isleminin ne yapacagini incele",
                    "requires_clarification": False,
                    "valid": True,
                    "planner_invoked": True,
                },
            )

        self.assertTrue(result.success, result.message)
        prepare_mock.assert_not_called()
        state = (result.data or {}).get("state") or {}
        self.assertEqual(state.get("status"), "failed")
        checks = ((state.get("active_entities") or {}).get("semantic_verifications") or [])
        self.assertIn(
            "mutation_requires_typed_act_mode",
            [code for row in checks for code in (row.get("reason_codes") or [])],
        )

