    def test_explicit_typed_intent_overrides_semantic_model_false_negative(self) -> None:
        now_ms = int(datetime.now(TZ_GMT3).timestamp() * 1000)
        order_number = "ORD-SEMANTIC-FALSE-NEGATIVE-1"
        self._insert_order(
            order_number,
            now_ms,
            package_id=97_061,
            status="ReadyToShip",
            cargo_tracking_number="TRK-SEMANTIC-FALSE-NEGATIVE-1",
            cargo_provider_name="Trendyol Express",
        )
        planner = self._direct_label_planner(
            [order_number],
            semantic_verdict="deny",
        )

        result = run_agent_task(
            f"{order_number} siparisini TANEX 2610 etiketiyle yazdir",
            db_name=self.db_path,
            planner_client=planner,
            turn_interpretation={
                "mode": "act",
                "domain": "orders",
                "objective": f"{order_number} siparisini TANEX 2610 etiketiyle yazdir",
                "requires_clarification": False,
                "valid": True,
                "planner_invoked": True,
            },
        )

        self.assertTrue(result.success, result.message)
        state = (result.data or {}).get("state") or {}
        self.assertEqual(state.get("status"), "pending_approval", state)
        checks = ((state.get("active_entities") or {}).get("semantic_verifications") or [])
        plan_check = next(row for row in checks if row.get("phase") == "plan_step")
        self.assertTrue(plan_check.get("allowed"), plan_check)
        evidence = plan_check.get("evidence") or {}
        self.assertTrue(evidence.get("deterministic_intent_alignment"), evidence)
        self.assertTrue(
            ((evidence.get("model_verdict") or {}).get("skipped")),
            evidence,
        )

