    def test_failed_direct_operation_replans_to_another_typed_atomic_operation(self) -> None:
        initial_meta = {
            "source": "llm_direct",
            "step_ids": ["primary_query"],
            "step_specs": [
                {
                    "id": "primary_query",
                    "operation_id": "orders.query",
                    "arguments": {"period": "today", "mode": "count"},
                    "depends_on": [],
                    "objective": "Bugunku siparis sayisini typed sorguyla getir",
                    "expected_evidence": ["count"],
                }
            ],
        }

        def planner(prompt: str) -> str:
            if prompt.startswith("GoalPlan observation"):
                return json.dumps({"decision": "complete", "reason": "Recovered exact count observed"})
            self.assertIn("Basarisiz step: primary_query", prompt)
            self.assertIn("orders.count", prompt)
            return json.dumps(
                {
                    "steps": [
                        {
                            "id": "fallback_count",
                            "operation_id": "orders.count",
                            "arguments": {"period": "today"},
                            "depends_on": [],
                            "objective": "Alternatif canonical sayim operation'ini calistir",
                            "expected_evidence": ["count"],
                        }
                    ],
                    "reason": "Ilk sorgu yolu kullanilamadi.",
                }
            )

        with patch(
            "AI.processors.task_runtime._orders_task_plan",
            return_value=(["primary_query"], initial_meta),
        ), patch(
            "AI.processors.task_runtime._run_bound_domain_read_step",
            side_effect=[
                Result.fail("primary repository unavailable", close_dialog=False),
                Result.ok(
                    "Bugun 3 siparis var.",
                    close_dialog=False,
                    data={
                        "mode": "tool",
                        "answer": "Bugun 3 siparis var.",
                        "tool_call": {
                            "tool": "orders.count",
                            "arguments": {"period": "today"},
                        },
                        "tool_result": {"count": 3, "period": "today"},
                    },
                ),
            ],
        ), patch(
            "AI.processors.task_runtime.run_agent_turn",
            side_effect=AssertionError("typed replan must remain directly bound"),
        ) as turn_mock:
            result = run_agent_task(
                "Bugunku siparis sayisini getir",
                db_name=self.db_path,
                planner_client=planner,
            )

        self.assertTrue(result.success, result.message)
        turn_mock.assert_not_called()
        state = (result.data or {}).get("state") or {}
        self.assertEqual(state.get("status"), "complete")
        self.assertEqual(
            [step.get("step_id") for step in state.get("completed_steps") or []],
            ["primary_query", "fallback_count"],
        )
        self.assertEqual(
            ((state.get("completed_steps") or [])[0].get("result_data") or {}).get("replan_status"),
            "superseded",
        )
        goal_plan = (state.get("goal_plans") or [])[0]
        self.assertEqual(goal_plan.get("revision"), 2)
        fallback = {
            step.get("step_id"): step
            for step in goal_plan.get("steps") or []
        }["fallback_count"]
        self.assertEqual(fallback.get("operation_candidates"), ["orders.count"])
        self.assertEqual(fallback.get("arguments"), {"period": "today"})
        replan = ((goal_plan.get("metadata") or {}).get("replans") or [])[0]
        self.assertEqual(replan.get("replacement_step_ids"), ["fallback_count"])

    def test_successful_observation_can_replan_remaining_goal_graph(self) -> None:
        evaluation_calls = 0

        def planner(prompt: str) -> str:
            nonlocal evaluation_calls
            if prompt.startswith("Orders domain agent task plan"):
                return json.dumps(
                    {
                        "steps": [
                            {
                                "id": "ready_count",
                                "operation_id": "orders.ready_to_ship_count",
                                "arguments": {"period": "today"},
                                "depends_on": [],
                                "objective": "Kargoya hazir siparisleri say",
                                "expected_evidence": ["count"],
                            },
                            {
                                "id": "old_status_step",
                                "operation_id": "orders.status_counts",
                                "arguments": {"period": "today"},
                                "depends_on": ["ready_count"],
                                "objective": "Eski durum dagilimi adimi",
                                "expected_evidence": ["status_counts"],
                            },
                        ]
                    }
                )
            self.assertTrue(prompt.startswith("GoalPlan observation degerlendirmesi"))
            evaluation_calls += 1
            if evaluation_calls == 1:
                return json.dumps(
                    {
                        "decision": "replan",
                        "reason": "Observation sonrasinda yalniz genel sayim gerekli.",
                        "steps": [
                            {
                                "id": "replacement_count",
                                "operation_id": "orders.count",
                                "arguments": {"period": "today"},
                                "depends_on": ["ready_count"],
                                "objective": "Bugunku tum siparisleri say",
                                "expected_evidence": ["count"],
                            }
                        ],
                    }
                )
            return json.dumps(
                {
                    "decision": "complete",
                    "reason": "Gerekli iki authoritative sayim tamamlandi.",
                    "steps": [],
                }
            )

        with patch(
            "AI.processors.task_runtime.run_agent_turn",
            side_effect=AssertionError("observation replan must stay directly bound"),
        ) as turn_mock:
            result = run_agent_task(
                "Bugunku bekleyen ve toplam siparis sayisini incele",
                db_name=self.db_path,
                planner_client=planner,
            )

        self.assertTrue(result.success, result.message)
        turn_mock.assert_not_called()
        state = (result.data or {}).get("state") or {}
        self.assertEqual(state.get("status"), "complete")
        self.assertEqual(
            [step.get("step_id") for step in state.get("completed_steps") or []],
            ["ready_count", "replacement_count"],
        )
        goal_plan = (state.get("goal_plans") or [])[0]
        by_id = {
            step.get("step_id"): step
            for step in goal_plan.get("steps") or []
        }
        self.assertEqual(by_id["old_status_step"].get("status"), "superseded")
        self.assertEqual(
            by_id["replacement_count"].get("operation_candidates"),
            ["orders.count"],
        )
        self.assertEqual(goal_plan.get("revision"), 2)
        evaluations = (state.get("active_entities") or {}).get("goal_evaluations") or []
        self.assertEqual([row.get("decision") for row in evaluations], ["replan", "complete"])
        self.assertTrue(all(row.get("applied") for row in evaluations))
        self.assertEqual(evaluation_calls, 2)

    def test_observation_replan_cannot_drop_population_metric_dimensions(
        self,
    ) -> None:
        state = AgentSessionState(
            goal="Toplam siparişleri genel olarak analiz et",
            active_domain="orders",
            active_entities={
                "turn_interpretation": {
                    "mode": "inspect",
                    "domain": "orders",
                    "intent_kind": "data_read",
                    "requested_fields": [
                        "count",
                        "status",
                        "amount",
                        "item_sales_rows",
                    ],
                    "semantic_contract": {
                        "entity": "order",
                        "metric": "count",
                        "status_scope": "all",
                        "record_scope": "all_matching",
                        "period": "all",
                        "metric_requirements": [
                            ORDER_TOTAL_COUNT_METRIC,
                            ORDER_STATUS_DISTRIBUTION_METRIC,
                            ORDER_REVENUE_TOTAL_METRIC,
                            ORDER_ITEM_SALES_SUMMARY_METRIC,
                        ],
                    },
                }
            },
        )
        completed = AgentTaskStep(
            index=1,
            step_id="total",
            prompt="Toplamı getir",
            objective="Toplamı getir",
            operation_candidates=["orders.count"],
            operation_domain="orders",
            status="completed",
            verification_status="observed",
            tool_names=["orders.count"],
            result_data={"tool_result": {"count": 3112}},
        )
        state.completed_steps = [completed]
        state.remaining_steps = [
            AgentTaskStep(
                index=2,
                step_id="overview",
                prompt="Durum ve ciroyu getir",
                objective="Durum ve ciroyu getir",
                operation_candidates=["orders.summary"],
                operation_domain="orders",
                arguments={"period": "all"},
            ),
            AgentTaskStep(
                index=3,
                step_id="items",
                prompt="Ürün satışlarını getir",
                objective="Ürün satışlarını getir",
                operation_candidates=["orders.item_sales_summary"],
                operation_domain="orders",
                arguments={"period": "all"},
            ),
        ]
        observation = Observation.create(
            domain="orders",
            operation_name="orders.count",
            success=True,
            aggregates={"count": 3112},
            source="local_db",
        )

        evaluation = task_runtime._reevaluate_goal_after_observation(
            state,
            completed,
            observation,
            planner_client=lambda _prompt: json.dumps(
                {
                    "decision": "replan",
                    "reason": "Ürün özeti tek başına yeterli.",
                    "steps": [
                        {
                            "id": "replacement_items",
                            "operation_id": "orders.item_sales_summary",
                            "arguments": {"period": "all", "limit": 10},
                            "depends_on": ["total"],
                            "objective": "Ürün satışlarını özetle",
                            "expected_evidence": ["rows"],
                        }
                    ],
                },
                ensure_ascii=False,
            ),
            max_steps=8,
            max_replans=1,
        )

        self.assertEqual(evaluation.get("decision"), "continue")
        self.assertFalse(evaluation.get("applied"))
        self.assertEqual(
            evaluation.get("reason"),
            "observation_replan_rejected_metric_coverage",
        )
        self.assertEqual(
            evaluation.get("missing_metric_requirements"),
            [
                ORDER_STATUS_DISTRIBUTION_METRIC,
                ORDER_REVENUE_TOTAL_METRIC,
            ],
        )
        self.assertEqual(
            [step.step_id for step in state.remaining_steps],
            ["overview", "items"],
        )

