    def test_observation_evaluator_can_pause_with_a_persistable_clarification(self) -> None:
        def planner(prompt: str) -> str:
            if prompt.startswith("Orders domain agent task plan"):
                return json.dumps(
                    {
                        "steps": [
                            {
                                "id": "initial_count",
                                "operation_id": "orders.count",
                                "arguments": {"period": "today"},
                                "depends_on": [],
                                "objective": "Bugunku siparisleri say",
                                "expected_evidence": ["count"],
                            }
                        ]
                    }
                )
            return json.dumps(
                {
                    "decision": "clarify",
                    "reason": "Kullanici rapor kapsamini belirtmedi.",
                    "clarification": "Raporu hangi mağaza için hazırlayayım?",
                    "steps": [],
                }
            )

        with tempfile.TemporaryDirectory() as temp_dir, patch(
            "AI.processors.task_runtime.run_agent_turn",
            side_effect=AssertionError("direct clarification flow must remain bound"),
        ) as turn_mock:
            result = run_agent_task(
                "Bugunku siparisleri say ve sonra magaza raporuna hazirlan",
                db_name=self.db_path,
                planner_client=planner,
                persist=True,
                task_store_root=temp_dir,
            )

            self.assertTrue(Path((result.data or {}).get("state_path") or "").is_file())

        self.assertTrue(result.success, result.message)
        turn_mock.assert_not_called()
        self.assertEqual((result.data or {}).get("answer"), "Raporu hangi mağaza için hazırlayayım?")
        state = (result.data or {}).get("state") or {}
        self.assertEqual(state.get("status"), "needs_clarification")
        self.assertEqual(
            (state.get("active_entities") or {}).get("clarification"),
            "Raporu hangi mağaza için hazırlayayım?",
        )
        self.assertEqual((state.get("goal_plans") or [])[0].get("status"), "needs_clarification")

    def test_typed_turn_interpretation_uses_model_for_mode_and_domain(self) -> None:
        prompts: list[str] = []

        def planner(prompt: str) -> str:
            prompts.append(prompt)
            return json.dumps(
                {
                    "mode": "inspect",
                    "domain": "orders",
                    "objective": "Bekleyen siparislerin authoritative sayisini getir",
                    "requested_fields": ["count"],
                    "reason": "Orders verisi gerekiyor.",
                    "requires_clarification": False,
                }
            )

        result = task_runtime.interpret_agent_turn(
            "kac siparis var bekleyen",
            planner_client=planner,
            history=[{"role": "user", "content": "magazam nasil gidiyor"}],
        )

        self.assertTrue(result.success, result.message)
        self.assertTrue(prompts)
        self.assertNotIn("Semantic operation ipuclari", prompts[0])
        self.assertNotIn("orders.ready_to_ship_count", prompts[0])
        self.assertIn("Yalniz tek bir JSON nesnesi dondur", prompts[0])
        self.assertLess(len(prompts[0]), 8_000)
        data = result.data or {}
        self.assertEqual((data.get("mode"), data.get("domain")), ("inspect", "orders"))
        self.assertEqual(data.get("requested_fields"), ["count"])
        self.assertTrue(data.get("planner_invoked"))
        self.assertEqual(data.get("decision_path"), "typed_model_turn_interpretation")

