    def test_orders_task_runtime_return_approval_plans_executes_and_verifies(self) -> None:
        now_ms = int(datetime.now(TZ_GMT3).timestamp() * 1000)
        self._insert_waiting_return("CLAIM-TASK-APPROVE-1", "ORD-TASK-RETURN-1", now_ms)

        def planner(prompt: str) -> str:
            if prompt.startswith("OrderScout semantic action verifier"):
                return json.dumps({"verdict": "allow", "objective_aligned": True, "domain_aligned": True, "unwanted_effect": False, "reason": "Exact return approval is aligned."})
            if prompt.startswith("Orders model plan semantic repair"):
                return json.dumps(
                    {
                        "steps": [
                            {
                                "id": "returns.waiting.list",
                                "operation_id": "returns.query",
                                "arguments_json": json.dumps(
                                    {"filters": {"waiting_action_only": True}}
                                ),
                                "depends_on": [],
                            },
                            {
                                "id": "returns.approve.prepare",
                                "operation_id": "returns.approve.prepare",
                                "arguments_json": json.dumps(
                                    {"query": "CLAIM-TASK-APPROVE-1"}
                                ),
                                "depends_on": ["returns.waiting.list"],
                            },
                        ]
                    }
                )
            if prompt.startswith("Orders domain agent task plan"):
                return json.dumps(
                    {
                        "steps": [
                            {"id": "orders.full_context"},
                            {"id": "returns.approve.prepare"},
                        ]
                    }
                )
            return '{"mode":"tool","tool":"orders.count","arguments":{"period":"today"}}'

        result = run_agent_task(
            "Bekleyen iadeleri bul ve uygun iadeyi onayla",
            db_name=self.db_path,
            planner_client=planner,
            turn_interpretation={"mode": "act", "domain": "orders", "objective": "Bekleyen iadeyi onaya hazirla", "valid": True},
        )

        self.assertTrue(result.success, result.message)
        state = (result.data or {}).get("state") or {}
        plan = ((state.get("active_entities") or {}).get("task_plan") or {})
        self.assertEqual(plan.get("step_ids"), ["returns.waiting.list", "returns.approve.prepare"])
        self.assertEqual(plan.get("source"), "llm_direct_repaired")
        self.assertIn(
            "returns.waiting.list",
            (plan.get("initial_compile_verification") or {}).get("semantic_missing_step_ids") or [],
        )
        self.assertEqual(state.get("status"), "pending_approval")
        steps = state.get("completed_steps") or []
        self.assertEqual([step.get("tool_names") for step in steps], [["returns.query"], ["returns.approve.prepare"]])
        expected_claim_date = datetime.fromtimestamp(now_ms / 1000, tz=TZ_GMT3).strftime("%Y-%m-%d %H:%M")
        return_list_data = (steps[0] or {}).get("result_data") or {}
        return_rows = (return_list_data.get("tool_result") or {}).get("returns") or []
        self.assertEqual((return_rows[0] or {}).get("claim_date"), expected_claim_date)
        pending = state.get("pending_actions") or []
        self.assertEqual(len(pending), 1)
        action = pending[0]
        self.assertEqual(action.get("action_type"), "orders.approve_return_claim")
        payload = ((action.get("arguments") or {}).get("payload") or {})
        self.assertEqual(payload.get("order"), "CLAIM-TASK-APPROVE-1")

        def fake_approve_return_claim(*, order, **_kwargs):
            with Session(get_engine(self.db_path)) as session:
                claim = session.exec(select(ReturnClaim).where(ReturnClaim.claimId == order.claimId)).one()
                claim.claimItemStatus = "Accepted"
                claim.waitingClaimLineItemIds = []
                session.add(claim)
                session.commit()
            return Result.ok("Iade onaylandi.", close_dialog=False, data={"claim_id": order.claimId})

        with tempfile.TemporaryDirectory() as temp_dir, patch(
            "Orders.views.actions.approve_return_claim",
            side_effect=fake_approve_return_claim,
        ):
            audit_path = Path(temp_dir) / "return-approval-audit.jsonl"
            resumed = resume_agent_task_with_approval(
                state,
                approved_by="return-task-runtime",
                db_name=self.db_path,
                audit_path=str(audit_path),
                idempotency_key="return-task-approval",
            )
            self.assertTrue(audit_path.exists())

        self.assertTrue(resumed.success, resumed.message)
        resumed_state = (resumed.data or {}).get("state") or {}
        self.assertEqual(resumed_state.get("status"), "complete")
        self.assertEqual(resumed_state.get("pending_actions"), [])
        history = resumed_state.get("action_history") or []
        self.assertEqual(history[-1].get("phase"), "execute")
        self.assertTrue((history[-1].get("verify") or {}).get("verified"), history[-1])
        with Session(get_engine(self.db_path)) as session:
            claim = session.exec(select(ReturnClaim).where(ReturnClaim.claimId == "CLAIM-TASK-APPROVE-1")).one()
            self.assertEqual(claim.claimItemStatus, "Accepted")
            self.assertEqual(claim.waitingClaimLineItemIds, [])

