    def test_orders_task_runtime_repairs_malformed_goal_plan_json_once(self) -> None:
        responses = iter(
            [
                '{"steps":[',
                json.dumps(
                    {
                        "steps": [
                            {
                                "id": "ready_count",
                                "operation_id": "orders.ready_to_ship_count",
                                "arguments_json": '{"period":"all"}',
                                "depends_on": [],
                                "objective": "Kargoya hazir siparis sayisini getir",
                                "expected_evidence": ["count"],
                            }
                        ]
                    }
                ),
            ]
        )
        prompts: list[str] = []

        def planner(prompt: str) -> str:
            prompts.append(prompt)
            return next(responses)

        result = run_agent_task(
            "Kargoya hazir kac siparis var?",
            db_name=self.db_path,
            planner_client=planner,
            turn_interpretation={
                "mode": "inspect",
                "domain": "orders",
                "objective": "Kargoya hazir siparis sayisini getir",
                "intent_kind": "data_read",
                "request_shape": "scalar",
                "requested_fields": ["count"],
                "semantic_contract": {
                    "entity": "order",
                    "metric": "count",
                    "status_scope": "ready_to_ship",
                    "record_scope": "all_matching",
                    "period": "all",
                    "projection": ["count"],
                },
                "valid": True,
            },
        )

        self.assertTrue(result.success, result.message)
        state = (result.data or {}).get("state") or {}
        plan = ((state.get("active_entities") or {}).get("task_plan") or {})
        self.assertEqual(plan.get("source"), "llm_direct")
        self.assertEqual(plan.get("step_ids"), ["ready_count"])
        self.assertGreaterEqual(len(prompts), 2)
        self.assertTrue(
            prompts[1].startswith(
                "Orders domain agent task plan JSON repair"
            )
        )
        repair = dict(plan.get("planner_json_repair") or {})
        self.assertTrue(repair.get("invoked"))
        self.assertTrue(repair.get("applied"))
        self.assertEqual(repair.get("attempt_count"), 1)
        self.assertEqual(
            repair.get("initial_error"),
            "planner response has no complete JSON payload",
        )
        self.assertEqual(repair.get("initial_response_length"), 10)
        self.assertNotIn("initial_response", repair)
        self.assertEqual(state.get("status"), "complete")

    def test_nested_goal_plan_json_dialect_is_canonicalized_without_model_repair(
        self,
    ) -> None:
        prompts: list[str] = []

        def planner(prompt: str) -> str:
            prompts.append(prompt)
            return json.dumps(
                [
                    {
                        "goal_plan": {
                            "steps": [
                                {
                                    "id": "total",
                                    "operation_id": "orders.count",
                                    "arguments_json": "{}",
                                    "depends_on": [],
                                    "objective": "Yerel toplam siparis sayisini getir",
                                    "expected_evidence": [
                                        "count",
                                        "store",
                                        "scope",
                                    ],
                                }
                            ]
                        }
                    }
                ],
                ensure_ascii=False,
            )

        result = run_agent_task(
            "Pazaryerinden güncellemeden yerel toplamı ve kapsamı söyle.",
            db_name=self.db_path,
            planner_client=planner,
            turn_interpretation={
                "mode": "inspect",
                "domain": "orders",
                "objective": "Yerel toplam siparis sayisini ve kapsamı getir",
                "intent_kind": "data_read",
                "request_shape": "scalar",
                "requested_fields": ["count", "store", "scope"],
                "semantic_contract": {
                    "entity": "order",
                    "metric": "count",
                    "status_scope": "all",
                    "record_scope": "all_matching",
                    "period": "all",
                    "freshness": "local_snapshot",
                    "projection": ["count", "store", "scope"],
                    "metric_requirements": [ORDER_TOTAL_COUNT_METRIC],
                },
                "valid": True,
            },
        )

        self.assertTrue(result.success, result.message)
        state = dict((result.data or {}).get("state") or {})
        plan = dict((state.get("active_entities") or {}).get("task_plan") or {})
        plan_prompts = [
            prompt
            for prompt in prompts
            if prompt.startswith("Orders domain agent task plan")
        ]
        self.assertEqual(len(plan_prompts), 1, plan)
        self.assertFalse(
            any(
                prompt.startswith("Orders model plan semantic repair")
                for prompt in prompts
            ),
            prompts,
        )
        self.assertEqual(plan.get("source"), "llm_direct")
        self.assertEqual(plan.get("step_ids"), ["total"])
        observability = dict(plan.get("planner_response_observability") or {})
        self.assertEqual(observability.get("normalized_step_count"), 1)
        self.assertEqual(
            observability.get("normalized_operation_ids"),
            ["orders.count"],
        )
        self.assertNotIn("planner_json_repair", plan)

