    def test_model_authored_explicit_fetch_skips_redundant_model_verdict(
        self,
    ) -> None:
        with Session(get_engine(self.db_path)) as session:
            session.add(
                ApiAccount(
                    pk=1,
                    account_id="784195",
                    comp_name="MDB",
                    platform="trendyol",
                )
            )
            session.commit()

        prompts: list[str] = []

        def planner(prompt: str) -> str:
            prompts.append(prompt)
            if prompt.startswith("OrderScout semantic action verifier"):
                raise AssertionError(
                    "explicit deterministic intent must not spend another model call"
                )
            return json.dumps(
                {
                    "steps": [
                        {
                            "id": "sync",
                            "operation_id": "orders.fetch.prepare",
                            "arguments_json": '{"api_account_ids":[1]}',
                            "depends_on": [],
                            "objective": (
                                "Sipariş verilerimi şimdi güncelle ve canonical "
                                "hesap kapsamını kullan."
                            ),
                            "expected_evidence": [
                                "api_account_ids",
                                "account_scopes",
                            ],
                        }
                    ]
                },
                ensure_ascii=False,
            )

        result = run_agent_task(
            "Başkan sipariş verilerimi şimdi güncelle",
            db_name=self.db_path,
            planner_client=planner,
            turn_interpretation={
                "mode": "act",
                "domain": "orders",
                "objective": "Sipariş verilerimi şimdi güncelle",
                "intent_kind": "action",
                "requested_fields": ["scope"],
                "valid": True,
                "planner_invoked": True,
            },
        )

        self.assertTrue(result.success, result.message)
        state = (result.data or {}).get("state") or {}
        self.assertEqual(state.get("status"), "pending_approval")
        self.assertFalse(
            any(
                prompt.startswith("OrderScout semantic action verifier")
                for prompt in prompts
            )
        )
        verification = next(
            row
            for row in (
                (state.get("active_entities") or {}).get(
                    "semantic_verifications"
                )
                or []
            )
            if row.get("phase") == "plan_step"
        )
        evidence = verification.get("evidence") or {}
        self.assertTrue(evidence.get("deterministic_intent_alignment"))
        self.assertTrue(
            (evidence.get("model_verdict") or {}).get("skipped")
        )

