    def test_orders_task_runtime_fetch_executes_and_verifies_saved_orders(self) -> None:
        from Orders.processors.trendyol import pipeline as orders_pipeline

        with Session(get_engine(self.db_path)) as session:
            session.add(ApiAccount(pk=1, account_id="seller-task-fetch", comp_name="Task Fetch Seller", platform="trendyol"))
            session.commit()

        def planner(prompt: str) -> str:
            if prompt.startswith("OrderScout semantic action verifier"):
                return json.dumps({"verdict": "allow", "objective_aligned": True, "domain_aligned": True, "unwanted_effect": False, "reason": "Exact sync plan is aligned."})
            if prompt.startswith("Orders domain agent task plan"):
                return json.dumps(
                    {
                        "steps": [
                            {"id": "orders.fetch.prepare", "operation_id": "orders.fetch.prepare", "arguments_json": '{"api_account_ids":[1]}', "depends_on": []},
                            {"id": "orders.ready_to_ship", "operation_id": "orders.ready_to_ship", "arguments_json": "{}", "depends_on": []},
                            {"id": "orders.labels.prepare", "operation_id": "labels.create_from_orders.prepare", "arguments_json": "{}", "depends_on": []},
                            {"id": "returns.waiting.list", "operation_id": "returns.query", "arguments_json": "{}", "depends_on": []},
                        ]
                    }
                )
            return '{"mode":"tool","tool":"orders.count","arguments":{"period":"today"}}'

        result = run_agent_task(
            "Trendyol siparis verilerini cek",
            db_name=self.db_path,
            planner_client=planner,
            turn_interpretation={"mode": "act", "domain": "orders", "objective": "Trendyol siparis verilerini senkronize et", "valid": True},
        )

        self.assertTrue(result.success, result.message)
        state = (result.data or {}).get("state") or {}
        plan = ((state.get("active_entities") or {}).get("task_plan") or {})
        self.assertEqual(plan.get("step_ids"), ["orders.fetch.prepare"])
        self.assertIn("orders.ready_to_ship", plan.get("rejected_step_ids") or [])
        self.assertIn("returns.waiting.list", plan.get("rejected_step_ids") or [])
        self.assertEqual(state.get("status"), "pending_approval")
        pending = state.get("pending_actions") or []
        self.assertEqual(len(pending), 1)
        action = pending[0]
        self.assertEqual(action.get("action_type"), "orders.get_orders_from_companies")
        payload = ((action.get("arguments") or {}).get("payload") or {})
        self.assertEqual(payload.get("api_account_ids"), [1])
        self.assertNotIn("accounts", payload)

        fetch_calls: list[dict] = []
        save_calls: list[dict] = []
        now_ms = int(datetime.now(TZ_GMT3).timestamp() * 1000)

        def fake_fetch_orders_all(**kwargs):
            fetch_calls.append(dict(kwargs))
            return Result.ok(
                "Orders fake cekildi.",
                close_dialog=False,
                data={
                    "order_data_list": [
                        {
                            "id": 81001,
                            "shipmentPackageId": 81001,
                            "orderNumber": "ORD-TASK-FETCH-1",
                            "api_account_id": 1,
                            "lastModifiedDate": now_ms,
                            "orderDate": now_ms,
                            "status": "Picking",
                            "shipmentPackageStatus": "ReadyToShip",
                            "customerFirstName": "Sensitive Fetch Name",
                            "shipmentAddress": {"fullAddress": "Private Street 42"},
                        }
                    ],
                    "order_item_list": [],
                    "sync_diagnostics": {
                        "source_rows_seen": 1,
                        "normalized_order_rows": 1,
                        "normalized_item_rows": 0,
                        "skipped_source_rows": 0,
                        "skipped_reasons": {},
                        "source_rows_complete": True,
                        "fetch_errors": 0,
                    },
                },
            )

        def fake_save_orders(result_payload, db_name=None):
            rows = list((result_payload.data or {}).get("order_data_list") or [])
            save_calls.append({"rows": rows, "db_name": db_name})
            return original_save_orders(result_payload, db_name=db_name)

        original_save_orders = orders_pipeline.save_orders_to_db

        with tempfile.TemporaryDirectory() as temp_dir, patch.object(
            orders_pipeline,
            "fetch_orders_all",
            side_effect=fake_fetch_orders_all,
        ), patch.object(
            orders_pipeline,
            "save_orders_to_db",
            side_effect=fake_save_orders,
        ):
            audit_path = Path(temp_dir) / "fetch-task-audit.jsonl"
            resumed = resume_agent_task_with_approval(
                state,
                approved_by="fetch-task-runtime",
                db_name=self.db_path,
                audit_path=str(audit_path),
                idempotency_key="fetch-task-orders",
            )
            self.assertTrue(audit_path.exists())
            audit_text = audit_path.read_text(encoding="utf-8")
            self.assertIn("orders.get_orders_from_companies", audit_text)
            self.assertNotIn("api-key", audit_text)
            self.assertNotIn("api-secret", audit_text)
            self.assertNotIn("Sensitive Fetch Name", audit_text)
            self.assertNotIn("Private Street 42", audit_text)

        self.assertTrue(resumed.success, resumed.message)
        resumed_state = (resumed.data or {}).get("state") or {}
        self.assertEqual(resumed_state.get("status"), "complete")
        history = resumed_state.get("action_history") or []
        self.assertEqual(history[-1].get("phase"), "execute")
        verify = history[-1].get("verify") or {}
        self.assertTrue(verify.get("verified"), history[-1])
        self.assertEqual((verify.get("fetched") or {}).get("unique_orders"), 1)
        self.assertEqual((verify.get("writes") or {}).get("order_snapshots_inserted"), 1)
        self.assertTrue((verify.get("db_readback") or {}).get("verified"), verify)
        self.assertEqual((verify.get("db_readback") or {}).get("found_order_snapshots"), 1)
        self.assertGreater(int((verify.get("watermark") or {}).get("fresh_through_ms") or 0), 0)
        self.assertEqual(len(fetch_calls), 1)
        self.assertEqual((fetch_calls[0].get("comp_api_account_list") or [])[0][0], 1)
        self.assertGreaterEqual(len((fetch_calls[0].get("comp_api_account_list") or [])[0]), 4)
        self.assertEqual(len(save_calls), 1)
        self.assertEqual(save_calls[0]["rows"][0]["orderNumber"], "ORD-TASK-FETCH-1")
        self.assertEqual(save_calls[0]["db_name"], self.db_path)
        final_answer = str((resumed.data or {}).get("answer") or "")
        self.assertIn("Task Fetch Seller / production", final_answer)
        self.assertIn("DB read-back 1/1", final_answer)
        execute_result = dict((resumed.data or {}).get("execute") or {})
        persisted_result = dict(execute_result.get("result") or {})
        self.assertNotIn("order_data_list", dict(persisted_result.get("fetch") or {}))
        self.assertNotIn("Sensitive Fetch Name", json.dumps(persisted_result, ensure_ascii=False))

