    def test_contextual_task_runs_two_approval_cycles_without_losing_order_scope(self) -> None:
        now_ms = int(datetime.now(TZ_GMT3).timestamp() * 1000)
        selected_orders = {"ORD-TASK-TWO-PHASE-1", "ORD-TASK-TWO-PHASE-2"}
        for index, order_number in enumerate(
            (*sorted(selected_orders), "ORD-TASK-TWO-PHASE-UNRELATED"),
            start=1,
        ):
            self._insert_order(
                order_number,
                now_ms + index,
                package_id=990 + index,
                status="ReadyToShip",
                cargo_tracking_number=f"TRK-{order_number}",
                cargo_provider_name="Trendyol Express",
            )
        history = [
            {"role": "user", "content": "Son iki siparisi getir"},
            {
                "role": "assistant",
                "content": "1. ORD-TASK-TWO-PHASE-1\n2. ORD-TASK-TWO-PHASE-2",
            },
        ]
        result = run_agent_task(
            "bunlari yazdir, sonra fis cikarildi isaretle; bitene kadar devam et",
            db_name=self.db_path,
            history=history,
        )
        self.assertTrue(result.success, result.message)
        state = (result.data or {}).get("state") or {}
        plan = ((state.get("active_entities") or {}).get("task_plan") or {})
        self.assertEqual(
            plan.get("step_ids"),
            ["orders.labels.prepare", "orders.labels.extracted.prepare"],
        )
        first_action = (state.get("pending_actions") or [])[0]
        first_payload = (((first_action.get("arguments") or {}).get("payload")) or {})
        self.assertEqual(set(first_payload.get("order_numbers") or []), selected_orders)

        label_calls: list[list[str]] = []
        label_db_names: list[str | None] = []
        first_resume_progress: list[tuple[int, str]] = []

        def fake_create_order_label_from_orders(order_numbers, *, brand_code="TANEX", model_code="TANEX_2736", db_name=None):
            label_calls.append(list(order_numbers))
            label_db_names.append(db_name)
            return Result.ok("Etiketler olusturuldu.", close_dialog=False, data={"order_numbers": list(order_numbers)})

        with tempfile.TemporaryDirectory() as temp_dir, patch(
            "Labels.processors.pipeline.create_order_label_from_orders",
            side_effect=fake_create_order_label_from_orders,
        ):
            audit_path = Path(temp_dir) / "two-phase-task-audit.jsonl"
            first_resume = resume_agent_task_with_approval(
                state,
                approved_by="two-phase-task",
                db_name=self.db_path,
                audit_path=str(audit_path),
                idempotency_key="two-phase-label",
                progress_callback=lambda percent, message: first_resume_progress.append((percent, message)),
            )
            self.assertTrue(first_resume.success, first_resume.message)
            second_state = (first_resume.data or {}).get("state") or {}
            self.assertEqual(second_state.get("status"), "pending_approval")
            second_action = (second_state.get("pending_actions") or [])[0]
            self.assertEqual(second_action.get("action_type"), "labels.mark_orders_extracted_from_label_result")
            second_payload = (((second_action.get("arguments") or {}).get("payload")) or {})
            self.assertEqual(set(second_payload.get("order_numbers") or []), selected_orders)
            self.assertEqual(
                [percent for percent, _message in first_resume_progress],
                sorted(percent for percent, _message in first_resume_progress),
            )
            self.assertTrue(any("Adim 2/2" in message for _percent, message in first_resume_progress))

            second_resume = resume_agent_task_with_approval(
                second_state,
                approved_by="two-phase-task",
                chat_client=lambda _prompt: (
                    "Iki islem tamamlandi ve dogrulandi. "
                    "Kritik bekleyen is gorunmuyor. "
                    "Iade veya fulfillment riski bulunmamaktadir."
                ),
                db_name=self.db_path,
                audit_path=str(audit_path),
                idempotency_key="two-phase-extracted",
            )

        self.assertTrue(second_resume.success, second_resume.message)
        final_state = (second_resume.data or {}).get("state") or {}
        self.assertEqual(final_state.get("status"), "complete")
        self.assertEqual(len(label_calls), 1)
        self.assertEqual(set(label_calls[0]), selected_orders)
        self.assertEqual(label_db_names, [self.db_path])
        final_answer = str((second_resume.data or {}).get("answer") or second_resume.message)
        self.assertIn("Siparis etiketleri olusturuldu", final_answer)
        self.assertIn("Fis/cikti durumu isaretlendi", final_answer)
        self.assertIn("dogrulandi", final_answer)
        self.assertNotIn("Onay gerekiyor", final_answer)
        self.assertNotIn("kritik bekleyen is", final_answer.casefold())
        self.assertNotIn("iade veya fulfillment riski", final_answer.casefold())
        self.assertIn("yalnizca bu gorevde secilen kayitlar", final_answer)
        for order_number in selected_orders:
            self.assertIn(order_number, final_answer)
        with Session(get_engine(self.db_path)) as session:
            rows = session.exec(
                select(OrderHeader).where(
                    OrderHeader.orderNumber.in_(
                        [*sorted(selected_orders), "ORD-TASK-TWO-PHASE-UNRELATED"]
                    )
                )
            ).all()
        extracted = {row.orderNumber for row in rows if row.is_extracted}
        self.assertEqual(extracted, selected_orders)

