    def test_cancel_persisted_task_clears_pending_action_and_prevents_later_execute(self) -> None:
        now_ms = int(datetime.now(TZ_GMT3).timestamp() * 1000)
        self._insert_order(
            "ORD-TASK-CANCEL-1",
            now_ms,
            package_id=998,
            status="ReadyToShip",
            cargo_tracking_number="TRK-TASK-CANCEL-1",
            cargo_provider_name="Trendyol Express",
        )
        with tempfile.TemporaryDirectory() as temp_dir:
            result = run_agent_task(
                "Kargoya hazir siparisleri yazdir",
                db_name=self.db_path,
                persist=True,
                task_store_root=temp_dir,
            )
            state = (result.data or {}).get("state") or {}
            self.assertEqual(state.get("status"), "pending_approval")
            session_id = state.get("session_id")

            cancelled = cancel_agent_task_by_id(
                session_id,
                cancelled_by="behavioral-test",
                task_store_root=temp_dir,
            )

            self.assertTrue(cancelled.success, cancelled.message)
            cancelled_state = (cancelled.data or {}).get("state") or {}
            self.assertEqual(cancelled_state.get("status"), "cancelled")
            self.assertEqual(cancelled_state.get("pending_actions"), [])
            self.assertEqual(cancelled_state.get("remaining_steps"), [])
            self.assertEqual((cancelled_state.get("action_history") or [])[-1].get("phase"), "cancel")

            resumed = resume_agent_task_by_id(
                session_id,
                approved_by="behavioral-test",
                db_name=self.db_path,
                task_store_root=temp_dir,
            )

            self.assertFalse(resumed.success)
            self.assertIn("pending action", resumed.message.casefold())

            replacement = run_agent_task(
                "Kargoya hazir siparisleri yeniden yazdirmaya hazirla",
                db_name=self.db_path,
                persist=True,
                task_store_root=temp_dir,
            )
            self.assertTrue(replacement.success, replacement.message)
            replacement_state = (replacement.data or {}).get("state") or {}
            self.assertEqual(replacement_state.get("status"), "pending_approval")
            replacement_session_id = replacement_state.get("session_id")
            replacement_action = (replacement_state.get("pending_actions") or [])[0]

            superseded = supersede_agent_task_by_id(
                replacement_session_id,
                superseded_by="behavioral-scope-revision",
                reason="all_waiting_orders_requested",
                action_id=replacement_action.get("action_id"),
                task_store_root=temp_dir,
            )

            self.assertTrue(superseded.success, superseded.message)
            superseded_state = (superseded.data or {}).get("state") or {}
            self.assertEqual(superseded_state.get("status"), "superseded")
            self.assertEqual(superseded_state.get("pending_actions"), [])
            self.assertEqual(superseded_state.get("remaining_steps"), [])
            self.assertEqual(
                (superseded_state.get("action_history") or [])[-1].get("phase"),
                "supersede",
            )
            self.assertEqual(
                (superseded_state.get("action_history") or [])[-1].get("status"),
                "superseded",
            )

            stale_resume = resume_agent_task_by_id(
                replacement_session_id,
                approved_by="behavioral-test",
                db_name=self.db_path,
                task_store_root=temp_dir,
            )
            self.assertFalse(stale_resume.success)
            self.assertIn("pending action", stale_resume.message.casefold())

    def test_completed_task_rejects_stale_approval_summary_and_restores_exact_ids(self) -> None:
        now_ms = int(datetime.now(TZ_GMT3).timestamp() * 1000)
        selected_orders = {
            "ORD-TASK-FINAL-GROUND-1",
            "ORD-TASK-FINAL-GROUND-2",
        }
        for index, order_number in enumerate(sorted(selected_orders), start=1):
            self._insert_order(
                order_number,
                now_ms + index,
                package_id=1_100 + index,
                status="ReadyToShip",
                cargo_tracking_number=f"TRK-{order_number}",
                cargo_provider_name="Trendyol Express",
            )

        history = [
            {"role": "user", "content": "Son iki siparisi getir"},
            {
                "role": "assistant",
                "content": "\n".join(
                    f"{index}. {order_number}"
                    for index, order_number in enumerate(sorted(selected_orders), start=1)
                ),
            },
        ]
        started = run_agent_task(
            "bunlari fis cikarildi olarak isaretle",
            db_name=self.db_path,
            history=history,
        )
        self.assertTrue(started.success, started.message)
        state = (started.data or {}).get("state") or {}
        self.assertEqual(state.get("status"), "pending_approval")

        stale_model_answer = (
            "**Operasyon Ozeti**\n"
            "- **Siparis:** ORD‑TASK‑FINAL‑GROUND‑1\n"
            "- **Siparis:** ORD‑TASK‑FINAL‑GROUND‑2\n"
            "- Durum: Islem onayi bekleniyor; islem henuz baslatilmadi.\n"
            "Onay verildiginde veri tabani guncellenecektir."
        )
        resumed = resume_agent_task_with_approval(
            state,
            approved_by="final-grounding-test",
            chat_client=lambda _prompt: stale_model_answer,
            db_name=self.db_path,
            idempotency_key=f"final-grounding-{now_ms}",
        )

        self.assertTrue(resumed.success, resumed.message)
        final_answer = str((resumed.data or {}).get("answer") or resumed.message)
        self.assertNotIn("bekleniyor", final_answer.casefold())
        self.assertNotIn("henuz baslatilmadi", final_answer.casefold())
        self.assertNotIn("verildiginde", final_answer.casefold())
        self.assertIn("Fis/cikti durumu isaretlendi", final_answer)
        self.assertIn("dogrulandi", final_answer)
        for order_number in selected_orders:
            self.assertIn(order_number, final_answer)
        self.assertNotIn("ORD‑TASK", final_answer)

