    def test_orders_task_runtime_ready_then_customer_refined_full_context(self) -> None:
        now_ms = int(datetime.now(TZ_GMT3).timestamp() * 1000)
        self._insert_order(
            "ORD-TASK-CONTEXT-MAHMUT",
            now_ms,
            package_id=823,
            status="ReadyToShip",
            cargo_tracking_number="TRK-TASK-CONTEXT-MAHMUT",
            cargo_provider_name="Trendyol Express",
            first_name="Mahmut",
            last_name="Sevket",
        )
        self._insert_order(
            "ORD-TASK-CONTEXT-AYSE",
            now_ms + 1_000,
            package_id=824,
            status="ReadyToShip",
            cargo_tracking_number="TRK-TASK-CONTEXT-AYSE",
            cargo_provider_name="Trendyol Express",
            first_name="Ayse",
            last_name="Yilmaz",
        )
        self._insert_order_item("ORD-TASK-CONTEXT-MAHMUT", now_ms + 2_000, product_name="Mahmut Task Context Urunu", line_id=823)
        self._insert_order_item("ORD-TASK-CONTEXT-AYSE", now_ms + 3_000, product_name="Ayse Task Context Urunu", line_id=824)

        def planner(prompt: str) -> str:
            if prompt.startswith("GoalPlan observation"):
                return json.dumps({"decision": "complete", "reason": "Bound customer context observed"})
            if prompt.startswith("Orders domain agent task plan"):
                return json.dumps(
                    {
                        "steps": [
                            {"id": "orders.ready_to_ship", "operation_id": "orders.ready_to_ship", "arguments_json": "{}", "depends_on": []},
                            {"id": "orders.full_context", "operation_id": "orders.full_context", "arguments_json": '{"query":"Mahmut"}', "depends_on": []},
                            {"id": "orders.labels.prepare", "operation_id": "labels.create_from_orders.prepare", "arguments_json": "{}", "depends_on": []},
                        ]
                    }
                )
            return '{"mode":"tool","tool":"orders.count","arguments":{"period":"today"}}'

        def chat_client(prompt: str) -> str:
            if "Kullanilan tool: orders.full_context" in prompt:
                return "Mahmut siparisinde kalem (pen) bulunmuyor."
            return ""

        result = run_agent_task(
            "Kargoya hazir siparisleri bul, Mahmut olanin kalemlerini getir",
            db_name=self.db_path,
            planner_client=planner,
            chat_client=chat_client,
        )

        self.assertTrue(result.success, result.message)
        state = (result.data or {}).get("state") or {}
        self.assertEqual(state.get("status"), "complete")
        plan = (state.get("active_entities") or {}).get("task_plan") or {}
        self.assertEqual(plan.get("step_ids"), ["orders.ready_to_ship", "orders.full_context"])
        self.assertIn("orders.labels.prepare", plan.get("rejected_step_ids") or [])
        steps = state.get("completed_steps") or []
        self.assertEqual([step.get("tool_names") for step in steps], [["orders.ready_to_ship"], ["orders.full_context"]])
        context_tool = ((steps[-1].get("result_data") or {}).get("tool_result") or {})
        contexts = context_tool.get("contexts") or []
        self.assertEqual(len(contexts), 1)
        context = contexts[0]
        self.assertEqual(((context.get("order") or {}).get("order_number")), "ORD-TASK-CONTEXT-MAHMUT")
        self.assertEqual(((context.get("items") or [])[0] or {}).get("product_name"), "Mahmut Task Context Urunu")
        answer = ((steps[-1].get("result_data") or {}).get("answer") or "")
        self.assertIn("Mahmut Task Context Urunu", answer)
        self.assertNotIn("pen", answer.casefold())
        self.assertNotIn("kalem (pen)", answer.casefold())
        self.assertFalse(any("Ayse Task Context Urunu" in str(cell) for row in contexts for cell in str(row).splitlines()))

    def test_typed_ready_list_contract_repairs_count_plan_before_execution(self) -> None:
        prompts: list[str] = []

        def planner(prompt: str) -> str:
            prompts.append(prompt)
            operation_id = (
                "orders.ready_to_ship"
                if prompt.startswith("Orders model plan semantic repair")
                else "orders.ready_to_ship_count"
            )
            return json.dumps(
                {
                    "steps": [
                        {
                            "id": "verify_ready_queue",
                            "operation_id": operation_id,
                            "arguments_json": '{"period":"all"}',
                            "depends_on": [],
                            "objective": (
                                "Kargoya hazır kuyruğu exact listeyle doğrula"
                            ),
                            "expected_evidence": [
                                "order_numbers",
                                "listed_count",
                            ],
                        }
                    ]
                }
            )

        interpretation = {
            "mode": "inspect",
            "domain": "orders",
            "intent_kind": "data_read",
            "requested_fields": ["order_number"],
            "semantic_contract": {
                "entity": "order",
                "metric": "list",
                "status_scope": "ready_to_ship",
                "record_scope": "all_matching",
                "period": "all",
                "freshness": "local_snapshot",
                "projection": ["order_number"],
                "information_source": "local_business_data",
            },
        }
        step_ids, metadata = task_runtime._orders_task_plan(
            "Bu hazır kuyruğunun gerçekten boş olduğunu exact liste sorgusuyla doğrula.",
            planner_client=planner,
            max_steps=8,
            turn_interpretation=interpretation,
        )

        self.assertEqual(step_ids, ["verify_ready_queue"])
        self.assertEqual(metadata.get("source"), "llm_direct_repaired")
        self.assertEqual(
            [
                row.get("operation_id")
                for row in metadata.get("step_specs") or []
            ],
            ["orders.ready_to_ship"],
        )
        self.assertIn(
            "typed_read_contract_operation_mismatch:orders.ready_to_ship_count",
            metadata.get("initial_plan_reason_codes") or [],
        )
        self.assertEqual(
            metadata.get("expected_typed_read_operations"),
            ["orders.ready_to_ship"],
        )
        self.assertEqual(len(prompts), 2)

