    def test_r377_count_plus_every_order_number_is_one_authoritative_ready_list(
        self,
    ) -> None:
        message = (
            "başkan yerel kayda göre şu an kargoya hazır kaç sipariş var, "
            "sayıyı ve sipariş numaralarının tamamını aynı cevapta ver; "
            "api senkronu yapma"
        )
        interpreted = task_runtime.interpret_agent_turn(
            message,
            planner_client=lambda _prompt: json.dumps(
                {
                    "mode": "inspect",
                    "domain": "orders",
                    "objective": "Kargoya hazır sayıyı ve bütün numaraları getir",
                    "intent_kind": "data_read",
                    "request_shape": "record_list",
                    "requested_fields": ["count", "order_number"],
                    "direct_output_fields": ["count", "order_number"],
                    "entity": "order",
                    # R377 provider drift: exhaustive identity projection was
                    # mislabeled as a scalar count.
                    "metric": "count",
                    "status_scope": "ready_to_ship",
                    "record_scope": "all_matching",
                    "period": "all",
                    "freshness": "local_snapshot",
                    "information_source": "local_business_data",
                    "operation_policy": "allow_new_operations",
                    "reason": "Ready count and all identities in one answer.",
                    "requires_clarification": False,
                    "clarification": "",
                },
                ensure_ascii=False,
            ),
        )

        self.assertTrue(interpreted.success, interpreted.message)
        interpretation = dict(interpreted.data or {})
        contract = dict(interpretation.get("semantic_contract") or {})
        self.assertEqual(contract.get("metric"), "list")
        self.assertEqual(contract.get("status_scope"), "ready_to_ship")
        self.assertEqual(contract.get("record_scope"), "all_matching")
        self.assertEqual(contract.get("projection"), ["count", "order_number"])
        self.assertEqual(
            semantic_contracts.expected_order_read_operations(
                contract,
                requested_fields=interpretation.get("requested_fields") or [],
            ),
            frozenset({"orders.ready_to_ship"}),
        )

        def plan_provider(prompt: str) -> str:
            # R378: even the bounded model repair repeated the scalar count.
            # The typed list contract has one canonical safe read and may be
            # lowered only after both model plans are rejected.
            operation_id = "orders.ready_to_ship_count"
            return json.dumps(
                {
                    "steps": [
                        {
                            "id": "ready_rows",
                            "operation_id": operation_id,
                            "arguments_json": '{"period":"all"}',
                            "depends_on": [],
                            "objective": "Ready count and exact identities",
                            "expected_evidence": [
                                "count",
                                "listed_count",
                                "order_numbers",
                            ],
                        }
                    ]
                }
            )

        step_ids, metadata = task_runtime._orders_task_plan(
            message,
            planner_client=plan_provider,
            max_steps=8,
            turn_interpretation=interpretation,
        )
        self.assertEqual(step_ids, ["orders.ready_to_ship"])
        self.assertEqual(metadata.get("source"), "typed_unique_read_recovery")
        self.assertTrue(metadata.get("typed_unique_read_recovery"))
        self.assertEqual(
            [
                row.get("operation_id")
                for row in metadata.get("step_specs") or []
            ],
            ["orders.ready_to_ship"],
        )

