    def test_authoritative_empty_order_list_is_a_verified_zero_cardinality_result(
        self,
    ) -> None:
        state = self._completed_response_state(
            goal=(
                "Hazır kuyruğu exact liste sorgusuyla doğrula; "
                "kayıt yoksa açıkça söyle."
            ),
            operation="orders.ready_to_ship",
            tool_result={
                "orders": [],
                "order_numbers": [],
                "listed_count": 0,
                "selected_count": 0,
                "ready_to_ship": 0,
                "truncated": False,
                "period": "all",
            },
            authoritative_answer=(
                "Kargoya hazır sipariş kuyruğu boş; "
                "sorgu kapsamında 0 sipariş bulundu."
            ),
            requested_fields=["order_number", "status"],
        )
        state.active_entities["turn_interpretation"]["semantic_contract"] = {
            "entity": "order",
            "metric": "list",
            "status_scope": "ready_to_ship",
            "record_scope": "all_matching",
            "period": "all",
            "projection": ["order_number", "status"],
        }

        answer = response_verifier.project_fallback_response(
            state,
            "Liste doğrulandı.",
        )
        verified = response_verifier.verify_response_projection(
            answer,
            state,
            source="verified_fallback",
        )

        self.assertIn("kuyrugu bos", task_runtime._normalized(answer))
        self.assertIn("0 siparis", task_runtime._normalized(answer))
        self.assertTrue(verified.success, verified.data)
        missing_zero = response_verifier.verify_response_projection(
            "Sipariş satırları authoritative sonuç içinde bulunamadı.",
            state,
            source="model_candidate",
        )
        self.assertFalse(missing_zero.success)
        self.assertIn(
            "empty_order_list_projection_missing",
            (
                (missing_zero.data or {}).get("response_verification") or {}
            ).get("reason_codes")
            or [],
        )
        state.active_entities["turn_interpretation"]["requested_fields"] = [
            "order_number"
        ]
        state.active_entities["turn_interpretation"]["semantic_contract"][
            "projection"
        ] = ["order_number"]
        identifier_only_answer = response_verifier.project_fallback_response(
            state,
            "Sipariş numarası authoritative sonuç içinde bulunamadı.",
        )
        identifier_only_verified = (
            response_verifier.verify_response_projection(
                identifier_only_answer,
                state,
                source="verified_fallback",
            )
        )

        self.assertIn(
            "kuyrugu bos",
            task_runtime._normalized(identifier_only_answer),
        )
        self.assertIn(
            "0 siparis",
            task_runtime._normalized(identifier_only_answer),
        )
        self.assertTrue(
            identifier_only_verified.success,
            identifier_only_verified.data,
        )

