    def test_empty_current_list_rejects_identifier_from_stale_active_selection(
        self,
    ) -> None:
        state = self._completed_response_state(
            goal="Bunlari listele.",
            operation="orders.ready_to_ship",
            tool_result={
                "orders": [],
                "order_numbers": [],
                "listed_count": 0,
                "selected_count": 0,
                "ready_to_ship": 0,
                "truncated": False,
                "period": "all",
            },
            authoritative_answer=(
                "Kargoya hazir siparis kuyrugu bos; "
                "sorgu kapsaminda 0 siparis bulundu."
            ),
            requested_fields=["order_number", "status"],
        )
        state.active_entities["turn_interpretation"]["semantic_contract"] = {
            "entity": "order",
            "metric": "list",
            "status_scope": "ready_to_ship",
            "record_scope": "all_matching",
            "period": "all",
            "projection": ["order_number", "status"],
        }
        stale_selection = SelectionSnapshot.from_order_numbers(
            ["ORD-STALE-001"],
            source_tool="orders.full_context",
        )
        state.add_selection_snapshot(stale_selection)
        stale_observation = Observation.create(
            domain="orders",
            operation_name="orders.full_context",
            success=True,
            selection_id=stale_selection.selection_id,
            refs=list(stale_selection.refs),
            facts={"message": "Siparis ORD-STALE-001 tam baglami hazir."},
            source="orders.full_context",
        )
        state.add_observation(stale_observation)
        current_observation = Observation.create(
            domain="orders",
            operation_name="orders.ready_to_ship",
            success=True,
            aggregates={"listed_count": 0},
            facts={"message": "Kargoya hazir 0 siparis var."},
            source="orders.ready_to_ship",
        )
        state.add_observation(current_observation)
        state.completed_steps[0].observation_ids = [
            current_observation.observation_id
        ]

        stale_answer = (
            "Sorguladiginiz ORD-STALE-001 numarali siparis icin "
            "kargoya hazir siparis kuyrugu bos; sorgu kapsaminda 0 siparis var."
        )
        rejected = response_verifier.verify_response_projection(
            stale_answer,
            state,
            source="model_repair_candidate",
        )
        responses = iter((stale_answer, stale_answer))
        final_answer = task_runtime._finalize_task_answer(
            state,
            chat_client=lambda _prompt: next(responses),
        )
        projection = response_verifier.response_evidence_projection(state)

        self.assertFalse(rejected.success)
        self.assertIn(
            "ungrounded_identifier:ORD-STALE-001",
            (
                (rejected.data or {}).get("response_verification") or {}
            ).get("reason_codes")
            or [],
        )
        self.assertNotIn("ORD-STALE-001", final_answer)
        self.assertIn("kuyrugu bos", task_runtime._normalized(final_answer))
        self.assertEqual(projection.get("order_numbers"), [])

