    def test_real_cloud_task_runtime_operation_overview_returns_final_answer(self) -> None:
        today = datetime.now(TZ_GMT3).date()
        today_start = int(datetime.combine(today, datetime.min.time(), tzinfo=TZ_GMT3).timestamp() * 1000)
        self._insert_order(
            "ORD-LIVE-TASK-OVERVIEW-READY",
            today_start + 1_000,
            package_id=9581,
            status="ReadyToShip",
            cargo_tracking_number="TRK-LIVE-TASK-OVERVIEW-READY",
            cargo_provider_name="Trendyol Express",
        )
        self._insert_order(
            "ORD-LIVE-TASK-OVERVIEW-RISK",
            today_start + 2_000,
            package_id=9582,
            status="ReadyToShip",
            cargo_tracking_number="",
            cargo_provider_name="",
        )
        self._insert_waiting_return("CLAIM-LIVE-TASK-OVERVIEW-WAIT", "ORD-LIVE-TASK-OVERVIEW-RET", today_start + 3_000)

        client = self._client()
        provider_label = _safe_provider_label(self._provider_record, self._provider_source)
        result = run_agent_task(
            "Bugunku siparis operasyonunu toparla",
            planner_client=client,
            chat_client=client,
            db_name=self.db_path,
        )

        self.assertGreater(len(client.prompts), 0, provider_label)
        self.assertEqual(client.errors, [], provider_label + "\n" + "\n".join(client.errors))
        self.assertTrue(result.success, result.message)
        data = result.data or {}
        state = data.get("state") or {}
        self.assertEqual(state.get("status"), "complete")
        plan = (state.get("active_entities") or {}).get("task_plan") or {}
        self.assertEqual(plan.get("step_ids"), ["orders.ready_to_ship", "orders.fulfillment_risk", "returns.waiting.list"])
        steps = state.get("completed_steps") or []
        self.assertEqual([step.get("status") for step in steps], ["completed", "completed", "completed"])
        tool_names = [tool for step in steps for tool in (step.get("tool_names") or [])]
        self.assertIn("orders.ready_to_ship", tool_names)
        self.assertIn("orders.fulfillment_risk", tool_names)
        self.assertIn("returns.query", tool_names)
        final_answer = data.get("answer") or (state.get("active_entities") or {}).get("final_answer") or ""
        self.assertTrue(final_answer.strip(), data)
        self.assertNotIn("Agent task runtime tamamlandi", final_answer)
        normalized_answer = final_answer.casefold()
        self.assertTrue(any(token in normalized_answer for token in ("kargo", "hazir", "risk", "iade", "onay")), final_answer)
        self.assertNotIn("kritik bekleyen is gorunmuyor", normalized_answer)
        self.assertNotIn("kritik bekleyen iş görünmüyor", normalized_answer)
        self.assertTrue(
            "iade" in normalized_answer
            and any(token in normalized_answer for token in ("aksiyon", "onay", "bekle", "sonuclandir", "sonuçlandır")),
            final_answer,
        )
        self.assertTrue(any(prompt.startswith("Orders agent task final cevabi") for prompt in client.prompts), client.prompts)

        transcript = {
            "provider": provider_label,
            "plan": plan,
            "completed_steps": [
                {"prompt": step.get("prompt"), "tool_names": step.get("tool_names"), "answer": (step.get("result_data") or {}).get("answer")}
                for step in steps
            ],
            "final_answer": final_answer,
            "llm_responses": client.responses,
        }
        print("\nLIVE_OPERATION_OVERVIEW_TASK_RUNTIME_TRANSCRIPT " + provider_label)
        print(json.dumps(transcript, ensure_ascii=True, indent=2))
        artifact_path = _write_live_artifact(
            "live-task-runtime-operation-overview",
            provider_label=provider_label,
            transcript=[transcript],
        )
        if artifact_path is not None:
            print(f"LIVE_OPERATION_OVERVIEW_TASK_RUNTIME_ARTIFACT {artifact_path}")

