    def test_r365_broad_derived_summary_cannot_drop_explicit_status_distribution(
        self,
    ) -> None:
        message = (
            "Dış API'ye çıkmadan yalnız mevcut lokal sipariş kaydını kullan: "
            "toplam sipariş sayısını, durumlara göre dağılımı, toplam ciroyu "
            "ve sipariş başına ortalama ciroyu hesaplayıp birlikte açıkla."
        )
        interpreted = task_runtime.interpret_agent_turn(
            message,
            planner_client=lambda _prompt: json.dumps(
                {
                    "mode": "inspect",
                    "domain": "orders",
                    "objective": "Lokal sipariş özetini ve ortalamayı açıkla",
                    "intent_kind": "data_read",
                    "request_shape": "broad_analysis",
                    "requested_fields": [
                        "count",
                        "amount",
                        "calculation",
                        "currency",
                    ],
                    "direct_output_fields": ["count", "amount"],
                    "entity": "order",
                    "metric": "derived",
                    "status_scope": "all",
                    "record_scope": "all_matching",
                    "period": "all",
                    "freshness": "local_snapshot",
                    "information_source": "local_business_data",
                    "operation_policy": "allow_new_operations",
                    "calculation_count": 1,
                    "calculation_grouping": "single_result",
                    "derived_calculation": {
                        "operator": "divide",
                        "operands": [
                            {"ref": "orders.revenue_total"},
                            {"ref": "orders.total_count"},
                        ],
                        "result_kind": "amount_per_order",
                        "precision": 2,
                        "show_work": True,
                    },
                    "reason": "Provider status projection'ını eksik bıraktı",
                    "requires_clarification": False,
                    "clarification": "",
                },
                ensure_ascii=False,
            ),
        )

        self.assertTrue(interpreted.success, interpreted.message)
        data = dict(interpreted.data or {})
        self.assertIn("status", data.get("requested_fields") or [])
        contract = dict(data.get("semantic_contract") or {})
        self.assertIn("status", contract.get("direct_projection") or [])
        self.assertIn(
            ORDER_STATUS_DISTRIBUTION_METRIC,
            contract.get("metric_requirements") or [],
        )

        state = AgentSessionState(
            goal=message,
            active_domain="orders",
            status="complete",
        )
        state.active_entities["turn_interpretation"] = data
        state.completed_steps = [
            AgentTaskStep(
                index=1,
                step_id="summary",
                prompt="Sipariş özeti",
                operation_domain="orders",
                status="completed",
                tool_names=["orders.summary"],
                result_data={
                    "tool_result": {
                        "tool": "orders.summary",
                        "total_orders": 3120,
                        "status_counts": {
                            "Cancelled": 110,
                            "Delivered": 2958,
                            "UnDeliveredAndReturned": 52,
                        },
                        "estimated_revenue": 503546.47,
                        "currency": "TRY",
                    }
                },
            )
        ]
        wrong = response_verifier.verify_response_projection(
            "Toplam 3120 sipariş var. Toplam ciro 503546.47 TRY. "
            "Sipariş başına ortalama ciro: 503546.47 TRY / 3120 sipariş "
            "= 161.39 TRY/sipariş.",
            state,
        )

        self.assertFalse(wrong.success)
        reasons = (
            (wrong.data or {}).get("response_verification") or {}
        ).get("reason_codes") or []
        self.assertTrue(any("status" in str(reason) for reason in reasons), reasons)

    def test_r366_policy_security_difference_never_requires_arithmetic_formula(
        self,
    ) -> None:
        message = (
            "Siparişleri yalnız okumakla onları değiştirmek arasındaki güvenlik "
            "farkı ne, hangi durumda benden onay alırsın ve sonucu nasıl "
            "doğrularsın? Şu anda veri çekme ya da işlem yapma."
        )
        responses = [
            {
                "mode": "explain",
                "domain": "orders",
                "objective": "Okuma ve değişiklik güvenlik politikasını açıkla",
                "intent_kind": "policy_explanation",
                "request_shape": "policy_explanation",
                "explanation_topics": ["approval", "verification"],
                "requested_fields": ["status"],
                "direct_output_fields": [],
                "entity": "order",
                "metric": "none",
                "status_scope": "all",
                "record_scope": "all_matching",
                "period": "all",
                "freshness": "unspecified",
                "information_source": "unspecified",
                "operation_policy": "existing_observations_only",
                "calculation_count": 0,
                "calculation_grouping": "none",
                "derived_calculation": {},
                "derived_calculations": [],
                "reason": "Güvenlik politikası açıklaması",
                "requires_clarification": False,
                "clarification": "",
            },
            {"explanation_topics": ["approval", "verification"]},
        ]

        responses.insert(1, dict(responses[0], requested_fields=[]))

        def planner(_prompt: str) -> str:
            return json.dumps(responses.pop(0), ensure_ascii=False)

        result = task_runtime.interpret_agent_turn(
            message,
            planner_client=planner,
        )

        self.assertTrue(result.success, f"{result.message} | {result.data}")
        data = dict(result.data or {})
        self.assertEqual(data.get("mode"), "explain")
        self.assertEqual(data.get("intent_kind"), "policy_explanation")
        self.assertEqual(data.get("request_shape"), "policy_explanation")
        self.assertEqual(data.get("requested_fields"), [])
        self.assertNotIn("derived_calculation_repair", data)
        self.assertIn("policy_business_projection_conflict", data["turn_interpretation_repair"]["initial_error"])
        self.assertEqual(responses, [])

    def test_r369_capability_policy_candidate_is_checked_against_trusted_topics(
        self,
    ) -> None:
        policy_context = {
            "source": "canonical_runtime_policy",
            "domain": "orders",
            "topics": ["approval", "verification"],
            "assertions": [
                {
                    "id": "read",
                    "topic": "approval",
                    "fact": "Canonical R0 read operasyonları salt okunurdur ve kullanıcı onayı gerektirmez.",
                },
                {
                    "id": "effect",
                    "topic": "approval",
                    "fact": "Etki taşıyan operasyonlar prepare edilir; açık onay olmadan execute edilmez.",
                },
                {
                    "id": "verify",
                    "topic": "verification",
                    "fact": "Execute sonucu canonical verify/read-back ile doğrulanır.",
                },
            ],
        }
        candidate = (
            "Kargoya hazır siparişleri sayma ve listeleme gibi doğrudan "
            "okunabilir R0 işlemleri salt okunurdur, onay gerektirmez. "
            "Dosya, DB veya dış sistem etkisi olan işler önce prepare ile "
            "hazırlanır; açık onay gelmeden execute edilip çalıştırılmaz. "
            "Onaylı execute sonrası sonuç canonical verify/read-back ile doğrulanır."
        )

        accepted = task_runtime.run_model_conversation_turn(
            "Bunların hangileri okunur, hangileri onay ister?",
            mode="explain",
            objective="Read ve effect capability'leri ayır",
            chat_client=lambda _prompt: candidate,
            policy_context=policy_context,
        )

        self.assertTrue(accepted.success, accepted.message)
        accepted_data = dict(accepted.data or {})
        self.assertEqual(accepted_data.get("answer"), candidate)
        self.assertTrue(
            (accepted_data.get("response_synthesis") or {}).get(
                "candidate_accepted"
            )
        )

        repaired = task_runtime.run_model_conversation_turn(
            "Bunların hangileri okunur, hangileri onay ister?",
            mode="explain",
            objective="Read ve effect capability'leri ayır",
            chat_client=lambda _prompt: "Bunların hepsi yapılabilir.",
            policy_context=policy_context,
        )

        self.assertTrue(repaired.success, repaired.message)
        repaired_data = dict(repaired.data or {})
        repaired_answer = str(repaired_data.get("answer") or "")
        self.assertIn("R0 read operasyonları salt okunurdur", repaired_answer)
        self.assertIn("açık onay olmadan execute edilmez", repaired_answer)
        self.assertIn("verify/read-back", repaired_answer)
        self.assertIn(
            "incomplete_policy_candidate_to_grounded_projection",
            repaired_data.get("response_semantic_corrections") or [],
        )
        self.assertFalse(
            (repaired_data.get("response_synthesis") or {}).get(
                "candidate_accepted"
            )
        )

    def test_r405_orders_sync_cannot_be_described_as_approval_free_read(
        self,
    ) -> None:
        policy_context = {
            "source": "canonical_runtime_policy",
            "domain": "orders",
            "topics": ["freshness", "approval"],
            "assertions": [
                {
                    "id": "orders.explicit_sync_refresh",
                    "topic": "freshness",
                    "fact": "Tazelik için ayrı senkronizasyon hazırlanır ve read-back sonrasında yeni snapshot kullanılır.",
                },
                {
                    "id": "orders.marketplace_sync_is_not_r0_read",
                    "topic": "freshness",
                    "fact": "Pazaryeri API senkronizasyonu canonical R0 okuma değildir; kalıcı DB etkisi taşır.",
                },
                {
                    "id": "orders.marketplace_sync_requires_approval",
                    "topic": "approval",
                    "fact": "Sipariş senkronizasyonu prepare edilir; açık onay olmadan execute edilmez ve DB read-back ile doğrulanır.",
                },
                {
                    "id": "runtime.r0_reads_need_no_approval",
                    "topic": "approval",
                    "fact": "Canonical R0 yerel snapshot okumaları salt okunurdur ve onay gerektirmez.",
                },
                {
                    "id": "runtime.effects_prepare_then_confirm",
                    "topic": "approval",
                    "fact": "DB etkisi taşıyan operasyonlar prepare edilir; açık onay olmadan execute edilmez.",
                },
            ],
        }
        bad_candidate = (
            "Yerel snapshot son kalıcı kayıttır; yeni API senkronizasyonu olmadan "
            "pazaryerinin anlık durumunu garanti etmez. Salt okunur sorgular "
            "(veri çekme, listeleme) onay gerektirmez. DB etkili işler prepare "
            "edilir ve açık onaydan sonra execute edilir."
        )

        repaired = task_runtime.run_model_conversation_turn(
            "Veri ne kadar güncel ve ne zaman onay istersin?",
            mode="explain",
            objective="Tazelik ve onay politikasını açıkla",
            chat_client=lambda _prompt: bad_candidate,
            policy_context=policy_context,
        )

        self.assertTrue(repaired.success, repaired.message)
        data = dict(repaired.data or {})
        self.assertNotEqual(data.get("answer"), bad_candidate)
        self.assertIn(
            "Pazaryeri API senkronizasyonu canonical R0 okuma değildir",
            str(data.get("answer") or ""),
        )
        self.assertIn(
            "policy_marketplace_sync_misclassified_as_approval_free_read",
            (data.get("response_synthesis") or {}).get(
                "candidate_projection_reason_codes"
            )
            or [],
        )
        self.assertFalse(
            (data.get("response_synthesis") or {}).get("candidate_accepted")
        )

        good_candidate = (
            "Yerel snapshot okumaları onaysızdır. Pazaryeri API'sinden sipariş "
            "çekip snapshot'ı yenilemek DB etkili bir senkronizasyondur; önce "
            "prepare edilir, açık onay olmadan execute edilmez ve read-back ile doğrulanır."
        )
        accepted = task_runtime.run_model_conversation_turn(
            "Veri ne kadar güncel ve ne zaman onay istersin?",
            mode="explain",
            objective="Tazelik ve onay politikasını açıkla",
            chat_client=lambda _prompt: good_candidate,
            policy_context=policy_context,
        )

        self.assertTrue(accepted.success, accepted.message)
        accepted_data = dict(accepted.data or {})
        self.assertEqual(accepted_data.get("answer"), good_candidate)
        self.assertTrue(
            (accepted_data.get("response_synthesis") or {}).get(
                "candidate_accepted"
            )
        )

