    def test_r421_per_target_status_calculations_bind_each_visible_result_label(
        self,
    ) -> None:
        state = AgentSessionState(
            goal="Her durumun toplam içindeki yüzdesi",
            active_domain="orders",
            status="complete",
        )
        state.active_entities["turn_interpretation"] = {
            "requested_fields": ["count", "calculation", "ratio"],
            "semantic_contract": {
                "entity": "order",
                "metric": "derived",
                "projection": ["count", "calculation", "ratio"],
                "direct_projection": ["count"],
                "calculation_grouping": "per_target",
                "metric_requirements": [
                    ORDER_TOTAL_COUNT_METRIC,
                    ORDER_STATUS_DISTRIBUTION_METRIC,
                ],
                "derived_calculations": [
                    {
                        "operator": "percentage",
                        "operands": [
                            {"ref": "orders.status_count", "member": member},
                            {"ref": "orders.total_count"},
                        ],
                        "result_kind": "percentage",
                        "precision": 2,
                        "show_work": True,
                    }
                    for member in (
                        "Cancelled",
                        "Delivered",
                        "UnDeliveredAndReturned",
                    )
                ],
            },
        }
        state.completed_steps = [
            AgentTaskStep(
                index=1,
                step_id="summary",
                prompt="Sipariş özeti",
                operation_domain="orders",
                status="completed",
                tool_names=["orders.summary"],
                result_data={
                    "tool_result": {
                        "tool": "orders.summary",
                        "total_orders": 3120,
                        "status_counts": {
                            "Cancelled": 110,
                            "Delivered": 2958,
                            "UnDeliveredAndReturned": 52,
                        },
                    }
                },
            )
        ]

        calculations = response_verifier.verified_derived_calculations(state)
        self.assertEqual(
            [row.get("result_member") for row in calculations],
            ["Cancelled", "Delivered", "UnDeliveredAndReturned"],
        )
        projected = response_verifier._derived_calculation_projection(state)
        self.assertIn("Cancelled durumu icin oran", projected)
        self.assertIn("Delivered durumu icin oran", projected)
        self.assertIn("UnDeliveredAndReturned durumu icin oran", projected)

        unlabeled = response_verifier.verify_response_projection(
            "Toplam 3120 siparis var.\n"
            "110 / 3120 × 100 = 3.53 %.\n"
            "2958 / 3120 × 100 = 94.81 %.\n"
            "52 / 3120 × 100 = 1.67 %.",
            state,
        )
        self.assertFalse(unlabeled.success)
        self.assertTrue(
            any(
                str(reason).startswith(
                    "derived_calculation_member_projection_missing"
                )
                for reason in (
                    (unlabeled.data or {}).get("response_verification") or {}
                ).get("reason_codes")
                or []
            )
        )

        labeled = response_verifier.verify_response_projection(
            "Toplam 3120 siparis var.\n"
            "Cancelled: 110 / 3120 × 100 = 3.53 %.\n"
            "Delivered: 2958 / 3120 × 100 = 94.81 %.\n"
            "UnDeliveredAndReturned: 52 / 3120 × 100 = 1.67 %.",
            state,
        )
        self.assertTrue(labeled.success, labeled.data)

