    def test_r430_missing_comparison_repairs_only_relation(self) -> None:
        message = (
            "Aynı dağılımı kullanıp yeni veri okuma: üç durumun yüzdesini "
            "ikişer ondalıkla ayrı ayrı hesapla, sonra görünen bu üç "
            "yüzdeyi topla ve 100'den fark varsa nedenini söyle."
        )
        prior = AgentSessionState(
            goal="Sipariş durum dağılımını getir",
            active_domain="orders",
            status="complete",
        )
        prior.completed_steps = [
            AgentTaskStep(
                index=1,
                step_id="summary",
                prompt="Sipariş özeti",
                operation_domain="orders",
                status="completed",
                tool_names=["orders.summary"],
                result_data={
                    "tool_result": {
                        "tool": "orders.summary",
                        "total_orders": 3120,
                        "status_counts": {
                            "Cancelled": 110,
                            "Delivered": 2958,
                            "UnDeliveredAndReturned": 52,
                        },
                    }
                },
            )
        ]
        percentages = [
            {
                "operator": "divide",
                "operands": [
                    {
                        "ref": "orders.status_count",
                        "member": member,
                    },
                    {"ref": "orders.total_count"},
                ],
                "result_kind": "percentage",
                "precision": 2,
                "show_work": True,
            }
            for member in (
                "Cancelled",
                "Delivered",
                "UnDeliveredAndReturned",
            )
        ]
        initial_payload = {
            "mode": "inspect",
            "domain": "orders",
            "objective": "Üç yüzdeyi hesapla, topla ve 100 ile karşılaştır",
            "intent_kind": "data_read",
            "request_shape": "focused_analysis",
            "requested_fields": ["calculation", "ratio"],
            "direct_output_fields": [],
            "entity": "order",
            "metric": "derived",
            "status_scope": "all",
            "record_scope": "all_matching",
            "period": "all",
            "freshness": "local_snapshot",
            "information_source": "local_business_data",
            "operation_policy": "existing_observations_only",
            "calculation_count": 4,
            "calculation_grouping": "sequential_results",
            "status_members": [
                "Cancelled",
                "Delivered",
                "UnDeliveredAndReturned",
            ],
            "derived_calculations": [
                *percentages,
                {
                    "operator": "add",
                    "operands": [
                        {"ref": "derived.current", "index": 0},
                        {"ref": "derived.current", "index": 1},
                        {"ref": "derived.current", "index": 2},
                    ],
                    "result_kind": "percentage",
                    "precision": 2,
                    "show_work": True,
                },
            ],
            "reason": "Prior observation üzerinde dört bağlı hesap.",
            "requires_clarification": False,
            "clarification": "",
        }
        responses = iter(
            [
                json.dumps(initial_payload, ensure_ascii=False),
                json.dumps(
                    {
                        "formula_index": 3,
                        "comparison": {
                            "operator": "equal",
                            "operand": {"ref": "literal", "value": 100},
                            "include_difference": True,
                        },
                    },
                    ensure_ascii=False,
                ),
            ]
        )
        interpreted = task_runtime.interpret_agent_turn(
            message,
            planner_client=lambda _prompt, **_kwargs: next(responses),
            session_state=prior,
        )

        self.assertTrue(interpreted.success, interpreted.message)
        interpretation = dict(interpreted.data or {})
        self.assertEqual(
            interpretation.get("decision_path"),
            "typed_model_turn_interpretation_comparison_repaired",
        )
        self.assertNotIn("derived_calculation_repair", interpretation)
        self.assertTrue(
            dict(
                interpretation.get("derived_comparison_repair") or {}
            ).get("applied")
        )
        contract = dict(interpretation.get("semantic_contract") or {})
        calculations = list(contract.get("derived_calculations") or [])
        self.assertEqual(len(calculations), 4, calculations)
        self.assertEqual(
            [row.get("operator") for row in calculations[:3]],
            ["divide", "divide", "divide"],
        )
        self.assertEqual(
            calculations[3].get("comparison"),
            {
                "operator": "equal",
                "operand": {
                    "ref": "literal",
                    "value": "100",
                    "source": "current_user_message",
                },
                "include_difference": True,
            },
        )

        prior.active_entities["turn_interpretation"] = interpretation
        answer = response_verifier.project_fallback_response(prior, "")
        self.assertIn("Cancelled durumu icin oran", answer)
        self.assertIn("Delivered durumu icin oran", answer)
        self.assertIn("UnDeliveredAndReturned durumu icin oran", answer)
        self.assertIn("100.01", answer)
        self.assertIn("0.01", answer)
        verified = response_verifier.verify_response_projection(
            answer,
            prior,
        )
        self.assertTrue(verified.success, verified.data)

