    def test_r435_coherent_tracking_projection_is_not_reopened(self) -> None:
        interpretation = {
            "mode": "inspect",
            "domain": "orders",
            "objective": "İkinci siparişin kargo ve takip bilgisini getir",
            "requested_fields": [
                "item",
                "sku",
                "quantity",
                "cargo",
                "tracking_number",
            ],
            "semantic_contract": {
                "entity": "order",
                "metric": "detail",
                "record_scope": "active_selection",
                "projection": [
                    "item",
                    "sku",
                    "quantity",
                    "cargo",
                    "tracking_number",
                ],
            },
            "planner_invoked": True,
            "valid": True,
        }
        plan_meta = {
            "source": "llm_direct",
            "planner_invoked": True,
            "step_specs": [
                {
                    "operation_id": "orders.full_context",
                    "objective": "Seçili sipariş detayını getir",
                    "expected_evidence": [
                        "items",
                        "sku",
                        "quantity",
                        "cargo",
                        "tracking_number",
                    ],
                }
            ],
        }
        planner_calls: list[str] = []

        reconciled, meta = (
            task_runtime._reconcile_orders_projection_contract(
                "İkinci siparişin ürün, SKU, adet, kargo ve takip numarasını getir",
                interpretation=interpretation,
                plan_meta=plan_meta,
                planner_client=lambda prompt, **_kwargs: (
                    planner_calls.append(prompt) or "{}"
                ),
            )
        )

        self.assertEqual(planner_calls, [])
        self.assertTrue(meta.get("projection_contract_coherent"))
        self.assertFalse(meta.get("projection_contract_repair_invoked"))
        self.assertIn(
            "tracking_number",
            reconciled.get("requested_fields") or [],
        )
        self.assertIn(
            "tracking_number",
            (reconciled.get("semantic_contract") or {}).get("projection")
            or [],
        )

