    def test_r448_status_complement_chain_drops_unrequested_comparison_and_runs(
        self,
    ) -> None:
        message = (
            "Bu tabloya gore Delivered disindaki iki durumun toplamini bul; "
            "Delivered ile adet farkini ve bu iki durum toplaminin butun "
            "siparisler icindeki yuzdesini hesapla. Yeni business tool calistirma."
        )
        state = AgentSessionState(
            goal="Siparislerin genel tablosunu goster",
            active_domain="orders",
            status="complete",
        )
        state.completed_steps = [
            AgentTaskStep(
                index=1,
                step_id="summary",
                prompt=state.goal,
                operation_domain="orders",
                status="completed",
                tool_names=["orders.summary"],
                result_data={
                    "tool_result": {
                        "tool": "orders.summary",
                        "total_orders": 3120,
                        "status_counts": {
                            "Cancelled": 110,
                            "Delivered": 2958,
                            "UnDeliveredAndReturned": 52,
                        },
                    }
                },
            )
        ]
        model_payload = {
            "mode": "inspect",
            "domain": "orders",
            "objective": message,
            "intent_kind": "data_read",
            "request_shape": "focused_analysis",
            "requested_fields": ["calculation", "count", "ratio"],
            "direct_output_fields": [],
            "entity": "order",
            "metric": "derived",
            "status_scope": "all",
            "record_scope": "all_matching",
            "period": "all",
            "freshness": "local_snapshot",
            "information_source": "local_business_data",
            "operation_policy": "allow_new_operations",
            "calculation_count": 3,
            "calculation_grouping": "sequential_results",
            "derived_calculations": [
                {
                    "operator": "add",
                    "operands": [
                        {
                            "ref": "orders.status_count",
                            "members": [
                                "Cancelled",
                                "UnDeliveredAndReturned",
                            ],
                        }
                    ],
                    "result_kind": "count",
                    "precision": 0,
                    "show_work": True,
                },
                {
                    "operator": "subtract",
                    "operands": [
                        {
                            "ref": "orders.status_count",
                            "member": "Delivered",
                        },
                        {"ref": "derived.current", "index": 0},
                    ],
                    "result_kind": "count",
                    "precision": 0,
                    "show_work": True,
                    "comparison": {
                        "operator": "not_equal",
                        "operand": {"ref": "literal", "value": 0},
                    },
                },
                {
                    "operator": "percentage",
                    "operands": [
                        {"ref": "derived.current", "index": 0},
                        {"ref": "orders.total_count"},
                    ],
                    "result_kind": "percentage",
                    "precision": 2,
                    "show_work": True,
                },
            ],
            "reason": "Onceki authoritative status dagilimindan uc bagli hesap",
            "requires_clarification": False,
            "clarification": "",
        }
        prompts: list[str] = []

        def planner(prompt: str, **_kwargs: object) -> str:
            prompts.append(prompt)
            return json.dumps(model_payload, ensure_ascii=False)

        interpreted = task_runtime.interpret_agent_turn(
            message,
            planner_client=planner,
            session_state=state,
        )

        self.assertTrue(interpreted.success, interpreted.data)
        self.assertEqual(len(prompts), 1)
        interpretation = dict(interpreted.data or {})
        self.assertIn(
            "unrequested_derived_comparison_removed",
            interpretation.get("semantic_corrections") or [],
        )
        self.assertNotIn("derived_calculation_repair", interpretation)
        state.active_entities["turn_interpretation"] = interpretation

        projected = task_runtime.run_existing_observation_read_turn(
            message,
            interpretation=interpretation,
            session_state=state,
        )

        self.assertTrue(projected.success, projected.data)
        answer = str((projected.data or {}).get("answer") or "")
        self.assertIn("110 siparis + 52 siparis = 162 adet", answer)
        self.assertIn("2958 siparis - 162 adet = 2796 adet", answer)
        self.assertIn("162 adet / 3120 siparis", answer)
        self.assertIn("5.19 %", answer)
        self.assertEqual((projected.data or {}).get("tool_calls"), [])


    def test_r450_r452_model_comparison_permission_and_chain_completeness(
        self,
    ) -> None:
        cases = [
            (
                "Yeni veri çekmeden az önceki dağılımı kullan: önce Cancelled ile "
                "UnDeliveredAndReturned adetlerini topla. Sonra bu ara toplamı "
                "Delivered adedinden çıkar. Son olarak aynı ara toplamın toplam "
                "siparişler içindeki yüzdesini iki ondalıkla hesapla. Üç hesabı "
                "işlem adımlarıyla göster; başka bir karşılaştırma ekleme.",
                "prohibited",
            ),
            (
                "Mevcut kanıtla Cancelled ve UnDeliveredAndReturned toplamını, "
                "Delivered adedinden bu toplam çıkarılınca kalanı ve bu toplamın "
                "bütün siparişlere yüzdesini hesapla. Yeni sorgu yok. Sonuçlar "
                "hakkında eşitlik veya tutarlılık kararı istemiyorum.",
                "prohibited",
            ),
            (
                "Using only previous observations, add Cancelled and "
                "UnDeliveredAndReturned counts, subtract that subtotal from "
                "Delivered, and calculate its percentage of all orders. "
                "Do not compare the results with previous totals.",
                "prohibited",
            ),
            (
                "Önceki dağılımdan Cancelled ve UnDeliveredAndReturned adetlerini "
                "topla, Delivered adedinden bu ara toplamı çıkar ve aynı toplamın "
                "bütün siparişler içindeki yüzdesini hesapla. Yeni sorgu yok.",
                "not_requested",
            ),
            (
                "Önceki dağılımdan Cancelled ve UnDeliveredAndReturned adetlerini "
                "topla, Delivered adedinden bu ara toplamı çıkar ve aynı toplamın "
                "bütün siparişler içindeki yüzdesini hesapla. Yeni sorgu yok. "
                "İkinci sonuç 0 eşiğini aşıyor mu?",
                "required",
            ),
        ]
        executions = [(message, policy, False) for message, policy in cases]
        for repair_kind in ("invalid", "missing", "missing_count_one", "short_repair"):
            executions.append((*cases[0], repair_kind))
        for message, policy, repair_formula in executions:
            with self.subTest(message=message, policy=policy, repair_formula=repair_formula):
                state = AgentSessionState(
                    goal="Stage siparişlerinin durum dağılımı",
                    active_domain="orders",
                    status="complete",
                )
                state.completed_steps = [
                    AgentTaskStep(
                        index=1,
                        step_id="summary",
                        prompt=state.goal,
                        operation_domain="orders",
                        status="completed",
                        tool_names=["orders.summary"],
                        result_data={"tool_result": {
                            "tool": "orders.summary",
                            "total_orders": 570,
                            "status_counts": {
                                "Cancelled": 86, "UnDeliveredAndReturned": 13,
                                "Delivered": 25, "Picking": 238, "ReadyToShip": 48,
                                "Invoiced": 39, "Shipped": 118,
                                "AtCollectionPoint": 1, "UnDelivered": 2,
                            },
                        }},
                    )
                ]
                formulas = [
                    {"operator": "add", "operands": [
                        {"ref": "orders.status_count", "member": "Cancelled"},
                        {"ref": "orders.status_count", "member": "UnDeliveredAndReturned"},
                    ], "result_kind": "count", "precision": 0, "show_work": True},
                    {"operator": "subtract", "operands": [
                        {"ref": "orders.status_count", "member": "Delivered"},
                        {"ref": "derived.current", "index": 0},
                    ], "result_kind": "count", "precision": 0, "show_work": True,
                     "comparison": {"operator": "greater_than", "operand": {
                         "ref": "literal", "value": 0,
                     }}},
                    {"operator": "percentage", "operands": [
                        {"ref": "derived.current", "index": 0},
                        {"ref": "orders.total_count"},
                    ], "result_kind": "percentage", "precision": 2, "show_work": True},
                ]
                payload = {
                    "mode": "inspect", "domain": "orders", "objective": message,
                    "intent_kind": "data_read", "request_shape": "focused_analysis",
                    "requested_fields": ["calculation", "count", "ratio"],
                    "direct_output_fields": [], "entity": "order", "metric": "derived",
                    "status_scope": "all", "record_scope": "all_matching",
                    "period": "all", "freshness": "local_snapshot",
                    "information_source": "local_business_data",
                    "operation_policy": "existing_observations_only",
                    "comparison_policy": policy,
                    "calculation_count": 3, "calculation_grouping": "sequential_results",
                    "derived_calculations": formulas,
                    "requires_clarification": False, "clarification": "",
                }
                prompts: list[str] = []

                def planner(prompt: str, **_kwargs: object) -> str:
                    prompts.append(prompt)
                    if repair_formula:
                        if len(prompts) == 1:
                            malformed = json.loads(json.dumps(payload))
                            if repair_formula == "invalid":
                                malformed["derived_calculations"][0]["operator"] = "invalid"
                            else:
                                malformed["derived_calculation"] = malformed.pop(
                                    "derived_calculations"
                                )[0]
                                if repair_formula == "missing_count_one":
                                    malformed["calculation_count"] = 1
                            return json.dumps(malformed, ensure_ascii=False)
                        self.assertIn('"comparison_required": false', prompt)
                        if repair_formula == "short_repair":
                            return json.dumps({"derived_calculations": formulas[:1]})
                        return json.dumps({"derived_calculations": formulas})
                    return json.dumps(payload, ensure_ascii=False)

                interpreted = task_runtime.interpret_agent_turn(
                    message, planner_client=planner, session_state=state,
                )
                if repair_formula == "short_repair":
                    self.assertFalse(interpreted.success)
                    self.assertIn("sequential_calculation_count_missing", str(interpreted.data))
                    self.assertEqual(len(prompts), 2)
                    continue
                self.assertTrue(interpreted.success, interpreted.data)
                self.assertEqual(len(prompts), 2 if repair_formula else 1)
                interpretation = dict(interpreted.data or {})
                self.assertEqual(interpretation["comparison_policy_source"], "model_authored")
                self.assertEqual(interpretation["comparison_policy"], policy)
                self.assertNotIn("derived_comparison_repair", interpretation)
                contract = interpretation["semantic_contract"]
                self.assertNotIn("action_intent", contract)
                self.assertNotIn("required_operation_ids", contract)
                normalized = contract["derived_calculations"]
                self.assertEqual(bool(normalized[1].get("comparison")), policy == "required")
                state.active_entities["turn_interpretation"] = interpretation
                projected = task_runtime.run_existing_observation_read_turn(
                    message, interpretation=interpretation, session_state=state,
                )
                self.assertTrue(projected.success, projected.data)
                answer = str((projected.data or {}).get("answer") or "")
                self.assertIn("86 siparis + 13 siparis = 99 adet", answer)
                self.assertIn("25 siparis - 99 adet = -74 adet", answer)
                self.assertIn("99 adet / 570 siparis", answer)
                self.assertIn("17.37 %", answer)
                self.assertEqual((projected.data or {}).get("tool_calls"), [])
                for sign in ("", "+"):
                    corrupted = response_verifier.verify_response_projection(
                        answer.replace("-74", f"{sign}74"), state,
                    )
                    self.assertFalse(corrupted.success, corrupted.data)
                unicode_minus = response_verifier.verify_response_projection(
                    answer.replace("-74", "−74"), state,
                )
                self.assertTrue(unicode_minus.success, unicode_minus.data)

    def test_r450_numeric_grounding_keeps_signs_in_locale_amounts(self) -> None:
        for source, rendered in [
            (-1234.5, "-1.234,50"),
            (-1234.5, "−1,234.50"),
            (-1234, "-1.234"),
            (1234.5, "+1.234,50"),
        ]:
            with self.subTest(source=source, rendered=rendered):
                tokens = response_verifier._answer_numeric_tokens(f"Tutar: {rendered} TRY")
                self.assertEqual(tokens, [rendered])
                expected = response_verifier._numeric_token_equivalents(source)
                actual = response_verifier._numeric_token_equivalents(tokens[0])
                self.assertTrue(actual.intersection(expected))
                self.assertFalse(actual.intersection(
                    response_verifier._numeric_token_equivalents(-source)
                ))
        self.assertEqual(
            response_verifier._answer_numeric_tokens("25 - 99 = -74; 25-99; 2026-09-05"),
            ["25", "99", "-74", "25", "99", "2026", "09", "05"],
        )


    def _r456_prior_calculation_state(self) -> AgentSessionState:
        state = AgentSessionState(goal="Yerel durum dağılımı", active_domain="orders", status="complete")
        state.completed_steps = [AgentTaskStep(
            index=1, step_id="summary", prompt=state.goal, operation_domain="orders",
            status="completed", tool_names=["orders.summary"], result_data={"tool_result": {
                "tool": "orders.summary", "total_orders": 570,
                "status_counts": {"Cancelled": 86, "UnDeliveredAndReturned": 13, "Delivered": 25},
            }},
        )]
        formulas = [
            {"operator": "add", "operands": [
                {"ref": "orders.status_count", "member": "Cancelled"},
                {"ref": "orders.status_count", "member": "UnDeliveredAndReturned"},
            ], "result_kind": "count", "precision": 0, "show_work": True},
            {"operator": "subtract", "operands": [
                {"ref": "orders.status_count", "member": "Delivered"},
                {"ref": "derived.current", "index": 0},
            ], "result_kind": "count", "precision": 0, "show_work": True},
            {"operator": "percentage", "operands": [
                {"ref": "derived.current", "index": 0}, {"ref": "orders.total_count"},
            ], "result_kind": "percentage", "precision": 2, "show_work": True},
        ]
        interpretation = {
            "domain": "orders", "mode": "inspect", "intent_kind": "data_read",
            "requested_fields": ["calculation"], "direct_output_fields": [],
            "operation_policy": "existing_observations_only",
            "semantic_contract": {"entity": "order", "metric": "derived",
                "derived_calculations": formulas, "calculation_count": 3,
                "calculation_grouping": "sequential_results", "projection": ["calculation"]},
        }
        result = task_runtime.run_existing_observation_read_turn(
            "Önceki dağılımdan üç hesabı yap", interpretation=interpretation, session_state=state,
        )
        self.assertTrue(result.success, result.data)
        restored = AgentSessionState.from_dict(result.data["session_state"])
        self.assertEqual(len(restored.observations), 3)
        return restored

    def test_r456_prior_result_comparisons_use_core_and_preserve_numeric_history(self) -> None:
        for operator, expected in [
            ("less_than", True), ("less_or_equal", True), ("greater_than", False),
            ("greater_or_equal", False), ("equal", False), ("not_equal", True),
        ]:
            with self.subTest(operator=operator):
                state = self._r456_prior_calculation_state()
                message = "Önceki negatif sonucun 0 ile ilişkisini göster; yeni veri çekmeden yanıtla."
                payload = {
                    "mode": "inspect", "domain": "orders", "objective": message,
                    "intent_kind": "data_read", "request_shape": "focused_analysis",
                    "requested_fields": ["calculation"], "direct_output_fields": [],
                    "entity": "order", "metric": "derived", "record_scope": "all_matching",
                    "operation_policy": "existing_observations_only", "comparison_policy": "required",
                    "calculation_count": 1, "calculation_grouping": "single_result",
                    "derived_calculation": {"operator": operator, "operands": [
                        {"ref": "derived.recent", "offset": 1}, {"ref": "literal", "value": 0},
                    ], "result_kind": "scalar", "precision": 0, "show_work": True,
                        "comparison": {"operator": operator, "operand": {"ref": "literal", "value": 0}}},
                    "requires_clarification": False, "clarification": "",
                }
                prompts = []
                def planner(prompt: str, **_kwargs: object) -> str:
                    prompts.append(prompt)
                    return json.dumps(payload, ensure_ascii=False)
                interpreted = task_runtime.interpret_agent_turn(message, planner_client=planner, session_state=state)
                self.assertTrue(interpreted.success, interpreted.data)
                self.assertEqual(len(prompts), 1)
                contract = interpreted.data["semantic_contract"]["derived_calculation"]
                self.assertEqual(contract["operator"], operator)
                self.assertEqual(contract["result_kind"], "boolean")
                self.assertNotIn("comparison", contract)
                projected = task_runtime.run_existing_observation_read_turn(
                    message, interpretation=interpreted.data, session_state=state,
                )
                self.assertTrue(projected.success, projected.data.get("response_verification"))
                self.assertEqual(projected.data.get("tool_names"), [])
                answer = projected.data["answer"]
                self.assertIn("25 siparis - 99 adet = -74 adet", answer)
                state = AgentSessionState.from_dict(projected.data["session_state"])
                last = state.observations[-1]
                self.assertEqual(last.operation_name, "core.verified_comparison")
                proof = last.aggregates["verified_comparison"]
                self.assertIs(proof["result"], expected)
                self.assertTrue(proof["operand_evidence_hashes"][0])
                self.assertNotIn("arithmetic_evidence_hash", proof)
                recent = response_verifier._recent_verified_calculations(state)
                self.assertEqual([row["result"] for row in recent], ["17.37", "-74", "99"])
                bad_truth = answer.replace("Doğru" if expected else "Yanlış", "Yanlış" if expected else "Doğru")
                self.assertFalse(response_verifier.verify_response_projection(bad_truth, state).success)
                self.assertFalse(response_verifier.verify_response_projection(answer.replace("-74", "+74"), state).success)

    def test_r456_multiple_comparisons_bind_each_truth_and_reject_boolean_arithmetic(self) -> None:
        state = self._r456_prior_calculation_state()
        message = "Önceki negatif sonuç 0'dan küçük mü, büyük mü? İki ilişkiyi de göster."
        formulas = [{"operator": operator, "operands": [
            {"ref": "derived.recent", "offset": 1}, {"ref": "literal", "value": 0},
        ], "result_kind": "boolean", "precision": 0, "show_work": True}
            for operator in ("less_than", "greater_than")]
        interpretation = {
            "mode": "inspect", "domain": "orders", "intent_kind": "data_read",
            "requested_fields": ["calculation"], "direct_output_fields": [],
            "operation_policy": "existing_observations_only", "comparison_policy": "required",
            "semantic_contract": {"entity": "order", "metric": "derived",
                "derived_calculations": formulas, "calculation_count": 2,
                "calculation_grouping": "sequential_results", "projection": ["calculation"]},
        }
        projected = task_runtime.run_existing_observation_read_turn(
            message, interpretation=interpretation, session_state=state,
        )
        self.assertTrue(projected.success, projected.data.get("response_verification"))
        answer = projected.data["answer"]
        self.assertIn("-74 < 0 → Doğru", answer)
        self.assertIn("-74 > 0 → Yanlış", answer)
        state = AgentSessionState.from_dict(projected.data["session_state"])
        self.assertEqual([row["result"] for row in response_verifier._recent_verified_calculations(state)],
            ["17.37", "-74", "99"])
        self.assertEqual(len([row for row in state.observations
            if row.operation_name == "core.verified_comparison"]), 2)
        swapped = answer.replace("Doğru", "SWAP").replace("Yanlış", "Doğru").replace("SWAP", "Yanlış")
        self.assertFalse(response_verifier.verify_response_projection(swapped, state).success)
        self.assertFalse(response_verifier.verify_response_projection(
            answer.replace("Doğru", "Doğru değil"), state,
        ).success)
        proof = state.observations[-1].aggregates["verified_comparison"]
        self.assertEqual(response_verifier._verified_derived_calculation_from_contract(
            state, {"operator": "add", "operands": [
                {"ref": "derived.current", "index": 0}, {"ref": "literal", "value": 0},
            ], "result_kind": "scalar", "precision": 0}, current_calculations=[proof],
        ), {})
        for policy in ("prohibited", "not_requested"):
            with self.subTest(policy=policy):
                errors = []
                self.assertEqual(task_runtime._normalize_derived_calculation(
                    formulas[0], domain="orders", message=message, comparison_policy=policy,
                    validation_errors=errors,
                ), {})
                self.assertTrue(errors)

    def test_r458_singleton_transport_and_relation_repair_share_one_contract(self) -> None:
        message = "Önceki negatif fark 0'dan küçük mü? Yeni veri çekmeden göster."
        relation = {"operator": "less_than", "operands": [
            {"ref": "derived.recent", "offset": 1}, {"ref": "literal", "value": 0},
        ], "result_kind": "boolean", "precision": 0, "show_work": True}
        initial = {
            "mode": "inspect", "domain": "orders", "objective": message,
            "intent_kind": "data_read", "request_shape": "focused_analysis",
            "requested_fields": ["calculation"], "entity": "order", "metric": "derived",
            "operation_policy": "existing_observations_only", "comparison_policy": "required",
            "calculation_count": 1, "calculation_grouping": "single_result",
            "derived_calculations": [relation],
            "requires_clarification": False, "clarification": "",
        }
        for repair_kind in ("unneeded", "valid", "single_repair", "conflicting_relation", "missing_relation"):
            with self.subTest(repair_kind=repair_kind):
                state = self._r456_prior_calculation_state()
                first = json.loads(json.dumps(initial))
                repaired_relation = json.loads(json.dumps(relation))
                if repair_kind != "unneeded":
                    first["calculation_grouping"] = "sequential_results"
                if repair_kind == "single_repair":
                    first["calculation_grouping"] = "single_result"
                    first["derived_calculation"] = first.pop("derived_calculations")[0]
                    first["derived_calculation"]["operator"] = "unknown_relation"
                if repair_kind == "conflicting_relation":
                    repaired_relation["comparison"] = {"operator": "less_than", "operand": {
                        "ref": "derived.recent", "offset": 1,
                    }}
                if repair_kind == "missing_relation":
                    repaired_relation.update(operator="subtract", result_kind="scalar")
                repair = {"derived_calculations": [repaired_relation],
                    "result_contract_revision": {"calculation_count": 1,
                        "calculation_grouping": "single_result", "reason": "Önceki sonuç üzerinde tek ilişki."}}
                responses = iter([first, repaired_relation if repair_kind == "single_repair" else repair])
                prompts = []
                def planner(prompt: str) -> str:
                    prompts.append(prompt)
                    return json.dumps(next(responses), ensure_ascii=False)
                with patch.object(task_runtime, "invoke_provider_planner", wraps=task_runtime.invoke_provider_planner) as calls:
                    interpreted = task_runtime.interpret_agent_turn(
                        message, session_state=state, planner_client=planner,
                    )
                self.assertEqual(len(prompts), 1 if repair_kind == "unneeded" else 2)
                if repair_kind == "conflicting_relation":
                    self.assertFalse(interpreted.success)
                    self.assertIn("standalone_comparison_contract_conflict", str(interpreted.data))
                elif repair_kind == "missing_relation":
                    self.assertFalse(interpreted.success)
                    self.assertIn("comparison_contract_missing", str(interpreted.data))
                else:
                    self.assertTrue(interpreted.success, interpreted.data)
                    projected = task_runtime.run_existing_observation_read_turn(
                        message, interpretation=interpreted.data, session_state=state,
                    )
                    self.assertTrue(projected.success, projected.data.get("response_verification"))
                    self.assertIn("-74 < 0 → Doğru", projected.data["answer"])
                    self.assertEqual(projected.data["tool_names"], [])
                if repair_kind != "unneeded":
                    schema = calls.call_args_list[-1].kwargs["response_schema"]
                    item_schema = (schema if repair_kind == "single_repair"
                        else schema["properties"]["derived_calculations"]["items"])
                    self.assertNotIn("comparison", item_schema["required"])
                    self.assertIn("nested comparison ekleme", prompts[-1])

    def test_r458_singleton_does_not_hide_missing_independent_results(self) -> None:
        message = "Önceki negatif fark 0'dan küçük mü ve 0'dan büyük mü? İki ilişkiyi de göster."
        formulas = [{"operator": operator, "operands": [
            {"ref": "derived.recent", "offset": 1}, {"ref": "literal", "value": 0},
        ], "result_kind": "boolean", "precision": 0, "show_work": True}
            for operator in ("less_than", "greater_than")]
        initial = {"mode": "inspect", "domain": "orders", "objective": message,
            "intent_kind": "data_read", "request_shape": "focused_analysis",
            "requested_fields": ["calculation"], "entity": "order", "metric": "derived",
            "operation_policy": "existing_observations_only", "comparison_policy": "required",
            "calculation_count": 2, "calculation_grouping": "independent_results",
            "derived_calculations": formulas[:1], "requires_clarification": False, "clarification": ""}
        for repair_count in (1, 2):
            with self.subTest(repair_count=repair_count):
                state = self._r456_prior_calculation_state()
                responses = iter([initial, {"derived_calculations": formulas[:repair_count]}])
                interpreted = task_runtime.interpret_agent_turn(
                    message, session_state=state,
                    planner_client=lambda *_args: json.dumps(next(responses), ensure_ascii=False),
                )
                if repair_count == 1:
                    self.assertFalse(interpreted.success)
                    self.assertIn("declared_calculation_count_missing:1:2", str(interpreted.data))
                else:
                    self.assertTrue(interpreted.success, interpreted.data)
                    projected = task_runtime.run_existing_observation_read_turn(
                        message, interpretation=interpreted.data, session_state=state,
                    )
                    self.assertTrue(projected.success, projected.data.get("response_verification"))
                    self.assertIn("-74 < 0 → Doğru", projected.data["answer"])
                    self.assertIn("-74 > 0 → Yanlış", projected.data["answer"])

    def test_r460_percentage_display_does_not_rewrite_division_after_boolean_result(self) -> None:
        message = "Şimdi karşılaştırmadan önce bulduğun yüzde sonucunu 2'ye böl ve üç ondalıkla işlem adımını göster. Yeni veri çekme; başka karşılaştırma ekleme."
        for operator, repaired in (("divide", False), ("divide", True), ("percentage", False), ("percentage", True)):
            with self.subTest(operator=operator, repaired=repaired):
                state = self._r456_prior_calculation_state()
                comparison = task_runtime.run_existing_observation_read_turn(
                    "Önceki negatif fark 0'dan küçük mü?",
                    interpretation={"domain": "orders", "mode": "inspect", "intent_kind": "data_read",
                        "requested_fields": ["calculation"], "operation_policy": "existing_observations_only",
                        "semantic_contract": {"entity": "order", "metric": "derived", "projection": ["calculation"],
                            "derived_calculation": {"operator": "less_than", "operands": [
                                {"ref": "derived.recent", "offset": 1}, {"ref": "literal", "value": 0},
                            ], "result_kind": "boolean", "precision": 0, "show_work": True}}},
                    session_state=state,
                )
                self.assertTrue(comparison.success, comparison.message)
                state = AgentSessionState.from_dict(comparison.data["session_state"])
                formula = {"operator": operator, "operands": [
                    {"ref": "derived.recent", "offset": 0}, {"ref": "literal", "value": 2},
                ], "result_kind": "percentage", "precision": 3, "show_work": True}
                initial_formula = {**formula, "operator": "half" if repaired else operator}
                payload = {"mode": "inspect", "domain": "orders", "objective": message,
                    "intent_kind": "data_read", "request_shape": "focused_analysis", "entity": "order",
                    "metric": "derived", "requested_fields": ["calculation", "ratio"],
                    "direct_output_fields": [], "operation_policy": "existing_observations_only",
                    "comparison_policy": "prohibited", "calculation_count": 1,
                    "calculation_grouping": "single_result", "derived_calculation": initial_formula,
                    "requires_clarification": False, "clarification": ""}
                responses = iter([payload, formula])
                interpreted = task_runtime.interpret_agent_turn(message, session_state=state,
                    planner_client=lambda *_args: json.dumps(next(responses), ensure_ascii=False))
                self.assertTrue(interpreted.success, interpreted.data)
                contract = interpreted.data["semantic_contract"]["derived_calculation"]
                provenance = interpreted.data["formula_contract_provenance"]
                self.assertEqual(provenance["accepted"], [{"operator": operator, "result_kind": "percentage"}])
                self.assertIs(provenance["formula_repair_invoked"], repaired)
                if not repaired:
                    self.assertEqual(provenance["initial"], provenance["accepted"])
                projected = task_runtime.run_existing_observation_read_turn(
                    message, interpretation=interpreted.data, session_state=state,
                )
                self.assertTrue(projected.success, projected.data.get("response_verification"))
                self.assertEqual(projected.data["tool_names"], [])
                self.assertIn("17.37 % / 2 = 8.685 %", projected.data["answer"])
                self.assertNotIn("× 100", projected.data["answer"])
                restored = AgentSessionState.from_dict(projected.data["session_state"])
                proof = restored.observations[-1].aggregates["verified_calculation"]
                self.assertEqual(proof["operator"], operator)
                self.assertEqual(proof["result"], "8.685")
                self.assertTrue(proof["operand_evidence_hashes"][0])
                scalar = response_verifier._verified_derived_calculation_from_contract(
                    state, {**contract, "result_kind": "scalar"},
                )
                self.assertEqual(scalar["result"], "0.087")
                self.assertEqual(proof["quantity_scaling"]["display_result_multiplier"], "1")
                self.assertNotEqual(proof["arithmetic_evidence_hash"], scalar["arithmetic_evidence_hash"])
                self.assertNotEqual(proof["evidence_hash"], scalar["evidence_hash"])
                self.assertFalse(response_verifier.verify_response_projection(
                    projected.data["answer"].replace("8.685", "868.500"), restored,
                ).success)

    def test_r456_repair_retains_primary_formula_error_before_revision_metadata(self) -> None:
        state = self._r456_prior_calculation_state()
        message = "Bu kez karşılaştırma istiyorum: negatif adet farkı 0'dan küçük mü? Yeni veri çekmeden söyle."
        first = {
            "mode": "inspect", "domain": "orders", "objective": message,
            "intent_kind": "data_read", "request_shape": "focused_analysis",
            "requested_fields": ["calculation"], "entity": "order", "metric": "derived",
            "operation_policy": "existing_observations_only", "comparison_policy": "required",
            "calculation_count": 1, "calculation_grouping": "sequential_results",
            "derived_calculations": [{"operator": "subtract", "operands": [
                {"ref": "orders.status_count", "member": "Delivered"},
                {"ref": "derived.current", "index": 0},
            ], "result_kind": "count", "precision": 0, "show_work": True}],
            "requires_clarification": False, "clarification": "",
        }
        for repair_operator in ("less_than", "unknown_relation"):
            with self.subTest(repair_operator=repair_operator):
                repair = {"derived_calculations": [{
                    "operator": repair_operator, "operands": [
                        {"ref": "derived.recent", "offset": 1}, {"ref": "literal", "value": 0},
                    ], "result_kind": "scalar", "precision": 0, "show_work": True,
                }], "result_contract_revision": {"calculation_count": 1,
                    "calculation_grouping": "single_result", "reason": "Önceki sonuç üzerinde tek karşılaştırma."}}
                responses = iter([first, repair])
                interpreted = task_runtime.interpret_agent_turn(
                    message, session_state=state,
                    planner_client=lambda *_args, **_kwargs: json.dumps(next(responses), ensure_ascii=False),
                )
                if repair_operator == "unknown_relation":
                    self.assertFalse(interpreted.success)
                    self.assertIn("operator_not_allowed:unknown_relation", str(interpreted.data))
                    self.assertNotIn("result_contract_revision_invalid", str(interpreted.data))
                else:
                    self.assertTrue(interpreted.success, interpreted.data)
                    projected = task_runtime.run_existing_observation_read_turn(
                        message, interpretation=interpreted.data, session_state=state,
                    )
                    self.assertTrue(projected.success, projected.data.get("response_verification"))
                    self.assertIn("-74 < 0", projected.data["answer"])


